    private enum class RecoverableRetryMode {
        NONE,
        WAITING,
        READY,
        EXHAUSTED
    }

    private data class RecoverableRetryDecision(
        val mode: RecoverableRetryMode,
        val consecutiveFailures: Int = 0,
        val retryAt: Long? = null
    ) {
        val canAutoRetry: Boolean
            get() = mode == RecoverableRetryMode.WAITING || mode == RecoverableRetryMode.READY
    }

    init {
        liveServicesForTesting += this
        // Runtime state is persisted across app-server restarts. Reattach loops eagerly
        // on service startup so companies keep progressing even before the UI polls.
        if (autoStartAutomationRefresh) {
            queueAutomationRefresh()
        }
    }

    fun shutdown() {
        runBlocking {
            serviceScope.cancel("DesktopAppService shutdown")
            val jobsToJoin = synchronized(runtimeLifecycleLock) {
                buildList {
                    addAll(activeTaskJobs.values.filterNotNull())
                    addAll(companyRuntimeJobs.values.filterNotNull())
                    addAll(automationRefreshJobs.values.filterNotNull())
                }.distinct()
            }.distinct()
            jobsToJoin.forEach { it.cancel() }
            withTimeoutOrNull(SHUTDOWN_JOIN_TIMEOUT_MS) {
                jobsToJoin.forEach { it.cancelAndJoin() }
            }
            withTimeoutOrNull(SHUTDOWN_JOIN_TIMEOUT_MS) {
                interruptActiveTasksForShutdown()
            }
        }
        synchronized(runtimeLifecycleLock) {
            activeTaskJobs.clear()
            companyRuntimeJobs.clear()
            companyRuntimeTickMutexes.clear()
            companyRuntimeWakeSignals.clear()
            automationRefreshJobs.clear()
        }
        intentionallyInterruptedTaskIds.clear()
        recentCompanyAutomationTraceKeys.clear()
        recentSupersededPullRequestCleanupAt.clear()
        recentNoOpPullRequestRefreshAt.clear()
        recentPullRequestMetadataRefreshes.clear()
        recentAgentModelDiscoveries.clear()
        codexAppServerManager.stopAll()
        serviceScope.cancel()
        liveServicesForTesting -= this
    }

    internal fun primeRuntimeCachesForTesting(companyId: String, taskId: String) {
        companyRuntimeTickMutexes[companyId] = Mutex()
        companyRuntimeWakeSignals[companyId] = MutableSharedFlow(extraBufferCapacity = 1)
        companyRuntimeJobs[companyId] = serviceScope.launch(start = CoroutineStart.UNDISPATCHED) { delay(Long.MAX_VALUE) }
        automationRefreshJobs[companyId] = serviceScope.launch(start = CoroutineStart.UNDISPATCHED) { delay(Long.MAX_VALUE) }
        activeTaskJobs[taskId] = serviceScope.launch(start = CoroutineStart.UNDISPATCHED) { delay(Long.MAX_VALUE) }
        intentionallyInterruptedTaskIds += taskId
        recentCompanyAutomationTraceKeys["company:$companyId"] = System.currentTimeMillis()
        recentSupersededPullRequestCleanupAt[companyId] = System.currentTimeMillis()
    }

    internal fun runtimeCacheSizesForTesting(): Map<String, Int> = mapOf(
        "tickMutexes" to companyRuntimeTickMutexes.size,
        "wakeSignals" to companyRuntimeWakeSignals.size,
        "runtimeJobs" to companyRuntimeJobs.size,
        "refreshJobs" to automationRefreshJobs.size,
        "activeTaskJobs" to activeTaskJobs.size,
        "interruptedTaskIds" to intentionallyInterruptedTaskIds.size,
        "traceKeys" to recentCompanyAutomationTraceKeys.size,
        "supersededPrTimestamps" to recentSupersededPullRequestCleanupAt.size,
        "pullRequestMetadataRefreshes" to recentPullRequestMetadataRefreshes.size,
        "agentModelDiscoveries" to recentAgentModelDiscoveries.size
    )

    private fun pruneRuntimeCaches(now: Long = System.currentTimeMillis()) {
        recentCompanyAutomationTraceKeys.entries.removeIf { now - it.value > COMPANY_TRACE_DEDUP_WINDOW_MS }
        recentSupersededPullRequestCleanupAt.entries.removeIf { now - it.value > SUPERSEDED_PR_RECONCILIATION_INTERVAL_MS * 2 }
        recentNoOpPullRequestRefreshAt.entries.removeIf { now - it.value > NO_OP_PR_REUSE_REFRESH_INTERVAL_MS * 2 }
        recentPullRequestMetadataRefreshes.entries.removeIf { now - it.value.refreshedAt > PR_METADATA_REFRESH_CACHE_MS * 2 }
        recentAgentModelDiscoveries.entries.removeIf { now - it.value.discoveredAt > AGENT_MODEL_DISCOVERY_CACHE_MS * 2 }
    }

    suspend fun dashboard(): DashboardResponse {
        pruneRuntimeCaches()
        // Every dashboard read is also a chance to heal background loops after an app-server
        // restart. The read path stays cheap, but it nudges the automation layer back into the
        // expected steady state before serializing the full desktop snapshot.
        queueAutomationRefresh()
        migrateLegacyOpenCodeCompanyAgentModels()
        val state = stateStore.load().withDerivedMetrics()
        val orgProfiles = ensureOrgProfiles(state.orgProfiles, state.companyAgentDefinitions, state.companies)
        val boundIssuesById = mutableMapOf<String, CompanyIssue>()
        val boundReviewQueueById = mutableMapOf<String, ReviewQueueItem>()
        val boundRuntimesByCompanyId = mutableMapOf<String?, CompanyRuntimeSnapshot>()
        state.companies.forEach { company ->
            val runtime = state.companyRuntimes.firstOrNull { it.companyId == company.id } ?: CompanyRuntimeSnapshot(companyId = company.id)
            val bound = runtimeBindingService.bind(state, company.id, runtime)
            bound.issues.forEach { boundIssuesById[it.id] = it }
            bound.reviewQueue.forEach { boundReviewQueueById[it.id] = it }
            boundRuntimesByCompanyId[company.id] = bound.runtime
        }
        return DashboardResponse(
            repositories = state.repositories.sortedByDescending { it.updatedAt },
            workspaces = state.workspaces.sortedByDescending { it.updatedAt },
            tasks = state.tasks.sortedByDescending { it.createdAt },
            settings = settings(),
            companies = state.companies.sortedByDescending { it.updatedAt },
            companyAgentDefinitions = state.companyAgentDefinitions
                .sortedWith(compareBy<CompanyAgentDefinition> { it.displayOrder }.thenBy { it.title.lowercase() }),
            agentCapabilityProfiles = state.agentCapabilityProfiles
                .sortedWith(compareBy<AgentCapabilityProfile> { it.companyId }.thenBy { it.agentId }),
            projectContexts = state.projectContexts.sortedByDescending { it.lastUpdatedAt },
            goals = state.goals.sortedByDescending { it.updatedAt },
            issues = state.issues
                .map { issue -> boundIssuesById[issue.id] ?: issue }
                .sortedByDescending { it.updatedAt },
            reviewQueue = state.reviewQueue
                .map { item -> boundReviewQueueById[item.id] ?: item }
                .sortedByDescending { it.updatedAt },
            orgProfiles = orgProfiles,
            workflowTopologies = computeWorkflowTopologies(state, orgProfiles),
            goalDecisions = state.goalDecisions.sortedByDescending { it.createdAt },
            runningAgentSessions = computeRunningAgentSessions(state, orgProfiles),
            backendStatuses = computeBackendStatuses(state),
            opsMetrics = state.opsMetrics,
            activity = state.companyActivity.sortedByDescending { it.createdAt },
            companyRuntimes = state.companyRuntimes
                .map { runtime -> boundRuntimesByCompanyId[runtime.companyId] ?: runtime }
                .sortedByDescending { it.lastTickAt ?: 0L },
            agentContextEntries = state.agentContextEntries.sortedByDescending { it.createdAt },
            agentMessages = state.agentMessages.sortedByDescending { it.createdAt },
            marketingDelegationPolicies = CompanyMarketingDashboardProjection.policies(state),
            marketingRuns = CompanyMarketingDashboardProjection.runs(state),
            skillRuns = state.skillRuns.sortedByDescending { it.updatedAt },
            agentPerformance = computeAgentPerformance(state, companyId = null, orgProfiles = orgProfiles)
        ).redactedForApi()
    }

    suspend fun companyDashboard(companyId: String? = null): CompanyDashboardResponse {
        return companyDashboardPrepared(companyId)
    }

    suspend fun companyDashboardPrepared(companyId: String? = null): CompanyDashboardResponse {
        if (companyId == null) {
            migrateLegacyCompanyRosters(companyId)
            queueAutomationRefresh(companyId)
        } else {
            prepareCompanyAutomationState(companyId)
        }
        val state = stateStore.load().withDerivedMetrics()
        return companyDashboardSnapshot(state, companyId).redactedForApi()
    }

    suspend fun companyDashboardReadOnly(companyId: String? = null): CompanyDashboardResponse {
        val state = stateStore.load().withDerivedMetrics()
        return companyDashboardSnapshot(state, companyId).redactedForApi()
    }

    suspend fun agentPerformance(companyId: String): List<AgentPerformanceSnapshot> {
        val state = stateStore.load().withDerivedMetrics()
        val orgProfiles = ensureOrgProfiles(state.orgProfiles, state.companyAgentDefinitions, state.companies)
        return computeAgentPerformance(state, companyId, orgProfiles)
    }

    suspend fun listMorningReports(companyId: String): List<CompanyDailyReportSummary> {
        ensureMorningReport(companyId)
        return withContext(Dispatchers.IO) {
            val dir = companyReportsDir(companyId)
            if (!Files.exists(dir)) {
                return@withContext emptyList()
            }
            val reports = mutableListOf<CompanyDailyReportSummary>()
            Files.list(dir).use { stream ->
                stream
                    .filter { path -> path.fileName.toString().endsWith(".json") }
                    .forEach { path ->
                        readMorningReportFile(path)?.toSummary()?.let { reports += it }
                    }
            }
            reports.sortedWith(
                compareByDescending<CompanyDailyReportSummary> { it.date }
                    .thenByDescending { it.generatedAt }
            )
        }
    }

    suspend fun morningReport(companyId: String, date: String): CompanyDailyReport {
        val parsedDate = parseMorningReportDate(date)
        val existing = withContext(Dispatchers.IO) {
            readMorningReportFile(companyReportPath(companyId, parsedDate))
        }
        return existing ?: generateMorningReport(companyId, parsedDate.toString())
    }

    suspend fun generateMorningReport(companyId: String, date: String? = null): CompanyDailyReport =
        generateMorningReport(companyId, date, System.currentTimeMillis())

    private suspend fun generateMorningReport(
        companyId: String,
        date: String?,
        generatedAt: Long
    ): CompanyDailyReport {
        val reportDate = date?.let(::parseMorningReportDate) ?: previousMorningReportDate(generatedAt)
        val state = stateStore.load().withDerivedMetrics()
        val company = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val report = buildMorningReport(state, company, reportDate, generatedAt)
        writeMorningReport(report)
        return report
    }

    private suspend fun ensureMorningReport(
        companyId: String,
        nowMillis: Long = System.currentTimeMillis()
    ): CompanyDailyReport? {
        val state = stateStore.load()
        if (state.companies.none { it.id == companyId }) {
            throw IllegalArgumentException("Company not found: $companyId")
        }
        val reportDate = previousMorningReportDate(nowMillis)
        val path = companyReportPath(companyId, reportDate)
        val existing = withContext(Dispatchers.IO) { readMorningReportFile(path) }
        return existing ?: generateMorningReport(companyId, reportDate.toString(), nowMillis)
    }

    private fun buildMorningReport(
        state: DesktopAppState,
        company: Company,
        reportDate: LocalDate,
        generatedAt: Long
    ): CompanyDailyReport {
        val (periodStart, periodEnd) = morningReportPeriod(reportDate)
        fun inPeriod(timestamp: Long?): Boolean = timestamp != null && timestamp >= periodStart && timestamp < periodEnd

        val companyId = company.id
        val goalsById = state.goals.associateBy { it.id }
        val companyIssues = state.issues.filter { it.companyId == companyId }
        val companyIssueIds = companyIssues.map { it.id }.toSet()
        val issuesById = companyIssues.associateBy { it.id }
        val companyTasks = state.tasks.filter { task -> task.issueId?.let { it in companyIssueIds } == true }
        val companyTaskIds = companyTasks.map { it.id }.toSet()
        val companyRuns = state.runs.filter { it.taskId in companyTaskIds }
        val periodRuns = companyRuns.filter { inPeriod(it.updatedAt) || inPeriod(it.createdAt) }
        val periodIssues = companyIssues.filter { inPeriod(it.updatedAt) || inPeriod(it.createdAt) }
        val periodActivities = state.companyActivity
            .filter { it.companyId == companyId && inPeriod(it.createdAt) }
            .sortedByDescending { it.createdAt }
        val periodReviewQueue = state.reviewQueue
            .filter { item ->
                (item.companyId == companyId || item.issueId in companyIssueIds) &&
                    (
                        inPeriod(item.updatedAt) || inPeriod(item.createdAt) || inPeriod(item.qaReviewedAt) ||
                            inPeriod(item.ceoReviewedAt) || inPeriod(item.mergedAt)
                        )
            }
            .sortedByDescending { it.updatedAt }

        val completedItems = periodIssues
            .filter { it.status == IssueStatus.DONE && inPeriod(it.updatedAt) }
            .sortedByDescending { it.updatedAt }
            .map { issue ->
                issue.toReportItem(
                    goalsById = goalsById,
                    status = "DONE",
                    severity = "success",
                    timestamp = issue.updatedAt
                )
            }

        val pullRequests = periodReviewQueue
            .filter { !it.pullRequestUrl.isNullOrBlank() }
            .map { item ->
                val issue = issuesById[item.issueId]
                CompanyDailyReportItem(
                    id = "pr-${item.id}",
                    title = issue?.title ?: "Pull request ${item.pullRequestNumber ?: item.id}",
                    detail = listOfNotNull(
                        item.pullRequestNumber?.let { "#$it" },
                        item.pullRequestState,
                        item.checksSummary,
                        item.mergeability
                    ).joinToString(" · ").ifBlank { null },
                    issueId = item.issueId,
                    goalId = issue?.goalId,
                    runId = item.runId,
                    pullRequestUrl = item.pullRequestUrl,
                    status = if (item.status == ReviewQueueStatus.MERGED) "MERGED" else item.status.name,
                    severity = if (item.status == ReviewQueueStatus.MERGED) "success" else "info",
                    timestamp = item.mergedAt ?: item.updatedAt
                )
            }

        val reviewItems = periodReviewQueue
            .map { item ->
                val issue = issuesById[item.issueId]
                val reportStatus = when {
                    item.qaVerdict.equals("PASS", ignoreCase = true) -> "QA_PASS"
                    item.qaVerdict.equals("CHANGES_REQUESTED", ignoreCase = true) ||
                        item.ceoVerdict.equals("CHANGES_REQUESTED", ignoreCase = true) ||
                        item.status == ReviewQueueStatus.CHANGES_REQUESTED -> "CHANGES_REQUESTED"
                    item.status == ReviewQueueStatus.MERGED -> "MERGED"
                    else -> item.status.name
                }
                CompanyDailyReportItem(
                    id = "review-${item.id}",
                    title = issue?.title ?: "Review ${item.id}",
                    detail = listOfNotNull(
                        item.qaVerdict?.let { "QA $it" },
                        item.ceoVerdict?.let { "CEO $it" },
                        item.checksSummary,
                        item.mergeability
                    ).joinToString(" · ").ifBlank { null },
                    issueId = item.issueId,
                    goalId = issue?.goalId,
                    runId = item.runId,
                    pullRequestUrl = item.pullRequestUrl,
                    status = reportStatus,
                    severity = when (reportStatus) {
                        "QA_PASS", "MERGED" -> "success"
                        "CHANGES_REQUESTED" -> "warning"
                        else -> "info"
                    },
                    timestamp = item.qaReviewedAt ?: item.ceoReviewedAt ?: item.mergedAt ?: item.updatedAt
                )
            }

        val blockedItems = periodIssues
            .filter { it.status == IssueStatus.BLOCKED || it.status == IssueStatus.WAITING_FOR_APPROVAL }
            .sortedByDescending { it.updatedAt }
            .map { issue ->
                val latestRun = companyRuns
                    .filter { run -> companyTasks.firstOrNull { it.id == run.taskId }?.issueId == issue.id }
                    .maxByOrNull { it.updatedAt }
                val blockedReason = classifyBlockedReason(
                    issue = issue,
                    latestRun = latestRun,
                    reviewQueueItem = state.reviewQueue.firstOrNull { it.issueId == issue.id }
                )
                issue.toReportItem(
                    goalsById = goalsById,
                    detailOverride = blockedReason?.summary ?: issue.transitionReason ?: issue.providerBlockReason,
                    status = issue.status.name,
                    severity = if (issue.status == IssueStatus.WAITING_FOR_APPROVAL) "warning" else "danger",
                    timestamp = issue.updatedAt
                )
            }

        val autoRecoveredItems = periodActivities
            .filter { activity ->
                val haystack = listOfNotNull(activity.source, activity.title, activity.detail)
                    .joinToString(" ")
                    .lowercase()
                listOf("recover", "retry", "requeue", "resume", "reopen").any { token -> token in haystack }
            }
            .map { activity ->
                CompanyDailyReportItem(
                    id = "activity-${activity.id}",
                    title = activity.title,
                    detail = activity.detail,
                    issueId = activity.issueId,
                    goalId = activity.goalId,
                    status = activity.source,
                    severity = activity.severity,
                    timestamp = activity.createdAt
                )
            }

        val highlights = periodActivities
            .take(6)
            .map { activity ->
                CompanyDailyReportItem(
                    id = "highlight-${activity.id}",
                    title = activity.title,
                    detail = activity.detail,
                    issueId = activity.issueId,
                    goalId = activity.goalId,
                    status = activity.source,
                    severity = activity.severity,
                    timestamp = activity.createdAt
                )
            }

        val recommendedNextActions = recommendedMorningReportActions(
            issues = companyIssues,
            reviewQueue = state.reviewQueue.filter { it.companyId == companyId || it.issueId in companyIssueIds },
            goalsById = goalsById
        )

        val runtime = state.companyRuntimes.firstOrNull { it.companyId == companyId }
        val estimatedRunCostCents = periodRuns.mapNotNull { it.estimatedCostCents }.sum()
        val costSummary = CompanyDailyReportCostSummary(
            estimatedRunCostCents = estimatedRunCostCents,
            todaySpentCents = runtime?.todaySpentCents ?: 0,
            monthSpentCents = runtime?.monthSpentCents ?: 0,
            dailyBudgetCents = company.dailyBudgetCents,
            monthlyBudgetCents = company.monthlyBudgetCents,
            budgetPaused = runtime?.budgetPausedAt != null
        )

        return CompanyDailyReport(
            id = "${company.id}-$reportDate",
            companyId = company.id,
            date = reportDate.toString(),
            generatedAt = generatedAt,
            periodStart = periodStart,
            periodEnd = periodEnd,
            summary = morningReportSummary(
                completedCount = completedItems.size,
                pullRequestCount = pullRequests.size,
                qaPassedCount = reviewItems.count { it.status == "QA_PASS" },
                blockedCount = blockedItems.size,
                estimatedRunCostCents = estimatedRunCostCents,
                activityCount = periodActivities.size
            ),
            highlights = highlights,
            completedItems = completedItems,
            pullRequests = pullRequests,
            reviewItems = reviewItems,
            blockedItems = blockedItems,
            autoRecoveredItems = autoRecoveredItems,
            recommendedNextActions = recommendedNextActions,
            costSummary = costSummary,
            activityCount = periodActivities.size
        )
    }

    private fun recommendedMorningReportActions(
        issues: List<CompanyIssue>,
        reviewQueue: List<ReviewQueueItem>,
        goalsById: Map<String, CompanyGoal>
    ): List<CompanyDailyReportItem> {
        val blocked = issues
            .filter { it.status == IssueStatus.BLOCKED || it.status == IssueStatus.WAITING_FOR_APPROVAL }
            .sortedByDescending { it.updatedAt }
            .take(3)
            .map { issue ->
                issue.toReportItem(
                    goalsById = goalsById,
                    detailOverride = issue.transitionReason ?: issue.providerBlockReason ?: "Needs operator or agent attention.",
                    status = issue.status.name,
                    severity = "warning",
                    timestamp = issue.updatedAt,
                    idPrefix = "next-issue"
                )
            }
        if (blocked.isNotEmpty()) return blocked

        val reviewAttention = reviewQueue
            .filter {
                it.status == ReviewQueueStatus.CHANGES_REQUESTED ||
                    it.status == ReviewQueueStatus.FAILED_CHECKS ||
                    it.status == ReviewQueueStatus.READY_FOR_CEO ||
                    it.status == ReviewQueueStatus.READY_TO_MERGE
            }
            .sortedByDescending { it.updatedAt }
            .take(3)
            .map {
                CompanyDailyReportItem(
                    id = "next-review-${it.id}",
                    title = "Review queue item ${it.pullRequestNumber?.let { number -> "#$number" } ?: it.id}",
                    detail = it.checksSummary ?: it.mergeability ?: "Review queue needs attention.",
                    issueId = it.issueId,
                    runId = it.runId,
                    pullRequestUrl = it.pullRequestUrl,
                    status = it.status.name,
                    severity = "warning",
                    timestamp = it.updatedAt
                )
            }
        if (reviewAttention.isNotEmpty()) return reviewAttention

        val active = issues
            .filter {
                it.status == IssueStatus.PLANNED ||
                    it.status == IssueStatus.DELEGATED ||
                    it.status == IssueStatus.IN_PROGRESS ||
                    it.status == IssueStatus.IN_REVIEW ||
                    it.status == IssueStatus.READY_FOR_CEO
            }
            .sortedByDescending { it.updatedAt }
            .take(3)
            .map { issue ->
                issue.toReportItem(
                    goalsById = goalsById,
                    detailOverride = "Continue this active work item.",
                    status = issue.status.name,
                    severity = "info",
                    timestamp = issue.updatedAt,
                    idPrefix = "next-active"
                )
            }
        return active.ifEmpty {
            listOf(
                CompanyDailyReportItem(
                    id = "next-idle",
                    title = "No urgent action",
                    detail = "No blocked work or pending review was found for the next operating cycle.",
                    status = "IDLE",
                    severity = "info"
                )
            )
        }
    }

    private fun CompanyIssue.toReportItem(
        goalsById: Map<String, CompanyGoal>,
        detailOverride: String? = null,
        status: String,
        severity: String,
        timestamp: Long,
        idPrefix: String = "issue"
    ): CompanyDailyReportItem = CompanyDailyReportItem(
        id = "$idPrefix-$id",
        title = title,
        detail = detailOverride ?: goalsById[goalId]?.title ?: description,
        issueId = id,
        goalId = goalId,
        pullRequestUrl = pullRequestUrl,
        status = status,
        severity = severity,
        timestamp = timestamp
    )

    private fun morningReportSummary(
        completedCount: Int,
        pullRequestCount: Int,
        qaPassedCount: Int,
        blockedCount: Int,
        estimatedRunCostCents: Int,
        activityCount: Int
    ): String {
        if (completedCount == 0 && pullRequestCount == 0 && qaPassedCount == 0 && blockedCount == 0 && activityCount == 0) {
            return "No company activity was recorded for this report window."
        }
        return buildList {
            add("$completedCount completed")
            add("$pullRequestCount pull requests")
            add("$qaPassedCount QA passes")
            add("$blockedCount blocked")
            if (estimatedRunCostCents > 0) add("estimated run cost ${formatCents(estimatedRunCostCents)}")
            add("$activityCount activity events")
        }.joinToString(" · ")
    }

    private fun formatCents(cents: Int): String =
        "$" + "%.2f".format(java.util.Locale.US, cents.toDouble() / 100.0)

    private fun previousMorningReportDate(nowMillis: Long): LocalDate =
        Instant.ofEpochMilli(nowMillis).atZone(ZoneId.systemDefault()).toLocalDate().minusDays(1)

    private fun parseMorningReportDate(date: String): LocalDate =
        try {
            LocalDate.parse(date)
        } catch (error: DateTimeParseException) {
            throw IllegalArgumentException("Report date must use YYYY-MM-DD: $date", error)
        }

    private fun morningReportPeriod(date: LocalDate): Pair<Long, Long> {
        val zone = ZoneId.systemDefault()
        val start = date.atStartOfDay(zone).toInstant().toEpochMilli()
        val end = date.plusDays(1).atStartOfDay(zone).toInstant().toEpochMilli()
        return start to end
    }

    private fun companyReportsDir(companyId: String): Path =
        stateStore.appHome()
            .resolve("companies")
            .resolve(safeReportPathSegment(companyId))
            .resolve("reports")

    private fun companyReportPath(companyId: String, date: LocalDate): Path =
        companyReportsDir(companyId).resolve("$date.json")

    private fun safeReportPathSegment(raw: String): String =
        raw.trim().replace(Regex("[^A-Za-z0-9._-]"), "_").ifBlank { "company" }

    private fun readMorningReportFile(path: Path): CompanyDailyReport? =
        runCatching {
            dailyReportJson.decodeFromString(CompanyDailyReport.serializer(), Files.readString(path))
        }.getOrNull()

    private suspend fun writeMorningReport(report: CompanyDailyReport) {
        withContext(Dispatchers.IO) {
            val dir = companyReportsDir(report.companyId)
            Files.createDirectories(dir)
            Files.writeString(
                companyReportPath(report.companyId, LocalDate.parse(report.date)),
                dailyReportJson.encodeToString(CompanyDailyReport.serializer(), report),
                StandardOpenOption.CREATE,
                StandardOpenOption.TRUNCATE_EXISTING,
                StandardOpenOption.WRITE
            )
        }
    }

    private fun companyDashboardSnapshot(
        state: DesktopAppState,
        companyId: String? = null
    ): CompanyDashboardResponse {
        val filteredGoals = state.goals
            .filter { companyId == null || it.companyId == companyId }
            .sortedByDescending { it.updatedAt }
        val filteredIssues = state.issues
            .filter { companyId == null || it.companyId == companyId }
            .sortedByDescending { it.updatedAt }
        val filteredIssueIds = filteredIssues.map { it.id }.toSet()
        val filteredTasks = state.tasks
            .filter { task ->
                val issueId = task.issueId
                issueId != null && issueId in filteredIssueIds
            }
            .sortedByDescending { it.updatedAt }
        val orgProfiles = ensureOrgProfiles(state.orgProfiles, state.companyAgentDefinitions, state.companies)
        val boundRuntime = companyId?.let {
            runtimeBindingService.bind(
                state = state,
                companyId = it,
                runtime = state.companyRuntimes.firstOrNull { runtime -> runtime.companyId == it } ?: CompanyRuntimeSnapshot(companyId = it)
            )
        }
        val scopedIssues = boundRuntime?.issues?.filter { it.id in filteredIssueIds } ?: filteredIssues
        val scopedReviewQueue = (boundRuntime?.reviewQueue ?: state.reviewQueue)
            .filter { companyId == null || it.companyId == companyId || it.issueId in filteredIssueIds }
        return CompanyDashboardResponse(
            companies = state.companies.sortedByDescending { it.updatedAt },
            companyAgentDefinitions = state.companyAgentDefinitions
                .filter { companyId == null || it.companyId == companyId }
                .sortedWith(compareBy<CompanyAgentDefinition> { it.displayOrder }.thenBy { it.title.lowercase() }),
            agentCapabilityProfiles = state.agentCapabilityProfiles
                .filter { companyId == null || it.companyId == companyId }
                .sortedWith(compareBy<AgentCapabilityProfile> { it.companyId }.thenBy { it.agentId }),
            projectContexts = state.projectContexts
                .filter { companyId == null || it.companyId == companyId }
                .sortedByDescending { it.lastUpdatedAt },
            goals = filteredGoals,
            issues = scopedIssues,
            tasks = filteredTasks,
            issueDependencies = state.issueDependencies.filter { it.issueId in filteredIssueIds || it.dependsOnIssueId in filteredIssueIds },
            reviewQueue = scopedReviewQueue.sortedByDescending { it.updatedAt },
            orgProfiles = orgProfiles
                .filter { companyId == null || it.companyId == companyId },
            workflowTopologies = computeWorkflowTopologies(state, orgProfiles)
                .filter { companyId == null || it.companyId == companyId },
            goalDecisions = state.goalDecisions
                .filter { companyId == null || it.companyId == companyId }
                .sortedByDescending { it.createdAt },
            runningAgentSessions = computeRunningAgentSessions(state, orgProfiles)
                .filter { companyId == null || it.companyId == companyId },
            backendStatuses = computeBackendStatuses(state)
                .filter { companyId == null || state.companies.firstOrNull { company -> company.id == companyId }?.backendKind == it.kind },
            opsMetrics = state.opsMetrics,
            runtime = if (companyId == null) {
                state.runtime
            } else {
                boundRuntime?.runtime ?: state.companyRuntimes.firstOrNull { it.companyId == companyId } ?: CompanyRuntimeSnapshot(companyId = companyId)
            },
            signals = state.signals
                .filter { companyId == null || it.companyId == companyId }
                .sortedByDescending { it.createdAt },
            activity = state.companyActivity
                .filter { companyId == null || it.companyId == companyId }
                .sortedByDescending { it.createdAt },
            agentContextEntries = state.agentContextEntries
                .filter { companyId == null || it.companyId == companyId }
                .sortedByDescending { it.createdAt },
            agentMessages = state.agentMessages
                .filter { companyId == null || it.companyId == companyId }
                .sortedByDescending { it.createdAt },
            marketingDelegationPolicies = CompanyMarketingDashboardProjection.policies(state, companyId),
            marketingRuns = CompanyMarketingDashboardProjection.runs(state, companyId),
            skillRuns = state.skillRuns
                .filter { companyId == null || it.companyId == companyId }
                .sortedByDescending { it.updatedAt },
            agentPerformance = computeAgentPerformance(
                state = state,
                companyId = companyId,
                orgProfiles = orgProfiles,
                scopedIssues = scopedIssues,
                scopedTasks = filteredTasks,
                scopedReviewQueue = scopedReviewQueue
            )
        )
    }

    suspend fun listWorkflowTopologies(companyId: String? = null): List<WorkflowTopologySnapshot> {
        queueAutomationRefresh(companyId)
        val state = stateStore.load().withDerivedMetrics()
        val orgProfiles = ensureOrgProfiles(state.orgProfiles, state.companyAgentDefinitions, state.companies)
        return computeWorkflowTopologies(state, orgProfiles)
            .filter { companyId == null || it.companyId == companyId }
    }

    suspend fun listGoalDecisions(companyId: String? = null): List<GoalOrchestrationDecision> {
        queueAutomationRefresh(companyId)
        return stateStore.load().goalDecisions
            .filter { companyId == null || it.companyId == companyId }
            .sortedByDescending { it.createdAt }
    }

    private fun queueAutomationRefresh(companyId: String? = null) {
        if (companyId != null && automationRefreshJobs["__all__"]?.isActive == true) {
            return
        }
        val key = companyId ?: "__all__"
        if (automationRefreshJobs[key]?.isActive == true) {
            return
        }
        automationRefreshJobs[key] = serviceScope.launch {
            try {
                prepareCompanyAutomationState(companyId)
            } catch (cause: Throwable) {
                companyId?.let { markCompanyRuntimeError(it, cause) }
                throw cause
            } finally {
                automationRefreshJobs.remove(key)
            }
        }
    }

    fun companyEvents(companyId: String): Flow<CompanyEventEnvelope> =
        companyEventStream.filter { it.event.companyId == companyId }

    private suspend fun prepareCompanyAutomationState(companyId: String? = null) {
        migrateLegacyCompanyRosters(companyId)
        ensureBaselineAgentCapabilityProfiles(companyId)
        migrateLegacyFollowUpGoals(companyId)
        reconcileStaleAgentRuns(companyId)
        val targetCompanyIds = stateStore.load().companies
            .map { it.id }
            .filter { companyId == null || it == companyId }
        targetCompanyIds.forEach { activeCompanyId ->
            normalizeCompanyAutomationState(activeCompanyId)
            repairWorkflowLineages(activeCompanyId)
            reconcileNonPublishingReviewRuns(activeCompanyId)
            reconcileTerminalIssueStates(activeCompanyId)
            normalizePublishApprovalRequiredIssues(activeCompanyId)
            requeueAgentApprovedPublishApprovalIssues(activeCompanyId)
            archiveRecursiveFollowUpGoals(activeCompanyId)
            reopenResolvedMergeConflictIssues(activeCompanyId)
            reopenNoOpPullRequestExecutionIssues(activeCompanyId)
            requeueLegacyMergeConflictExecutionIssues(activeCompanyId)
            requeueRecoverableBlockedIssues(activeCompanyId)
            reconcileSupersededManagedPullRequests(activeCompanyId)
            ensureMorningReport(activeCompanyId)
        }
        resumeRunningCompanyRuntimes(companyId)
        ensureAutonomousCompanyRuntimes(companyId)
        stimulateAutonomousCompanyProgress(companyId)
        clearNonAttentionProviderBlockReasons(companyId)
    }

    internal suspend fun prepareCompanyAutomationStateForTesting(companyId: String? = null) {
        prepareCompanyAutomationState(companyId)
    }

    internal suspend fun requeueRecoverableBlockedIssuesForTesting(companyId: String): Int =
        requeueRecoverableBlockedIssues(companyId)

    private suspend fun clearNonAttentionProviderBlockReasons(companyId: String? = null): Int {
        var changed = 0
        stateMutex.withLock {
            val state = stateStore.load()
            val now = System.currentTimeMillis()
            val updatedIssues = state.issues.map { issue ->
                val inScope = companyId == null || issue.companyId == companyId
                val isAttentionState = issue.status == IssueStatus.BLOCKED || issue.status == IssueStatus.WAITING_FOR_APPROVAL
                if (inScope && !isAttentionState && issue.providerBlockReason != null) {
                    changed += 1
                    issue.copy(
                        providerBlockReason = null,
                        updatedAt = now
                    )
                } else {
                    issue
                }
            }
            if (changed > 0) {
                stateStore.save(state.copy(issues = updatedIssues).withDerivedMetrics())
            }
        }
        return changed
    }

    private suspend fun migrateLegacyCompanyRosters(companyId: String? = null) {
        stateMutex.withLock {
            val state = stateStore.load()
            val now = System.currentTimeMillis()
            val targetCompanies = state.companies.filter { companyId == null || it.id == companyId }
            val companiesNeedingMigration = targetCompanies.filter { company ->
                state.companyAgentDefinitions.none { it.companyId == company.id }
            }
            if (companiesNeedingMigration.isEmpty()) {
                return@withLock
            }

            val seededByCompany: Map<Company, List<CompanyAgentDefinition>> = companiesNeedingMigration.associateWith { company ->
                seedCompanyAgentDefinitions(company.id, now)
            }
            val definitionsByCompany: Map<String, Map<String, CompanyAgentDefinition>> =
                seededByCompany.mapValues { (_, defs) -> defs.associateBy { it.title } }
                    .mapKeys { (company, _) -> company.id }
            val migratedIssueAssignments = state.issues.map { issue ->
                val fallbackDefinitions = definitionsByCompany[issue.companyId] ?: return@map issue
                val matchingRole = state.orgProfiles
                    .firstOrNull { it.id == issue.assigneeProfileId }
                    ?.roleName
                    ?.let(fallbackDefinitions::get)
                issue.copy(
                    assigneeProfileId = matchingRole?.id ?: issue.assigneeProfileId
                )
            }
            val nextDefinitions = state.companyAgentDefinitions + seededByCompany.values.flatten()
            val nextProfiles = deriveProfiles(nextDefinitions, state.companies)
            val nextState = state.copy(
                companyAgentDefinitions = nextDefinitions,
                orgProfiles = nextProfiles,
                issues = migratedIssueAssignments
            ).withDerivedMetrics()
            stateStore.save(nextState)
        }
    }

    private suspend fun ensureBaselineAgentCapabilityProfiles(companyId: String? = null) {
        stateMutex.withLock {
            val state = stateStore.load()
            val companiesById = state.companies.associateBy { it.id }
            val existingProfiles = state.agentCapabilityProfiles
                .map { it.companyId to it.agentId }
                .toSet()
            val now = System.currentTimeMillis()
            val missingProfiles = state.companyAgentDefinitions
                .filter { definition -> companyId == null || definition.companyId == companyId }
                .filter { definition -> definition.companyId to definition.id !in existingProfiles }
                .mapNotNull { definition ->
                    companiesById[definition.companyId]?.let { company ->
                        seedCompanyAgentCapabilityProfile(company, definition, now)
                    }
                }
            val definitionsByKey = state.companyAgentDefinitions
                .associateBy { it.companyId to it.id }
            var upgraded = false
            val upgradedProfiles = state.agentCapabilityProfiles.map { profile ->
                val definition = definitionsByKey[profile.companyId to profile.agentId]
                val company = companiesById[profile.companyId]
                if (definition == null || company == null || (companyId != null && profile.companyId != companyId)) {
                    return@map profile
                }
                val upgradedProfile = upgradeCompanyAgentCapabilityProfile(company, definition, profile, now)
                if (upgradedProfile != profile) {
                    upgraded = true
                }
                upgradedProfile
            }
            if (missingProfiles.isEmpty() && !upgraded) {
                return@withLock
            }
            stateStore.save(
                state.copy(
                    agentCapabilityProfiles = upgradedProfiles + missingProfiles
                )
            )
        }
    }

    private suspend fun migrateLegacyFollowUpGoals(companyId: String? = null) {
        val traceEvents = mutableListOf<CompanyAutomationTraceEvent>()
        stateMutex.withLock {
            val state = stateStore.load()
            val issuesById = state.issues.associateBy { it.id }
            val goalsById = state.goals.associateBy { it.id }
            val reviewQueueById = state.reviewQueue.associateBy { it.id }
            val now = System.currentTimeMillis()
            var changed = false
            val recursiveNestedGoalIds = state.goals
                .filter { goal ->
                    (companyId == null || goal.companyId == companyId) &&
                        goal.status == GoalStatus.ACTIVE &&
                        goal.operatingPolicy?.startsWith("auto-follow-up:goal:") == true
                }
                .mapNotNull { goal ->
                    val parentGoalId = goal.operatingPolicy?.removePrefix("auto-follow-up:goal:").orEmpty()
                    val parentGoal = goalsById[parentGoalId] ?: return@mapNotNull null
                    if (parentGoal.operatingPolicy.orEmpty().startsWith("auto-follow-up:")) goal.id else null
                }
                .toSet()

            val canonicalGoals = state.goals.map { goal ->
                if (
                    (companyId != null && goal.companyId != companyId) ||
                    !goal.operatingPolicy.orEmpty().startsWith("auto-follow-up:") ||
                    goal.id in recursiveNestedGoalIds
                ) {
                    return@map goal
                }
                val rootGoalId = resolveFollowUpRootGoalId(goal.id, issuesById, goalsById, reviewQueueById)
                    ?: return@map goal
                val canonicalPolicy = "auto-follow-up:goal:$rootGoalId"
                val canonicalTitle = generatedFollowUpSubject(goal.title)
                    ?.let(::canonicalFollowUpSubject)
                    ?.let { subject -> "Resolve follow-up for \"$subject\"" }
                    ?: goal.title
                val inferredFollowUpContext = goal.followUpContext ?: inferLegacyFollowUpContext(
                    state = state,
                    goal = goal,
                    rootGoalId = rootGoalId,
                    issuesById = issuesById,
                    goalsById = goalsById,
                    reviewQueueById = reviewQueueById
                )
                if (
                    goal.operatingPolicy == canonicalPolicy &&
                    goal.title == canonicalTitle &&
                    goal.followUpContext == inferredFollowUpContext
                ) {
                    return@map goal
                }
                changed = true
                goal.copy(
                    operatingPolicy = canonicalPolicy,
                    title = canonicalTitle,
                    followUpContext = inferredFollowUpContext,
                    updatedAt = now
                )
            }

            val canonicalGoalsById = canonicalGoals.associateBy { it.id }
            val activeGoalIdsWithTasks = state.tasks
                .filter { it.status == DesktopTaskStatus.RUNNING || it.status == DesktopTaskStatus.QUEUED }
                .mapNotNull { task -> task.issueId?.let { issuesById[it]?.goalId } }
                .toSet()
            val duplicateGoalIds = canonicalGoals
                .filter { goal ->
                    (companyId == null || goal.companyId == companyId) &&
                        goal.status == GoalStatus.ACTIVE &&
                        goal.operatingPolicy.orEmpty().startsWith("auto-follow-up:") &&
                        goal.id !in recursiveNestedGoalIds
                }
                .groupBy { resolveFollowUpRootGoalId(it.id, issuesById, canonicalGoalsById, reviewQueueById) ?: canonicalFollowUpSubject(it.title) }
                .values
                .flatMap { goalsForLineage ->
                    if (goalsForLineage.size <= 1) {
                        emptyList()
                    } else {
                        val keepGoal = goalsForLineage.maxWithOrNull(
                            compareBy<CompanyGoal>(
                                { if (it.id in activeGoalIdsWithTasks) 1 else 0 },
                                { it.updatedAt }
                            )
                        )
                        goalsForLineage
                            .filterNot { it.id == keepGoal?.id || it.id in activeGoalIdsWithTasks }
                            .map { it.id }
                    }
                }
                .toSet()
            if (duplicateGoalIds.isNotEmpty()) {
                changed = true
            }

            val nextIssues = state.issues.map { issue ->
                if (companyId != null && issue.companyId != companyId) {
                    return@map issue
                }
                val goal = canonicalGoalsById[issue.goalId]
                val inferredExecutionIntent = if (issue.executionIntent == null) {
                    inferExecutionIntent(
                        kind = issue.kind,
                        title = issue.title,
                        description = issue.description,
                        plannedCodeProducing = issue.codeProducing
                    )
                } else {
                    issue.executionIntent
                }
                val normalizedCodeProducing = when (inferredExecutionIntent) {
                    ExecutionIntent.VALIDATION_ONLY, ExecutionIntent.PR_REUSE_HANDOFF -> false
                    ExecutionIntent.CODE_CHANGE, ExecutionIntent.MERGE_CONFLICT_REMEDIATION -> true
                    null -> issue.codeProducing
                }
                val normalizedIssue = issue.copy(
                    executionIntent = inferredExecutionIntent,
                    codeProducing = normalizedCodeProducing,
                    requiresPullRequest = issue.requiresPullRequest ?: inferIssueRequiresPullRequest(issue.title, issue.description)
                )
                if (normalizedIssue == issue) {
                    issue
                } else {
                    changed = true
                    normalizedIssue.copy(updatedAt = now)
                }
            }

            if (!changed) {
                return@withLock
            }

            val migratedIssues = nextIssues.map { issue ->
                if (issue.goalId !in duplicateGoalIds || issue.status == IssueStatus.DONE || issue.status == IssueStatus.CANCELED) {
                    issue
                } else {
                    traceEvents += CompanyAutomationTraceEvent(
                        timestamp = now,
                        companyId = issue.companyId,
                        projectContextId = issue.projectContextId,
                        goalId = issue.goalId,
                        issueId = issue.id,
                        issueTitle = issue.title,
                        issueKind = issue.kind,
                        oldStatus = issue.status,
                        newStatus = IssueStatus.CANCELED,
                        source = "migrateLegacyFollowUpGoals",
                        reason = "Canceled a duplicate historical follow-up goal during root-goal lineage migration.",
                        operatingPolicy = canonicalGoalsById[issue.goalId]?.operatingPolicy
                    )
                    issue.copy(
                        status = IssueStatus.CANCELED,
                        updatedAt = now
                    )
                }
            }
            val nextGoals = canonicalGoals.map { goal ->
                if (goal.id !in duplicateGoalIds) {
                    goal
                } else {
                    goal.copy(
                        status = GoalStatus.COMPLETED,
                        updatedAt = now
                    )
                }
            }
            val changedCompanies = nextGoals
                .filter { goal ->
                    val previousGoal = goalsById[goal.id]
                    previousGoal != null &&
                        (
                            previousGoal.operatingPolicy != goal.operatingPolicy ||
                                previousGoal.title != goal.title ||
                                previousGoal.status != goal.status ||
                                previousGoal.followUpContext != goal.followUpContext
                            )
                }
                .map { it.companyId }
                .distinct()
            var nextState = state.copy(
                goals = nextGoals,
                issues = migratedIssues
            )
            val detailParts = buildList {
                if (canonicalGoals != state.goals) add("canonicalized follow-up markers")
                if (migratedIssues != state.issues) add("backfilled legacy follow-up execution metadata")
                if (duplicateGoalIds.isNotEmpty()) add("collapsed ${duplicateGoalIds.size} duplicate follow-up goals")
            }
            changedCompanies.forEach { changedCompanyId ->
                nextState = nextState.recordCompanyActivity(
                    companyId = changedCompanyId,
                    source = "company-runtime",
                    title = "Migrated legacy follow-up state",
                    detail = detailParts.joinToString(", ")
                )
            }
            nextState = nextState.withDerivedMetrics()
            stateStore.save(nextState)
        }
        traceEvents.forEach(::appendCompanyAutomationTrace)
    }

    private suspend fun resumeRunningCompanyRuntimes(companyId: String? = null) {
        val runningCompanyIds = stateStore.load().companyRuntimes
            .filter { it.status == CompanyRuntimeStatus.RUNNING }
            .map { it.companyId }
            .filterNotNull()
            .filter { companyId == null || it == companyId }
        runningCompanyIds.forEach { runningCompanyId ->
            val preResumeState = stateStore.load()
            val shouldForceResumeTick = hasQueuedCompanyIssues(preResumeState, runningCompanyId) &&
                !hasActiveCompanyTasks(preResumeState, runningCompanyId)
            val queuedIssueCount = queuedCompanyIssueCount(preResumeState, runningCompanyId)
            val runtimeLoopActive = companyRuntimeJobs[runningCompanyId]?.isActive == true
            val shouldRecordResume = queuedIssueCount > 0 && (!runtimeLoopActive || shouldForceResumeTick)
            if (!runtimeLoopActive) {
                runCatching { startCompanyBackend(runningCompanyId) }
                    .onFailure { cause -> markCompanyRuntimeError(runningCompanyId, cause) }
                ensureCompanyRuntimeLoop(runningCompanyId)
            }
            if (shouldForceResumeTick) {
                markRuntimeTickHeartbeat(runningCompanyId, "recovering-after-app-server-shutdown")
            }
            if (!runtimeLoopActive || shouldForceResumeTick) {
                runCatching { runCompanyRuntimeTick(runningCompanyId) }
                    .onFailure { cause -> markCompanyRuntimeError(runningCompanyId, cause) }
                if (shouldRecordResume) {
                    recordCompanyRuntimeResume(runningCompanyId, queuedIssueCount)
                }
            }
        }
    }

    private suspend fun ensureAutonomousCompanyRuntimes(companyId: String? = null) {
        val state = stateStore.load()
        val companiesNeedingRuntime = state.goals
            .filter { it.autonomyEnabled && it.status == GoalStatus.ACTIVE }
            .filter { companyId == null || it.companyId == companyId }
            .mapNotNull { it.companyId }
            .distinct()
            .filter { activeCompanyId ->
                val runtime = state.companyRuntimes.firstOrNull { it.companyId == activeCompanyId }
                runtime?.status != CompanyRuntimeStatus.RUNNING && runtime?.manuallyStoppedAt == null
            }
        companiesNeedingRuntime.forEach { activeCompanyId ->
            startCompanyRuntimeIfNotManuallyStopped(activeCompanyId)
        }
    }

    private suspend fun reconcileStaleAgentRuns(companyId: String? = null) {
        val affectedTaskIds = mutableSetOf<String>()
        stateMutex.withLock {
            val state = stateStore.load()
            val now = System.currentTimeMillis()
            val relevantIssueIds = state.issues
                .filter { companyId == null || it.companyId == companyId }
                .map { it.id }
                .toSet()
            val staleRuns = state.runs.filter { run ->
                val hasDanglingActiveJob = activeTaskJobs.containsKey(run.taskId)
                run.status == AgentRunStatus.RUNNING &&
                    isRunStale(run, now) &&
                    !hasDanglingActiveJob &&
                    (companyId == null || state.tasks.firstOrNull { it.id == run.taskId }?.issueId in relevantIssueIds)
            }
            val staleZeroRunTaskIds = state.tasks.filter { task ->
                task.status == DesktopTaskStatus.RUNNING &&
                    (companyId == null || task.issueId in relevantIssueIds) &&
                    now - task.updatedAt > staleRunStartupGraceMs &&
                    runsByTask(state.runs)[task.id].isNullOrEmpty() &&
                    !activeTaskJobs.containsKey(task.id)
            }.mapTo(linkedSetOf()) { it.id }
            if (staleRuns.isEmpty() && staleZeroRunTaskIds.isEmpty()) {
                return@withLock
            }

            val staleRunIds = staleRuns.map { it.id }.toSet()
            val updatedRuns = state.runs.map { run ->
                if (run.id in staleRunIds) {
                    run.copy(
                        status = AgentRunStatus.FAILED,
                        error = run.error ?: "Agent process exited before Cotor recorded a final result",
                        updatedAt = now
                    )
                } else {
                    run
                }
            }
            val runsByTask = updatedRuns.groupBy { it.taskId }
            val updatedTasks = state.tasks.map { task ->
                val taskRuns = runsByTask[task.id].orEmpty()
                if (task.status != DesktopTaskStatus.RUNNING && task.status != DesktopTaskStatus.QUEUED) {
                    task
                } else if (task.id in staleZeroRunTaskIds) {
                    affectedTaskIds += task.id
                    task.copy(status = DesktopTaskStatus.FAILED, updatedAt = now)
                } else if (taskRuns.any { it.status == AgentRunStatus.RUNNING || it.status == AgentRunStatus.QUEUED }) {
                    task
                } else {
                    val nextStatus = finalTaskStatus(taskRuns)
                    if (nextStatus != task.status) {
                        affectedTaskIds += task.id
                        task.copy(status = nextStatus, updatedAt = now)
                    } else {
                        task
                    }
                }
            }
            val nextState = state.copy(
                runs = updatedRuns,
                tasks = updatedTasks
            ).withDerivedMetrics()
            stateStore.save(nextState)
        }
        affectedTaskIds.forEach { taskId ->
            getTask(taskId)?.let { task ->
                syncIssueFromTask(task.id, task.status)
            }
        }
    }

    private fun runsByTask(runs: List<AgentRun>): Map<String, List<AgentRun>> = runs.groupBy { it.taskId }

    private suspend fun interruptActiveTasksForShutdown() {
        val traceEvents = mutableListOf<CompanyAutomationTraceEvent>()
        stateMutex.withLock {
            val state = stateStore.load()
            val now = System.currentTimeMillis()
            val issuesById = state.issues.associateBy { it.id }
            val goalsById = state.goals.associateBy { it.id }
            val activeTasks = state.tasks.filter {
                it.status == DesktopTaskStatus.RUNNING || it.status == DesktopTaskStatus.QUEUED
            }
            if (activeTasks.isEmpty()) {
                return@withLock
            }

            val interruptedTaskIds = activeTasks.mapTo(linkedSetOf()) { it.id }
            intentionallyInterruptedTaskIds.addAll(interruptedTaskIds)

            val updatedRuns = state.runs.map { run ->
                if (run.taskId in interruptedTaskIds &&
                    (run.status == AgentRunStatus.RUNNING || run.status == AgentRunStatus.QUEUED)
                ) {
                    run.copy(
                        status = AgentRunStatus.FAILED,
                        error = INTERRUPTED_RUN_ERROR,
                        updatedAt = now
                    )
                } else {
                    run
                }
            }
            val latestRunsByTaskId = updatedRuns
                .groupBy { it.taskId }
                .mapValues { (_, runs) -> runs.maxByOrNull { it.updatedAt }!! }
            val updatedTasks = state.tasks.map { task ->
                if (task.id in interruptedTaskIds) {
                    task.copy(
                        status = DesktopTaskStatus.FAILED,
                        updatedAt = now
                    )
                } else {
                    task
                }
            }
            var nextState = state.copy(
                tasks = updatedTasks,
                runs = updatedRuns
            )
            activeTasks.forEach { task ->
                val issue = task.issueId?.let(issuesById::get) ?: return@forEach
                if (issue.status == IssueStatus.DONE || issue.status == IssueStatus.CANCELED) {
                    return@forEach
                }
                val reopenedStatus = if (issue.kind.equals("planning", ignoreCase = true)) {
                    IssueStatus.PLANNED
                } else {
                    IssueStatus.DELEGATED
                }
                val latestRun = latestRunsByTaskId[task.id]
                traceEvents += buildCompanyAutomationTraceEvent(
                    issue = issue,
                    goal = issue.goalId?.let(goalsById::get),
                    oldStatus = issue.status,
                    newStatus = reopenedStatus,
                    source = "interruptActiveTasksForShutdown",
                    reason = "App-server shutdown interrupted an active task; the issue was returned to the queue.",
                    latestTask = task.copy(status = DesktopTaskStatus.FAILED, updatedAt = now),
                    latestRun = latestRun
                )
                nextState = nextState.copy(
                    issues = nextState.issues.map { existing ->
                        if (existing.id == issue.id) {
                            existing.copy(
                                status = reopenedStatus,
                                transitionReason = INTERRUPTED_ISSUE_REASON,
                                updatedAt = now
                            )
                        } else {
                            existing
                        }
                    }
                ).recordCompanyActivity(
                    companyId = issue.companyId,
                    source = "runtime",
                    title = "Interrupted by app-server shutdown",
                    detail = issue.title,
                    severity = "warning",
                    goalId = issue.goalId,
                    issueId = issue.id
                )
            }
            nextState = nextState.recordSignal(
                source = "runtime",
                message = "Interrupted ${activeTasks.size} active task(s) during app-server shutdown.",
                severity = "warning"
            ).withDerivedMetrics()
            stateStore.save(nextState)
        }
        traceEvents.forEach(::appendCompanyAutomationTrace)
    }

    private suspend fun reopenInterruptedBlockedIssues(companyId: String): Int {
        val traceEvents = mutableListOf<CompanyAutomationTraceEvent>()
        var reopenedCount = 0
        stateMutex.withLock {
            val state = stateStore.load()
            val now = System.currentTimeMillis()
            val runtime = state.companyRuntimes.firstOrNull { it.companyId == companyId } ?: return@withLock
            val interruptionBoundary = runtime.lastStartedAt ?: return@withLock
            val goalsById = state.goals.associateBy { it.id }
            val latestTasksByIssueId = state.tasks
                .filter { it.issueId != null }
                .groupBy { it.issueId!! }
                .mapValues { (_, tasks) -> tasks.maxByOrNull { it.updatedAt }!! }
            val latestRunsByTaskId = state.runs
                .groupBy { it.taskId }
                .mapValues { (_, runs) -> runs.maxByOrNull { it.updatedAt }!! }
            val issuesToReopen = state.issues.mapNotNull { issue ->
                if (issue.companyId != companyId || issue.status != IssueStatus.BLOCKED) {
                    return@mapNotNull null
                }
                if (issue.pullRequestNumber != null || issue.pullRequestUrl != null) {
                    return@mapNotNull null
                }
                if (issue.qaVerdict != null || issue.ceoVerdict != null) {
                    return@mapNotNull null
                }
                val latestTask = latestTasksByIssueId[issue.id] ?: return@mapNotNull null
                val latestRun = latestRunsByTaskId[latestTask.id] ?: return@mapNotNull null
                val interruptedByRestart =
                    latestTask.status in setOf(DesktopTaskStatus.FAILED, DesktopTaskStatus.PARTIAL) &&
                        latestTask.updatedAt < interruptionBoundary &&
                        latestRun.status == AgentRunStatus.FAILED &&
                        latestRun.publish == null &&
                        latestRun.error?.contains(
                            "Agent process exited before Cotor recorded a final result",
                            ignoreCase = true
                        ) == true
                if (!interruptedByRestart) {
                    return@mapNotNull null
                }
                issue to Pair(latestTask, latestRun)
            }
            if (issuesToReopen.isEmpty()) {
                return@withLock
            }
            val taskIds = issuesToReopen.mapTo(linkedSetOf()) { it.second.first.id }
            val updatedRuns = state.runs.map { run ->
                if (run.taskId in taskIds && run.status == AgentRunStatus.FAILED &&
                    run.error?.contains("Agent process exited before Cotor recorded a final result", ignoreCase = true) == true
                ) {
                    run.copy(
                        error = INTERRUPTED_RUN_ERROR,
                        updatedAt = now
                    )
                } else {
                    run
                }
            }
            var nextState = state.copy(runs = updatedRuns)
            issuesToReopen.forEach { (issue, pair) ->
                val latestTask = pair.first
                val latestRun = latestRunsByTaskId[latestTask.id]?.copy(error = INTERRUPTED_RUN_ERROR)
                    ?: pair.second.copy(error = INTERRUPTED_RUN_ERROR)
                val reopenedStatus = if (issue.kind.equals("planning", ignoreCase = true)) {
                    IssueStatus.PLANNED
                } else {
                    IssueStatus.DELEGATED
                }
                reopenedCount += 1
                traceEvents += buildCompanyAutomationTraceEvent(
                    issue = issue,
                    goal = issue.goalId?.let(goalsById::get),
                    oldStatus = issue.status,
                    newStatus = reopenedStatus,
                    source = "reopenInterruptedBlockedIssues",
                    reason = "Recovered an issue that was blocked by an app-server shutdown while its task was still running.",
                    latestTask = latestTask,
                    latestRun = latestRun
                )
                nextState = nextState.copy(
                    issues = nextState.issues.map { existing ->
                        if (existing.id == issue.id) {
                            existing.copy(
                                status = reopenedStatus,
                                transitionReason = INTERRUPTED_ISSUE_REASON,
                                updatedAt = now
                            )
                        } else {
                            existing
                        }
                    }
                ).recordCompanyActivity(
                    companyId = issue.companyId,
                    source = "runtime",
                    title = "Recovered interrupted issue",
                    detail = issue.title,
                    severity = "warning",
                    goalId = issue.goalId,
                    issueId = issue.id
                )
            }
            nextState = nextState.recordSignal(
                source = "runtime",
                message = "Recovered $reopenedCount blocked issue(s) that were interrupted by a previous app-server shutdown.",
                severity = "warning",
                companyId = companyId
            ).withDerivedMetrics()
            stateStore.save(nextState)
        }
        traceEvents.forEach(::appendCompanyAutomationTrace)
        return reopenedCount
    }

    private fun isTaskIntentionallyInterrupted(taskId: String): Boolean =
        taskId in intentionallyInterruptedTaskIds

    private suspend fun stimulateAutonomousCompanyProgress(companyId: String? = null) {
        val snapshot = stateStore.load()
        val now = System.currentTimeMillis()
        val targetCompanyIds = snapshot.goals
            .filter { it.autonomyEnabled && it.status == GoalStatus.ACTIVE }
            .mapNotNull { it.companyId }
            .filter { companyId == null || it == companyId }
            .distinct()

        targetCompanyIds.forEach { activeCompanyId ->
            val runtime = snapshot.companyRuntimes.firstOrNull { it.companyId == activeCompanyId }
            val hasPendingIssues = snapshot.issues.any { issue ->
                issue.companyId == activeCompanyId &&
                    issue.status != IssueStatus.DONE &&
                    issue.status != IssueStatus.CANCELED
            }
            val tickIsStale = runtime?.lastTickAt?.let { now - it > 5_000 } ?: true
            val loopMissing = companyRuntimeJobs[activeCompanyId]?.isActive != true

            if (hasPendingIssues && runtime?.manuallyStoppedAt == null) {
                if (runtime?.status != CompanyRuntimeStatus.RUNNING) {
                    startCompanyRuntimeIfNotManuallyStopped(activeCompanyId)
                } else if (loopMissing) {
                    ensureCompanyRuntimeLoop(activeCompanyId)
                }
                wakeCompanyRuntime(activeCompanyId)
                if (tickIsStale) {
                    runCatching { runCompanyRuntimeTick(activeCompanyId) }
                }
            }
        }
    }

    private fun runtimeWakeSignal(companyId: String): MutableSharedFlow<Unit> =
        companyRuntimeWakeSignals.computeIfAbsent(companyId) {
            MutableSharedFlow(replay = 0, extraBufferCapacity = 1)
        }

    private fun wakeCompanyRuntime(companyId: String) {
        runtimeWakeSignal(companyId).tryEmit(Unit)
    }

    private fun finalTaskStatus(runs: List<AgentRun>): DesktopTaskStatus = when {
        runs.isEmpty() -> DesktopTaskStatus.FAILED
        runs.all { it.status == AgentRunStatus.COMPLETED } -> DesktopTaskStatus.COMPLETED
        runs.any { it.status == AgentRunStatus.COMPLETED } &&
            runs.any { it.status == AgentRunStatus.FAILED } -> DesktopTaskStatus.PARTIAL
        else -> DesktopTaskStatus.FAILED
    }

    private fun isProcessAlive(processId: Long?): Boolean {
        if (processId == null) {
            return false
        }
        return runCatching {
            ProcessHandle.of(processId).map { it.isAlive }.orElse(false)
        }.getOrDefault(false)
    }

    private fun isRunStale(run: AgentRun, now: Long): Boolean {
        return when {
            run.processId != null -> !isProcessAlive(run.processId) && now - run.updatedAt > staleRunStartupGraceMs
            else -> now - run.updatedAt > staleRunStartupGraceMs
        }
    }

    suspend fun listRepositories(): List<ManagedRepository> =
        stateStore.load().repositories.sortedByDescending { it.updatedAt }

    suspend fun listWorkspaces(repositoryId: String? = null): List<Workspace> {
        val workspaces = stateStore.load().workspaces.sortedByDescending { it.updatedAt }
        return repositoryId?.let { id -> workspaces.filter { it.repositoryId == id } } ?: workspaces
    }

    suspend fun listBranches(repositoryId: String): List<String> {
        val repository = stateStore.load().repositories.firstOrNull { it.id == repositoryId }
            ?: throw IllegalArgumentException("Repository not found: $repositoryId")
        return gitWorkspaceService.listBranches(Path.of(repository.localPath))
    }

    suspend fun listTasks(workspaceId: String? = null): List<AgentTask> {
        val tasks = stateStore.load().tasks.sortedByDescending { it.createdAt }
        return workspaceId?.let { id -> tasks.filter { it.workspaceId == id } } ?: tasks
    }

    suspend fun listRuns(taskId: String? = null): List<AgentRun> {
        val runs = stateStore.load().runs.sortedByDescending { it.createdAt }
        return taskId?.let { id -> runs.filter { it.taskId == id } } ?: runs
    }

    suspend fun listIssueRuns(issueId: String): List<AgentRun> {
        val state = stateStore.load()
        val taskIds = state.tasks
            .filter { it.issueId == issueId }
            .mapTo(linkedSetOf()) { it.id }
        return state.runs
            .filter { it.taskId in taskIds }
            .sortedByDescending { it.updatedAt }
    }

    suspend fun issueExecutionDetails(issueId: String): List<IssueAgentExecutionDetail> {
        val state = stateStore.load()
        val issue = state.issues.firstOrNull { it.id == issueId } ?: return emptyList()
        val assigneeProfile = issue.assigneeProfileId?.let { profileId ->
            ensureOrgProfiles(state.orgProfiles, state.companyAgentDefinitions, state.companies)
                .firstOrNull { it.id == profileId }
        }
        val latestQueueItem = state.reviewQueue
            .filter { it.issueId == issueId }
            .maxByOrNull { it.updatedAt }
        return state.tasks
            .filter { it.issueId == issueId }
            .sortedByDescending { it.updatedAt }
            .flatMap { task ->
                val latestRuns = state.runs
                    .filter { it.taskId == task.id }
                    .groupBy { run -> run.agentName }
                    .values
                    .mapNotNull { runsForAgent -> runsForAgent.maxByOrNull { it.updatedAt } }
                    .sortedByDescending { it.updatedAt }

                val detailRuns = if (latestRuns.isEmpty()) listOf<AgentRun?>(null) else latestRuns.map { it }
                detailRuns.map { latestRun ->
                    val agentName = latestRun?.agentName
                        ?: task.agents.firstOrNull()
                        ?: assigneeProfile?.executionAgentName
                        ?: "unknown"
                    val assignment = task.plan?.assignmentFor(agentName) ?: task.plan?.assignments?.firstOrNull()
                    val agentDefinition = resolveCompanyAgentDefinition(state, issue, assigneeProfile, agentName)
                    IssueAgentExecutionDetail(
                        roleName = assigneeProfile?.roleName
                            ?: assignment?.role
                            ?: agentDefinition?.title
                            ?: agentName,
                        agentName = agentName,
                        agentCli = latestRun?.agentName
                            ?: assigneeProfile?.executionAgentName
                            ?: agentDefinition?.agentCli
                            ?: agentName,
                        model = latestRun?.model
                            ?: agentDefinition?.model
                            ?: BuiltinAgentCatalog.get(agentName)?.parameters?.get("model"),
                        assignedPrompt = assignment?.assignedPrompt ?: task.prompt,
                        taskId = task.id,
                        taskStatus = task.status.name,
                        runId = latestRun?.id,
                        runStatus = latestRun?.status?.name,
                        backendKind = latestRun?.backendKind,
                        processId = latestRun?.processId,
                        stdout = truncateExecutionLog(latestRun?.output),
                        stderr = truncateExecutionLog(latestRun?.error ?: latestRun?.publish?.error),
                        branchName = latestRun?.branchName ?: issue.branchName,
                        pullRequestUrl = latestRun?.publish?.pullRequestUrl
                            ?: latestQueueItem?.pullRequestUrl
                            ?: issue.pullRequestUrl,
                        updatedAt = maxOf(task.updatedAt, latestRun?.updatedAt ?: task.updatedAt),
                        publishSummary = buildIssueExecutionPublishSummary(issue, latestQueueItem, latestRun)
                    )
                }
            }
    }

