    fun capabilityCatalog(): List<CapabilityCatalogEntry> = com.cotor.app.capabilityCatalog()

    fun providerCatalog(): List<ProviderCatalogEntry> = com.cotor.app.providerCatalog()

    fun skillCatalog(): List<SkillCatalogEntry> = com.cotor.app.skillCatalog()

    fun inspectSkill(name: String): SkillCatalogEntry = skillCatalog().firstOrNull { it.name.equals(name.trim(), ignoreCase = true) }
        ?: throw IllegalArgumentException("Skill not found: $name")

    fun validateSkill(path: String): SkillValidationResult {
        val manifestPath = Path.of(path).toAbsolutePath().normalize()
        if (!Files.exists(manifestPath)) {
            return SkillValidationResult(valid = false, errors = listOf("Skill manifest not found: $manifestPath"))
        }
        if (Files.isDirectory(manifestPath)) {
            return SkillValidationResult(valid = false, errors = listOf("Skill manifest path is a directory: $manifestPath"))
        }
        val raw = runCatching { Files.readString(manifestPath) }
            .getOrElse { return SkillValidationResult(valid = false, errors = listOf(it.message ?: "Unable to read skill manifest")) }
        return parseSkillManifest(raw)
    }

    suspend fun runSkill(
        name: String,
        companyId: String,
        agentId: String,
        input: String? = null,
        parameters: Map<String, String> = emptyMap()
    ): SkillRunResult {
        val skill = inspectSkill(name)
        val runId = UUID.randomUUID().toString()
        val startedAt = System.currentTimeMillis()
        val simulation = simulateAgentCapability(
            companyId = companyId,
            agentId = agentId,
            action = ActionKind.SKILL_RUN.wireValue,
            skill = skill.name
        )
        val result = when {
            !simulation.allowed -> SkillRunResult(
                skill = skill.name,
                status = "DENIED",
                capability = simulation,
                runId = runId,
                summary = "${skill.displayName} was denied by capability policy.",
                error = simulation.reason
            )
            simulation.requiresApproval -> SkillRunResult(
                skill = skill.name,
                status = "APPROVAL_REQUIRED",
                capability = simulation,
                runId = runId,
                summary = "${skill.displayName} requires explicit pre-delegation before it can run.",
                error = simulation.reason
            )
            else -> runCatching {
                val request = ActionRequest(
                    kind = ActionKind.SKILL_RUN,
                    label = "skill.run:${skill.name}",
                    scope = ActionScope.COMPANY,
                    subject = ActionSubject(runId = runId, companyId = companyId, agentName = agentId),
                    replaySafe = false,
                    approvalRequiredOnReplay = false,
                    metadata = skillRunMetadata(skill, input, parameters),
                    evidence = ActionEvidence()
                )
                skillActionExecutionService.run(
                    request = request,
                    onSuccess = { completed: SkillRunResult ->
                        ActionEvidence(filePaths = completed.evidence.mapNotNull { it.path })
                    },
                    onFailure = { ActionEvidence() }
                ) {
                    dispatchSkillRun(
                        skill = skill,
                        companyId = companyId,
                        agentId = agentId,
                        input = input,
                        parameters = parameters,
                        runId = runId,
                        baseCapability = simulation
                    )
                }
            }.getOrElse { error ->
                SkillRunResult(
                    skill = skill.name,
                    status = if (error is IllegalArgumentException) "FAILED_SETUP" else "FAILED",
                    capability = simulation,
                    runId = runId,
                    summary = "${skill.displayName} failed before it could produce evidence.",
                    error = error.message ?: error::class.simpleName.orEmpty()
                )
            }
        }
        persistSkillRunResult(companyId, agentId, result, startedAt)
        return result
    }

    private suspend fun dispatchSkillRun(
        skill: SkillCatalogEntry,
        companyId: String,
        agentId: String,
        input: String?,
        parameters: Map<String, String>,
        runId: String,
        baseCapability: CapabilitySimulationResult
    ): SkillRunResult =
        when (skill.name) {
            "graphify" -> runGraphifySkill(skill, companyId, agentId, input, parameters, runId, baseCapability)
            "browser-smoke" -> runBrowserSmokeSkill(skill, companyId, agentId, input, parameters, runId, baseCapability)
            "marketing-operator",
            "content-publisher",
            "social-publisher" -> runMarketingSkill(skill, companyId, agentId, input, parameters, runId, baseCapability)
            "audience-scout",
            "analytics-reporter" -> runMarketingReportSkill(skill, companyId, agentId, input, parameters, runId, baseCapability)
            "video-plan" -> runVideoPlanSkill(skill, companyId, agentId, input, parameters, runId, baseCapability)
            else -> SkillRunResult(
                skill = skill.name,
                status = "FAILED_SETUP",
                capability = baseCapability,
                runId = runId,
                summary = "No runtime runner is registered for ${skill.displayName}.",
                error = "No runner registered for skill: ${skill.name}"
            )
        }

    private suspend fun runGraphifySkill(
        skill: SkillCatalogEntry,
        companyId: String,
        agentId: String,
        input: String?,
        parameters: Map<String, String>,
        runId: String,
        baseCapability: CapabilitySimulationResult
    ): SkillRunResult = withContext(Dispatchers.IO) {
        val company = stateStore.load().companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val root = Path.of(company.rootPath).toAbsolutePath().normalize()
        val evidenceDir = skillRunEvidenceDir(skill.name, runId)
        val reportPath = root.resolve("graphify-out").resolve("GRAPH_REPORT.md")
        val actions = mutableListOf<String>()
        val evidence = mutableListOf<SkillRunEvidence>()
        val output = StringBuilder()

        val readCheck = simulateCapabilityKey(
            companyId = companyId,
            agentId = agentId,
            capability = CapabilityKey.KNOWLEDGE_GRAPH_READ,
            action = "knowledge.graph-read",
            path = root.toString()
        )
        if (!readCheck.allowed || readCheck.requiresApproval) {
            return@withContext blockedSkillRunResult(skill, runId, readCheck, "Graphify read access is blocked.")
        }

        val refreshRequested = parameters["refresh"].isTruthy() || !Files.exists(reportPath)
        if (refreshRequested) {
            val writeCheck = simulateCapabilityKey(
                companyId = companyId,
                agentId = agentId,
                capability = CapabilityKey.KNOWLEDGE_GRAPH_WRITE,
                action = "knowledge.graph-write",
                path = root.toString()
            )
            if (!writeCheck.allowed || writeCheck.requiresApproval) {
                return@withContext blockedSkillRunResult(skill, runId, writeCheck, "Graphify refresh is blocked by policy.")
            }
            if (!commandAvailability("graphify")) {
                return@withContext SkillRunResult(
                    skill = skill.name,
                    status = "FAILED_SETUP",
                    capability = baseCapability,
                    runId = runId,
                    summary = "graphify is not available on PATH.",
                    error = "graphify command was not found."
                )
            }
            val updateOutputPath = evidenceDir.resolve("graphify-update.txt")
            val updateOutput = runSkillProcess(listOf("graphify", "update", "."), root, timeoutSeconds = 180)
            Files.writeString(updateOutputPath, updateOutput)
            actions += "graphify update ."
            evidence += SkillRunEvidence(
                type = "command-output",
                path = updateOutputPath.toString(),
                title = "graphify update output",
                detail = updateOutput.take(500)
            )
        }

        if (Files.exists(reportPath)) {
            val reportSummary = Files.readString(reportPath)
                .lineSequence()
                .filter { it.isNotBlank() }
                .take(80)
                .joinToString("\n")
            actions += "read graphify-out/GRAPH_REPORT.md"
            evidence += SkillRunEvidence(
                type = "file",
                path = reportPath.toString(),
                title = "Graph report",
                detail = "graphify-out/GRAPH_REPORT.md"
            )
            output.appendLine(reportSummary)
        }

        input?.trim()?.takeIf { it.isNotBlank() }?.let { question ->
            if (!commandAvailability("graphify")) {
                return@withContext SkillRunResult(
                    skill = skill.name,
                    status = "FAILED_SETUP",
                    capability = baseCapability,
                    runId = runId,
                    actions = actions,
                    evidence = evidence,
                    summary = "graphify explain could not run because graphify is not available.",
                    output = output.toString().trim().takeIf { it.isNotBlank() },
                    error = "graphify command was not found."
                )
            }
            val explainOutputPath = evidenceDir.resolve("graphify-explain.txt")
            val explainOutput = runSkillProcess(listOf("graphify", "explain", question), root, timeoutSeconds = 120)
            Files.writeString(explainOutputPath, explainOutput)
            actions += "graphify explain"
            evidence += SkillRunEvidence(
                type = "command-output",
                path = explainOutputPath.toString(),
                title = "graphify explain output",
                detail = question.take(200)
            )
            output.appendLine()
            output.appendLine(explainOutput)
        }

        if (output.isBlank()) {
            return@withContext SkillRunResult(
                skill = skill.name,
                status = "FAILED_SETUP",
                capability = baseCapability,
                runId = runId,
                actions = actions,
                evidence = evidence,
                summary = "No graphify report or explain output was available.",
                error = "graphify-out/GRAPH_REPORT.md is missing and refresh did not produce it."
            )
        }
        SkillRunResult(
            skill = skill.name,
            status = "COMPLETED",
            capability = baseCapability,
            runId = runId,
            actions = actions,
            evidence = evidence,
            summary = "Graphify returned repository map evidence.",
            output = output.toString().trim().take(8_000)
        )
    }

    private suspend fun runBrowserSmokeSkill(
        skill: SkillCatalogEntry,
        companyId: String,
        agentId: String,
        input: String?,
        parameters: Map<String, String>,
        runId: String,
        baseCapability: CapabilitySimulationResult
    ): SkillRunResult {
        val url = parameters["url"]?.trim()?.takeIf { it.isNotBlank() }
            ?: extractFirstUrl(input.orEmpty())
            ?: return SkillRunResult(
                skill = skill.name,
                status = "FAILED_SETUP",
                capability = baseCapability,
                runId = runId,
                summary = "Browser smoke needs a URL.",
                error = "Missing required parameter: url"
            )
        val trace = parameters["trace"].isTruthy()
        val stepsJson = parameters["stepsJson"]?.trim()?.takeIf { it.isNotBlank() }
        val planned = planBrowserSmoke(
            BrowserSmokeRequest(
                companyId = companyId,
                agentId = agentId,
                url = url,
                screenshot = true,
                trace = trace,
                record = false,
                interact = !stepsJson.isNullOrBlank()
            )
        )
        if (planned.status != "READY") {
            val capability = planned.checks.firstOrNull { !it.allowed || it.requiresApproval } ?: baseCapability
            return SkillRunResult(
                skill = skill.name,
                status = planned.status,
                capability = capability,
                runId = runId,
                summary = planned.message,
                output = planned.command.joinToString(" "),
                error = planned.error
            )
        }

        val evidenceDir = skillRunEvidenceDir(skill.name, runId)
        val screenshotPath = evidenceDir.resolve("screenshot.png")
        val tracePath = if (trace) evidenceDir.resolve("trace.zip") else null
        val result = browserSkillRunner.execute(
            BrowserSkillCommand(
                url = url,
                screenshotPath = screenshotPath.toString(),
                stepsJson = stepsJson,
                tracePath = tracePath?.toString(),
                maxRuntimeSeconds = parameters["timeoutSeconds"]?.toIntOrNull()?.coerceAtLeast(15) ?: 60
            )
        )
        val evidence = buildList {
            result.screenshotPath?.let {
                add(SkillRunEvidence(type = "screenshot", path = it, title = "Browser screenshot", detail = result.finalUrl))
            }
            result.tracePath?.let {
                add(SkillRunEvidence(type = "trace", path = it, title = "Browser trace", detail = result.finalUrl))
            }
            add(SkillRunEvidence(type = "url", url = result.finalUrl, title = "Final URL", detail = result.title))
        }
        return SkillRunResult(
            skill = skill.name,
            status = "COMPLETED",
            capability = baseCapability,
            runId = runId,
            actions = result.actions,
            evidence = evidence,
            summary = "Visited ${result.finalUrl} (${result.consoleErrors.size} console error(s)).",
            output = buildString {
                appendLine("Title: ${result.title.ifBlank { "(untitled)" }}")
                appendLine("Final URL: ${result.finalUrl}")
                if (result.consoleErrors.isNotEmpty()) {
                    appendLine("Console errors:")
                    result.consoleErrors.take(20).forEach { appendLine("- $it") }
                }
            }.trim()
        )
    }

    private suspend fun runMarketingSkill(
        skill: SkillCatalogEntry,
        companyId: String,
        agentId: String,
        input: String?,
        parameters: Map<String, String>,
        runId: String,
        baseCapability: CapabilitySimulationResult
    ): SkillRunResult {
        val objective = parameters["objective"]?.trim()?.takeIf { it.isNotBlank() }
            ?: input?.trim()?.takeIf { it.isNotBlank() }
            ?: return SkillRunResult(
                skill = skill.name,
                status = "FAILED_SETUP",
                capability = baseCapability,
                runId = runId,
                summary = "${skill.displayName} needs an objective.",
                error = "Missing required objective/input."
            )
        val requestedChannels = parseSkillChannels(parameters["channels"])
        val channels = when (skill.name) {
            "content-publisher" -> constrainMarketingSkillChannels(
                companyId = companyId,
                agentId = agentId,
                delegationPolicyId = parameters["delegationPolicyId"],
                requestedChannels = requestedChannels,
                predicate = ::isOwnedContentChannel
            )
            "social-publisher" -> constrainMarketingSkillChannels(
                companyId = companyId,
                agentId = agentId,
                delegationPolicyId = parameters["delegationPolicyId"],
                requestedChannels = requestedChannels,
                predicate = ::isOrganicSocialChannel
            )
            else -> requestedChannels
        }
        if (channels == null) {
            return SkillRunResult(
                skill = skill.name,
                status = "DENIED",
                capability = baseCapability,
                runId = runId,
                summary = "${skill.displayName} was denied because the requested channel is outside its scope.",
                error = "Requested channels: ${requestedChannels.joinToString(", ")}"
            )
        }
        if (skill.name in setOf("content-publisher", "social-publisher") && channels.isEmpty()) {
            return SkillRunResult(
                skill = skill.name,
                status = "DENIED",
                capability = baseCapability,
                runId = runId,
                summary = "${skill.displayName} has no delegated channel inside its scope.",
                error = "No MarketingDelegationPolicy channel matched ${skill.name}."
            )
        }
        val run = runCatching {
            createMarketingRun(
                MarketingRunRequest(
                    companyId = companyId,
                    agentId = agentId,
                    objective = objective,
                    channels = channels,
                    delegationPolicyId = parameters["delegationPolicyId"]?.trim()?.takeIf { it.isNotBlank() }
                )
            )
        }.getOrElse { error ->
            return SkillRunResult(
                skill = skill.name,
                status = if ((error.message ?: "").contains("not found", ignoreCase = true)) "FAILED_SETUP" else "FAILED",
                capability = baseCapability,
                runId = runId,
                summary = "${skill.displayName} could not start a MarketingRun.",
                error = error.message ?: error::class.simpleName.orEmpty()
            )
        }
        return SkillRunResult(
            skill = skill.name,
            status = when (run.status) {
                MarketingRunStatus.COMPLETED -> "COMPLETED"
                MarketingRunStatus.DENIED -> "DENIED"
                MarketingRunStatus.FAILED -> "FAILED"
                MarketingRunStatus.RUNNING -> "RUNNING"
            },
            capability = baseCapability,
            runId = runId,
            actions = run.actions.map { "${it.channel}: ${it.status}${it.error?.let { error -> " · $error" }.orEmpty()}" },
            evidence = run.actions.flatMap { action ->
                buildList {
                    action.screenshotPath?.let {
                        add(SkillRunEvidence(type = "screenshot", path = it, title = "${action.channel} screenshot", detail = action.targetUrl))
                    }
                    action.postedUrl?.let {
                        add(SkillRunEvidence(type = "url", url = it, title = "${action.channel} result URL", detail = action.status.name))
                    }
                }
            },
            summary = "MarketingRun ${run.id} finished with ${run.status}.",
            output = run.actions.joinToString("\n") { action ->
                "${action.channel}: ${action.status} -> ${action.postedUrl ?: action.targetUrl}${action.error?.let { " ($it)" }.orEmpty()}"
            },
            error = run.error
        )
    }

    private suspend fun runMarketingReportSkill(
        skill: SkillCatalogEntry,
        companyId: String,
        agentId: String,
        input: String?,
        parameters: Map<String, String>,
        runId: String,
        baseCapability: CapabilitySimulationResult
    ): SkillRunResult = withContext(Dispatchers.IO) {
        val analyticsCheck = checkSkillCapability(companyId, agentId, ActionKind.MARKETING_ANALYTICS_READ)
        if (!analyticsCheck.allowed || analyticsCheck.requiresApproval) {
            return@withContext blockedSkillRunResult(skill, runId, analyticsCheck, "${skill.displayName} needs delegated analytics read access.")
        }
        val state = stateStore.load()
        val policies = state.marketingDelegationPolicies.filter { it.companyId == companyId && it.agentId == agentId }
        val runs = state.marketingRuns.filter { it.companyId == companyId }
            .sortedByDescending { it.createdAt }
            .take(20)
        val successfulActions = runs.flatMap { it.actions }.count { it.status == MarketingActionStatus.SUCCEEDED }
        val failedActions = runs.flatMap { it.actions }.count { it.status == MarketingActionStatus.FAILED }
        val deniedActions = runs.flatMap { it.actions }.count { it.status == MarketingActionStatus.DENIED }
        val report = buildString {
            appendLine("# ${skill.displayName}")
            appendLine()
            appendLine("Input: ${input?.trim()?.ifBlank { "(none)" } ?: "(none)"}")
            appendLine("Policies: ${policies.size}")
            appendLine("Recent runs: ${runs.size}")
            appendLine("Succeeded actions: $successfulActions")
            appendLine("Failed actions: $failedActions")
            appendLine("Denied actions: $deniedActions")
            appendLine()
            appendLine("## Recent evidence")
            if (runs.isEmpty()) {
                appendLine("- No MarketingRun evidence is available yet.")
            } else {
                runs.forEach { run ->
                    appendLine("- ${run.id}: ${run.status} · ${run.channels.joinToString(", ")} · ${run.objective.take(120)}")
                    run.actions.take(5).forEach { action ->
                        appendLine("  - ${action.channel}: ${action.status} ${action.postedUrl ?: action.error ?: action.targetUrl}")
                    }
                }
            }
            appendLine()
            appendLine("## Next actions")
            appendLine("- Keep publishing inside configured MarketingDelegationPolicy channels.")
            appendLine("- Add analytics/browser dashboard accounts if this report needs live dashboard screenshots.")
        }
        val evidenceDir = skillRunEvidenceDir(skill.name, runId)
        val reportPath = evidenceDir.resolve("report.md")
        Files.writeString(reportPath, report)
        val evidence = mutableListOf(
            SkillRunEvidence(type = "file", path = reportPath.toString(), title = "${skill.displayName} report")
        )
        val actions = mutableListOf("summarized ${runs.size} marketing run(s)")
        val url = parameters["url"]?.trim()?.takeIf { it.isNotBlank() }
        if (url != null) {
            val screenshotCheck = checkSkillCapability(
                companyId = companyId,
                agentId = agentId,
                action = ActionKind.BROWSER_SCREENSHOT,
                networkTarget = browserNetworkTarget(url)?.hostWithPort
            )
            if (!screenshotCheck.allowed || screenshotCheck.requiresApproval) {
                return@withContext blockedSkillRunResult(skill, runId, screenshotCheck, "Analytics dashboard screenshot is blocked by policy.")
            }
            val screenshotPath = evidenceDir.resolve("dashboard.png")
            val browser = browserSkillRunner.execute(
                BrowserSkillCommand(url = url, screenshotPath = screenshotPath.toString(), maxRuntimeSeconds = 60)
            )
            actions += browser.actions
            evidence += SkillRunEvidence(type = "screenshot", path = screenshotPath.toString(), title = "Dashboard screenshot", detail = browser.finalUrl)
        }
        SkillRunResult(
            skill = skill.name,
            status = "COMPLETED",
            capability = baseCapability,
            runId = runId,
            actions = actions,
            evidence = evidence,
            summary = "${skill.displayName} summarized ${runs.size} recent run(s).",
            output = report.take(8_000)
        )
    }

    private suspend fun runVideoPlanSkill(
        skill: SkillCatalogEntry,
        companyId: String,
        agentId: String,
        input: String?,
        parameters: Map<String, String>,
        runId: String,
        baseCapability: CapabilitySimulationResult
    ): SkillRunResult = withContext(Dispatchers.IO) {
        val request = VideoPlanRequest(
            companyId = companyId,
            agentId = agentId,
            issueId = parameters["issueId"]?.trim()?.takeIf { it.isNotBlank() },
            prompt = parameters["prompt"]?.trim()?.takeIf { it.isNotBlank() } ?: input?.trim()?.takeIf { it.isNotBlank() },
            projectPath = parameters["projectPath"]?.trim()?.takeIf { it.isNotBlank() },
            provider = parameters["provider"]?.trim()?.takeIf { it.isNotBlank() }
        )
        val plan = planVideoScript(request)
        if (plan.status != "READY") {
            val capability = plan.checks.firstOrNull { !it.allowed || it.requiresApproval } ?: baseCapability
            return@withContext SkillRunResult(
                skill = skill.name,
                status = plan.status,
                capability = capability,
                runId = runId,
                summary = plan.message,
                output = plan.command.joinToString(" "),
                error = plan.error
            )
        }
        val provider = request.provider ?: "remotion"
        val evidenceDir = skillRunEvidenceDir(skill.name, runId)
        val planPath = evidenceDir.resolve("plan.md")
        val commandsPath = evidenceDir.resolve("commands.sh")
        val prompt = request.prompt ?: "Create a concise Cotor product video."
        val planMarkdown = buildString {
            appendLine("# Video Plan")
            appendLine()
            appendLine("- Provider: $provider")
            request.issueId?.let { appendLine("- Issue: $it") }
            request.projectPath?.let { appendLine("- Project path: $it") }
            appendLine("- Prompt: $prompt")
            appendLine()
            appendLine("## Storyboard")
            appendLine("1. Open with the current product state and the user problem.")
            appendLine("2. Show the autonomous company workflow and evidence trail.")
            appendLine("3. End with the measurable outcome and next action.")
            appendLine()
            appendLine("## Validation")
            appendLine("- Render/upload are intentionally not executed by video-plan.")
            appendLine("- Use the command artifact after a separate video render capability is delegated.")
        }
        val commands = when (provider.lowercase()) {
            "ffmpeg" -> "ffmpeg -y -f lavfi -i color=c=0x0B0F17:s=1920x1080:d=8 -vf drawtext=text='Cotor':fontcolor=white:fontsize=72:x=(w-text_w)/2:y=(h-text_h)/2 output.mp4"
            "manim" -> "manim -pql scene.py CotorScene"
            else -> "npx remotion render src/Video.tsx CotorVideo out/cotor-video.mp4"
        }
        Files.writeString(planPath, planMarkdown)
        Files.writeString(commandsPath, "#!/usr/bin/env bash\nset -euo pipefail\n$commands\n")
        SkillRunResult(
            skill = skill.name,
            status = "COMPLETED",
            capability = baseCapability,
            runId = runId,
            actions = listOf("wrote video plan", "wrote validation commands"),
            evidence = listOf(
                SkillRunEvidence(type = "file", path = planPath.toString(), title = "Video plan"),
                SkillRunEvidence(type = "file", path = commandsPath.toString(), title = "Video commands")
            ),
            summary = "Created local video planning artifacts without rendering or uploading.",
            output = planMarkdown
        )
    }

    private suspend fun persistSkillRunResult(
        companyId: String,
        agentId: String,
        result: SkillRunResult,
        startedAt: Long
    ) {
        val runId = result.runId ?: return
        val now = System.currentTimeMillis()
        val record = SkillRunRecord(
            id = runId,
            companyId = companyId,
            agentId = agentId,
            skill = result.skill,
            status = result.status,
            actions = result.actions,
            evidence = result.evidence,
            summary = result.summary,
            output = result.output,
            error = result.error,
            createdAt = startedAt,
            updatedAt = now,
            completedAt = if (result.status == "RUNNING") null else now
        )
        stateMutex.withLock {
            val state = stateStore.load()
            stateStore.save(
                state.copy(skillRuns = state.skillRuns.filterNot { it.id == runId } + record)
                    .recordCompanyActivity(
                        companyId = companyId,
                        source = "skill-run",
                        title = "Ran ${result.skill}",
                        detail = "${result.status} · ${result.summary ?: result.error ?: "Skill run finished."}"
                    )
                    .withDerivedMetrics()
            )
        }
    }

    private fun skillRunEvidenceDir(skillName: String, runId: String): Path =
        stateStore.appHome()
            .resolve("runtime")
            .resolve("skills")
            .resolve(safeSkillPathSegment(skillName))
            .resolve(safeSkillPathSegment(runId))
            .also { Files.createDirectories(it) }

    private fun safeSkillPathSegment(raw: String): String =
        raw.trim().replace(Regex("[^A-Za-z0-9._-]"), "_").ifBlank { "skill" }

    private fun skillRunMetadata(
        skill: SkillCatalogEntry,
        input: String?,
        parameters: Map<String, String>
    ): Map<String, String> =
        (
            mapOf(
                "skill" to skill.name,
                "skillName" to skill.name,
                "displayName" to skill.displayName,
                "input" to input.orEmpty().take(500)
            ) + parameters.mapKeys { "parameter.${it.key}" }.mapValues { it.value.take(500) }
            )
            .filterValues { it.isNotBlank() }

    private suspend fun checkSkillCapability(
        companyId: String,
        agentId: String,
        action: ActionKind,
        skill: String? = null,
        path: String? = null,
        networkTarget: String? = null,
        channel: String? = null
    ): CapabilitySimulationResult =
        simulateAgentCapability(
            companyId = companyId,
            agentId = agentId,
            action = action.wireValue,
            path = path,
            networkTarget = networkTarget,
            skill = skill,
            channel = channel
        )

    private suspend fun simulateCapabilityKey(
        companyId: String,
        agentId: String,
        capability: CapabilityKey,
        action: String,
        path: String? = null
    ): CapabilitySimulationResult {
        val state = stateStore.load()
        val definition = state.companyAgentDefinitions.firstOrNull { definition ->
            definition.companyId == companyId &&
                (
                    definition.id.equals(agentId, ignoreCase = true) ||
                        definition.agentCli.equals(agentId, ignoreCase = true) ||
                        definition.title.equals(agentId, ignoreCase = true)
                    )
        }
        val resolvedAgentId = definition?.id ?: agentId
        val setting = state.agentCapabilityProfiles
            .firstOrNull { it.companyId == companyId && it.agentId == resolvedAgentId }
            ?.settings
            ?.get(capability)
            ?: defaultAgentCapabilitySettings().getValue(capability)
        val mode = if (!setting.enabled) CapabilityMode.DISABLED else setting.mode
        val allowedByPath = if (setting.pathAllowlist.isEmpty()) {
            true
        } else {
            val requestedPath = path?.let { runCatching { Path.of(it).toAbsolutePath().normalize() }.getOrNull() }
            requestedPath != null && setting.pathAllowlist.any { allowlist ->
                val allowlistPath = runCatching { Path.of(allowlist).toAbsolutePath().normalize() }.getOrNull()
                allowlistPath != null && (requestedPath == allowlistPath || requestedPath.startsWith(allowlistPath))
            }
        }
        val scope = "company=$companyId agent=$resolvedAgentId"
        return when {
            !allowedByPath -> CapabilitySimulationResult(
                action = action,
                capability = capability,
                mode = mode,
                allowed = false,
                reason = "Capability $capability rejected $action for $scope because path allowlist constraints did not match."
            )
            mode == CapabilityMode.DISABLED -> CapabilitySimulationResult(
                action = action,
                capability = capability,
                mode = mode,
                allowed = false,
                reason = "Capability $capability is disabled for $scope."
            )
            mode == CapabilityMode.PROPOSE_ONLY || mode == CapabilityMode.APPROVAL_REQUIRED -> CapabilitySimulationResult(
                action = action,
                capability = capability,
                mode = mode,
                allowed = true,
                requiresApproval = true,
                reason = "Capability $capability requires pre-delegation for $scope."
            )
            else -> CapabilitySimulationResult(
                action = action,
                capability = capability,
                mode = mode,
                allowed = true,
                reason = "Capability $capability allows $action for $scope."
            )
        }
    }

    private fun blockedSkillRunResult(
        skill: SkillCatalogEntry,
        runId: String,
        capability: CapabilitySimulationResult,
        summary: String
    ): SkillRunResult =
        SkillRunResult(
            skill = skill.name,
            status = if (capability.requiresApproval) "APPROVAL_REQUIRED" else "DENIED",
            capability = capability,
            runId = runId,
            summary = summary,
            error = capability.reason
        )

    private suspend fun runSkillProcess(
        command: List<String>,
        workingDirectory: Path,
        timeoutSeconds: Long
    ): String = withContext(Dispatchers.IO) {
        val process = ProcessBuilder(command)
            .directory(workingDirectory.toFile())
            .redirectErrorStream(true)
            .start()
        val finished = process.waitFor(timeoutSeconds, java.util.concurrent.TimeUnit.SECONDS)
        val output = process.inputStream.bufferedReader().readText()
        if (!finished) {
            process.destroyForcibly()
            error("${command.joinToString(" ")} timed out after ${timeoutSeconds}s.")
        }
        if (process.exitValue() != 0) {
            error(output.ifBlank { "${command.joinToString(" ")} failed with exit ${process.exitValue()}." })
        }
        output
    }

    private fun parseSkillChannels(raw: String?): List<String> =
        raw.orEmpty()
            .split(",", "|", "\n")
            .map { it.trim().lowercase() }
            .filter { it.isNotBlank() }
            .distinct()

    private suspend fun constrainMarketingSkillChannels(
        companyId: String,
        agentId: String,
        delegationPolicyId: String?,
        requestedChannels: List<String>,
        predicate: (String) -> Boolean
    ): List<String>? =
        if (requestedChannels.isEmpty()) {
            defaultMarketingPolicyChannels(companyId, agentId, delegationPolicyId, predicate)
        } else if (requestedChannels.all(predicate)) {
            requestedChannels
        } else {
            null
        }

    private suspend fun defaultMarketingPolicyChannels(
        companyId: String,
        agentId: String,
        delegationPolicyId: String?,
        predicate: (String) -> Boolean
    ): List<String> =
        runCatching {
            val state = stateStore.load()
            val definition = state.companyAgentDefinitions.firstOrNull {
                it.companyId == companyId && it.id == agentId
            } ?: return@runCatching emptyList()
            val policy = resolveMarketingPolicy(
                state = state,
                request = MarketingRunRequest(
                    companyId = companyId,
                    agentId = agentId,
                    objective = "skill channel resolution",
                    delegationPolicyId = delegationPolicyId?.trim()?.takeIf { it.isNotBlank() }
                ),
                definition = definition
            )
            policy.channelAccounts
                .map { it.channel.trim().lowercase() }
                .filter { it.isNotBlank() && predicate(it) }
                .distinct()
        }.getOrDefault(emptyList())

    private fun isOwnedContentChannel(channel: String): Boolean =
        channel.lowercase() in setOf("web", "cms", "blog", "site", "docs")

    private fun isOrganicSocialChannel(channel: String): Boolean =
        channel.lowercase() in setOf("x", "twitter", "linkedin", "social", "mastodon", "threads")

    private fun String?.isTruthy(): Boolean =
        this?.trim()?.lowercase() in setOf("true", "1", "yes", "y", "on")

    private fun extractFirstUrl(text: String): String? =
        Regex("""https?://[^\s)>\]]+""").find(text)?.value?.trimEnd('.', ',', ';')

    suspend fun planBrowserSmoke(request: BrowserSmokeRequest): BrowserSmokeResult {
        val normalizedUrl = request.url.trim()
        require(normalizedUrl.isNotBlank()) { "Browser smoke URL is required." }
        val browserTarget = browserNetworkTarget(normalizedUrl)
        if (browserTarget == null) {
            return BrowserSmokeResult(
                url = normalizedUrl,
                status = "DENIED",
                checks = emptyList(),
                command = listOf("playwright", "open", normalizedUrl),
                message = "Browser smoke requires an http(s) URL with a host.",
                error = "Unsupported browser smoke URL: $normalizedUrl"
            )
        }
        val networkTarget = browserTarget.hostWithPort
        val requestedActions = buildList {
            add(ActionKind.BROWSER_READ)
            if (request.screenshot) add(ActionKind.BROWSER_SCREENSHOT)
            if (request.trace) add(ActionKind.BROWSER_TRACE)
            if (request.record) add(ActionKind.BROWSER_RECORD)
            if (request.interact) add(ActionKind.BROWSER_INTERACT)
            if (!browserTarget.isLocal) add(ActionKind.BROWSER_EXTERNAL_DOMAIN)
        }
        val checks = requestedActions.map { action ->
            simulateAgentCapability(
                companyId = request.companyId,
                agentId = request.agentId,
                action = action.wireValue,
                networkTarget = networkTarget
            )
        }
        val denied = checks.firstOrNull { !it.allowed }
        val approvalRequired = checks.firstOrNull { it.requiresApproval }
        val command = buildList {
            add("playwright")
            add("open")
            add(normalizedUrl)
            if (request.screenshot) add("--screenshot")
            if (request.trace) add("--trace")
            if (request.record) add("--record")
        }
        return when {
            denied != null -> BrowserSmokeResult(
                url = normalizedUrl,
                status = "DENIED",
                checks = checks,
                command = command,
                message = "Browser smoke is blocked by ${denied.capability}.",
                error = denied.reason
            )
            approvalRequired != null -> BrowserSmokeResult(
                url = normalizedUrl,
                status = "APPROVAL_REQUIRED",
                checks = checks,
                command = command,
                message = "Browser smoke requires approval before running.",
                error = approvalRequired.reason
            )
            else -> BrowserSmokeResult(
                url = normalizedUrl,
                status = "READY",
                checks = checks,
                command = command,
                message = "Browser smoke is allowed. Run the command with the browser runtime and attach evidence."
            )
        }
    }

    private data class BrowserTarget(val hostWithPort: String, val isLocal: Boolean)

    private fun browserNetworkTarget(url: String): BrowserTarget? = runCatching {
        val uri = URI(url)
        val scheme = uri.scheme?.lowercase()
        if (scheme != "http" && scheme != "https") return@runCatching null
        uri.host?.let { host ->
            val port = uri.port.takeIf { it > 0 }?.let { ":$it" }.orEmpty()
            val hostWithPort = "$host$port"
            BrowserTarget(hostWithPort = hostWithPort, isLocal = isLocalBrowserTarget(host))
        }
    }.getOrNull()

    private fun isLocalBrowserTarget(target: String): Boolean {
        val host = target.trim('[', ']').lowercase()
        return host == "localhost" || host == "127.0.0.1" || host == "::1"
    }

    suspend fun listMarketingDelegationPolicies(
        companyId: String? = null,
        agentId: String? = null
    ): List<MarketingDelegationPolicy> =
        stateStore.load().marketingDelegationPolicies
            .filter { companyId == null || it.companyId == companyId }
            .filter { agentId == null || it.agentId == agentId }
            .sortedWith(compareBy<MarketingDelegationPolicy> { it.companyId }.thenBy { it.agentId }.thenByDescending { it.updatedAt })

    suspend fun listMarketingRuns(
        companyId: String? = null,
        agentId: String? = null
    ): List<MarketingRunRecord> =
        stateStore.load().marketingRuns
            .filter { companyId == null || it.companyId == companyId }
            .filter { agentId == null || it.agentId == agentId }
            .sortedByDescending { it.createdAt }

    suspend fun marketingRun(runId: String): MarketingRunRecord? =
        stateStore.load().marketingRuns.firstOrNull { it.id == runId }

    suspend fun upsertMarketingDelegationPolicy(
        request: UpsertMarketingDelegationPolicyRequest
    ): MarketingDelegationPolicy = stateMutex.withLock {
        val state = stateStore.load()
        val company = state.companies.firstOrNull { it.id == request.companyId }
            ?: throw IllegalArgumentException("Company not found: ${request.companyId}")
        val definition = state.companyAgentDefinitions.firstOrNull { it.companyId == company.id && it.id == request.agentId }
            ?: throw IllegalArgumentException("Company agent not found: ${request.agentId}")
        require(isMarketingOperatorAgent(state, definition)) {
            "MarketingDelegationPolicy can only be attached to a Marketing Operator agent."
        }
        val now = System.currentTimeMillis()
        val existing = request.id
            ?.let { id -> state.marketingDelegationPolicies.firstOrNull { it.id == id } }
            ?: state.marketingDelegationPolicies.firstOrNull { it.companyId == company.id && it.agentId == definition.id }
        val policy = sanitizeMarketingDelegationPolicyRequest(request, existing, now)
        val currentProfile = state.agentCapabilityProfiles.firstOrNull { it.companyId == company.id && it.agentId == definition.id }
            ?: AgentCapabilityProfile(companyId = company.id, agentId = definition.id)
        val profile = currentProfile.copy(
            settings = currentProfile.settings + marketingPolicyCapabilitySettings(policy),
            updatedAt = now
        )
        val nextState = state.copy(
            marketingDelegationPolicies = state.marketingDelegationPolicies.filterNot { it.id == policy.id } + policy,
            agentCapabilityProfiles = state.agentCapabilityProfiles.filterNot { it.companyId == company.id && it.agentId == definition.id } + profile
        ).recordCompanyActivity(
            companyId = company.id,
            source = "marketing-delegation",
            title = "Updated Marketing Operator policy",
            detail = "${definition.title} · ${policy.channelAccounts.map { it.channel }.joinToString(", ")}"
        ).withDerivedMetrics()
        stateStore.save(nextState)
        policy
    }

    suspend fun createMarketingRun(request: MarketingRunRequest): MarketingRunRecord {
        val prepared = stateMutex.withLock {
            val state = stateStore.load()
            val company = state.companies.firstOrNull { it.id == request.companyId }
                ?: throw IllegalArgumentException("Company not found: ${request.companyId}")
            val definition = state.companyAgentDefinitions.firstOrNull { it.companyId == company.id && it.id == request.agentId }
                ?: throw IllegalArgumentException("Company agent not found: ${request.agentId}")
            val policy = resolveMarketingPolicy(state, request, definition)
            val channels = request.channels
                .map { it.trim() }
                .filter { it.isNotBlank() }
                .distinctBy { it.lowercase() }
                .ifEmpty { policy.channelAccounts.map { it.channel }.distinctBy { channel -> channel.lowercase() } }
            val now = System.currentTimeMillis()
            val run = MarketingRunRecord(
                companyId = company.id,
                agentId = definition.id,
                objective = request.objective.trim(),
                channels = channels,
                delegationPolicyId = policy.id,
                createdAt = now,
                updatedAt = now
            )
            stateStore.save(
                state.copy(marketingRuns = state.marketingRuns + run)
                    .recordCompanyActivity(
                        companyId = company.id,
                        source = "marketing-run",
                        title = "Started Marketing Operator run",
                        detail = channels.joinToString(", ")
                    )
                    .withDerivedMetrics()
            )
            PreparedMarketingRun(run = run, policy = policy, definition = definition)
        }
        val completed = executeMarketingRun(prepared)
        stateMutex.withLock {
            val state = stateStore.load()
            stateStore.save(
                state.copy(marketingRuns = state.marketingRuns.filterNot { it.id == completed.id } + completed)
                    .recordCompanyActivity(
                        companyId = completed.companyId,
                        source = "marketing-run",
                        title = "Finished Marketing Operator run",
                        detail = "${completed.status} · ${completed.actions.size} action(s)"
                    )
                    .withDerivedMetrics()
            )
        }
        return completed
    }

    private data class PreparedMarketingRun(
        val run: MarketingRunRecord,
        val policy: MarketingDelegationPolicy,
        val definition: CompanyAgentDefinition
    )

    private suspend fun executeMarketingRun(prepared: PreparedMarketingRun): MarketingRunRecord {
        val run = prepared.run
        val policy = prepared.policy
        validateMarketingRunPolicy(policy, run)?.let { reason ->
            val denied = marketingDeniedAction(run, policy, run.channels.firstOrNull().orEmpty(), reason)
            return finishMarketingRun(run, MarketingRunStatus.DENIED, listOf(denied), reason)
        }
        val actions = mutableListOf<MarketingActionRecord>()
        for (channel in run.channels) {
            val account = policy.channelAccounts.firstOrNull { it.channel.equals(channel, ignoreCase = true) }
            if (account == null) {
                actions += marketingDeniedAction(run, policy, channel, "Channel is outside the MarketingDelegationPolicy: $channel")
                continue
            }
            val targetUrl = marketingTargetUrl(policy, account)
            if (targetUrl == null) {
                actions += marketingDeniedAction(run, policy, channel, "Channel has no allowed target domain: $channel")
                continue
            }
            val browserTarget = browserNetworkTarget(targetUrl)
            if (browserTarget == null) {
                actions += marketingDeniedAction(run, policy, channel, "Marketing browser target must be http(s): $targetUrl")
                continue
            }
            val idempotencyKey = marketingIdempotencyKey(policy, run.objective, channel, browserTarget.hostWithPort)
            val previous = stateStore.load().marketingRuns
                .asSequence()
                .flatMap { it.actions.asSequence() }
                .firstOrNull { it.idempotencyKey == idempotencyKey && it.status == MarketingActionStatus.SUCCEEDED }
            if (previous != null) {
                actions += previous.copy(
                    id = UUID.randomUUID().toString(),
                    runId = run.id,
                    channel = channel,
                    status = MarketingActionStatus.SKIPPED,
                    error = "Idempotency key already posted by ${previous.runId}.",
                    updatedAt = System.currentTimeMillis()
                )
                continue
            }
            val publishAction = if (channel.equals("web", ignoreCase = true) || channel.equals("cms", ignoreCase = true)) {
                ActionKind.WEB_PUBLISH
            } else {
                ActionKind.SOCIAL_POST_CREATE
            }
            val checks = marketingCapabilityChecks(
                companyId = run.companyId,
                agentId = run.agentId,
                channel = channel,
                networkTarget = browserTarget.hostWithPort,
                includeExternal = !browserTarget.isLocal,
                includeLoginFlow = !policy.browserSessionRef.isNullOrBlank() || policy.secretRefs.isNotEmpty() || account.secretRefs.isNotEmpty(),
                publishAction = publishAction
            )
            val blocked = checks.firstOrNull { !it.allowed || it.requiresApproval }
            if (blocked != null) {
                actions += marketingDeniedAction(
                    run = run,
                    policy = policy,
                    channel = channel,
                    reason = "Capability ${blocked.capability} blocked marketing action: ${blocked.reason}",
                    targetUrl = targetUrl,
                    idempotencyKey = idempotencyKey
                )
                continue
            }
            val command = MarketingBrowserCommand(
                channel = channel,
                objective = run.objective,
                targetUrl = withMarketingUtm(targetUrl, run.id, channel),
                inputSummary = marketingInputSummary(run.objective, policy),
                browserSessionRef = policy.browserSessionRef,
                screenshotPath = marketingScreenshotPath(run.id, channel).toString(),
                maxRuntimeSeconds = policy.maxRuntimeSeconds
            )
            actions += runCatching {
                marketingBrowserRunner.execute(command)
            }.fold(
                onSuccess = { result ->
                    MarketingActionRecord(
                        runId = run.id,
                        channel = channel,
                        targetUrl = targetUrl,
                        inputSummary = result.inputSummary,
                        postedUrl = result.postedUrl,
                        screenshotPath = result.screenshotPath,
                        utm = "utm_source=cotor&utm_medium=organic&utm_campaign=${run.id}&utm_content=$channel",
                        status = MarketingActionStatus.SUCCEEDED,
                        idempotencyKey = idempotencyKey
                    )
                },
                onFailure = { error ->
                    MarketingActionRecord(
                        runId = run.id,
                        channel = channel,
                        targetUrl = targetUrl,
                        inputSummary = command.inputSummary,
                        screenshotPath = command.screenshotPath,
                        status = MarketingActionStatus.FAILED,
                        idempotencyKey = idempotencyKey,
                        error = error.message ?: error::class.simpleName.orEmpty()
                    )
                }
            )
        }
        val status = when {
            actions.any { it.status == MarketingActionStatus.FAILED } -> MarketingRunStatus.FAILED
            actions.any { it.status == MarketingActionStatus.DENIED } -> MarketingRunStatus.DENIED
            else -> MarketingRunStatus.COMPLETED
        }
        val error = actions.firstOrNull { it.status == MarketingActionStatus.DENIED || it.status == MarketingActionStatus.FAILED }?.error
        return finishMarketingRun(run, status, actions, error)
    }

    private suspend fun marketingCapabilityChecks(
        companyId: String,
        agentId: String,
        channel: String,
        networkTarget: String,
        includeExternal: Boolean,
        includeLoginFlow: Boolean,
        publishAction: ActionKind
    ): List<CapabilitySimulationResult> {
        val actions = buildList {
            add(ActionKind.BROWSER_READ)
            add(ActionKind.BROWSER_INTERACT)
            if (includeExternal) add(ActionKind.BROWSER_EXTERNAL_DOMAIN)
            if (includeLoginFlow) add(ActionKind.BROWSER_LOGIN_FLOW)
            add(publishAction)
        }
        return actions.map { action ->
            simulateAgentCapability(
                companyId = companyId,
                agentId = agentId,
                action = action.wireValue,
                networkTarget = networkTarget,
                channel = channel
            )
        }
    }

    private fun finishMarketingRun(
        run: MarketingRunRecord,
        status: MarketingRunStatus,
        actions: List<MarketingActionRecord>,
        error: String?
    ): MarketingRunRecord {
        val now = System.currentTimeMillis()
        return run.copy(
            status = status,
            actions = actions,
            updatedAt = now,
            completedAt = now,
            error = error
        )
    }

    private fun marketingDeniedAction(
        run: MarketingRunRecord,
        policy: MarketingDelegationPolicy,
        channel: String,
        reason: String,
        targetUrl: String = "",
        idempotencyKey: String = marketingIdempotencyKey(policy, run.objective, channel.ifBlank { "none" }, targetUrl)
    ): MarketingActionRecord = MarketingActionRecord(
        runId = run.id,
        channel = channel.ifBlank { "none" },
        targetUrl = targetUrl,
        inputSummary = marketingInputSummary(run.objective, policy),
        status = MarketingActionStatus.DENIED,
        idempotencyKey = idempotencyKey,
        error = reason
    )

    private suspend fun validateMarketingRunPolicy(
        policy: MarketingDelegationPolicy,
        run: MarketingRunRecord
    ): String? {
        if (run.objective.isBlank()) {
            return "Marketing objective is required."
        }
        if (run.channels.isEmpty()) {
            return "Marketing run requires at least one channel."
        }
        val allowedChannels = policy.channelAccounts.map { it.channel.lowercase() }.toSet()
        val outsideChannels = run.channels.filterNot { it.lowercase() in allowedChannels }
        if (outsideChannels.isNotEmpty()) {
            return "Channels are outside the MarketingDelegationPolicy: ${outsideChannels.joinToString(", ")}"
        }
        marketingPolicyTextViolation(policy, run.objective)?.let { return it }
        val state = stateStore.load()
        val usedToday = marketingPostCountToday(state, policy, System.currentTimeMillis())
        val newPostCount = run.channels.count { channel ->
            val account = policy.channelAccounts.firstOrNull { it.channel.equals(channel, ignoreCase = true) }
            val targetUrl = account?.let { marketingTargetUrl(policy, it) }
            val browserTarget = targetUrl?.let(::browserNetworkTarget)
            if (browserTarget == null) {
                true
            } else {
                val key = marketingIdempotencyKey(policy, run.objective, channel, browserTarget.hostWithPort)
                state.marketingRuns
                    .asSequence()
                    .flatMap { it.actions.asSequence() }
                    .none { it.idempotencyKey == key && it.status == MarketingActionStatus.SUCCEEDED }
            }
        }
        if (usedToday + newPostCount > policy.dailyPostLimit.coerceAtLeast(0)) {
            return "MarketingDelegationPolicy daily post limit would be exceeded: used=$usedToday requested=$newPostCount limit=${policy.dailyPostLimit}."
        }
        return null
    }

    private fun marketingPolicyTextViolation(policy: MarketingDelegationPolicy, objective: String): String? {
        val normalizedObjective = objective.lowercase()
        policy.forbiddenTerms.firstOrNull { term ->
            term.isNotBlank() && normalizedObjective.contains(term.lowercase())
        }?.let { return "Marketing objective contains a forbidden term: $it" }
        policy.prohibitedActions.firstOrNull { action ->
            val normalizedAction = action.lowercase()
            normalizedAction.isNotBlank() &&
                (
                    normalizedObjective.contains(normalizedAction) ||
                        normalizedObjective.contains(normalizedAction.replace("-", " "))
                    )
        }?.let { return "Marketing objective requests a prohibited action: $it" }
        return null
    }

    private fun marketingPostCountToday(
        state: DesktopAppState,
        policy: MarketingDelegationPolicy,
        now: Long
    ): Int {
        val startOfDay = LocalDate.now(ZoneId.systemDefault())
            .atStartOfDay(ZoneId.systemDefault())
            .toInstant()
            .toEpochMilli()
        return state.marketingRuns
            .filter { it.delegationPolicyId == policy.id && it.createdAt >= startOfDay && it.createdAt <= now }
            .sumOf { run ->
                run.actions.count { it.status == MarketingActionStatus.SUCCEEDED }
            }
    }

    private fun resolveMarketingPolicy(
        state: DesktopAppState,
        request: MarketingRunRequest,
        definition: CompanyAgentDefinition
    ): MarketingDelegationPolicy {
        require(isMarketingOperatorAgent(state, definition)) {
            "Marketing runs can only be created for a Marketing Operator agent."
        }
        return request.delegationPolicyId
            ?.let { policyId ->
                state.marketingDelegationPolicies.firstOrNull {
                    it.id == policyId && it.companyId == request.companyId && it.agentId == definition.id
                }
            }
            ?: state.marketingDelegationPolicies.firstOrNull { it.companyId == request.companyId && it.agentId == definition.id }
            ?: throw IllegalArgumentException("MarketingDelegationPolicy not found for agent: ${definition.id}")
    }

    private fun sanitizeMarketingDelegationPolicyRequest(
        request: UpsertMarketingDelegationPolicyRequest,
        existing: MarketingDelegationPolicy?,
        now: Long
    ): MarketingDelegationPolicy {
        val allowedDomains = request.allowedDomains.map { it.trim() }.filter { it.isNotBlank() }.distinctBy { it.lowercase() }
        val accounts = request.channelAccounts
            .mapNotNull { account ->
                val channel = account.channel.trim().lowercase()
                if (channel.isBlank()) {
                    null
                } else {
                    MarketingChannelAccount(
                        channel = channel,
                        accountRef = account.accountRef.trim().ifBlank { channel },
                        allowedDomains = account.allowedDomains.map { it.trim() }.filter { it.isNotBlank() }.distinctBy { it.lowercase() },
                        secretRefs = account.secretRefs.map { it.trim() }.filter { it.isNotBlank() }.distinct()
                    )
                }
            }
            .distinctBy { it.channel }
        require(allowedDomains.isNotEmpty()) { "MarketingDelegationPolicy requires at least one allowed domain." }
        require(accounts.isNotEmpty()) { "MarketingDelegationPolicy requires at least one channel account." }
        return MarketingDelegationPolicy(
            id = existing?.id ?: request.id?.trim()?.takeIf { it.isNotBlank() } ?: UUID.randomUUID().toString(),
            companyId = request.companyId,
            agentId = request.agentId,
            name = request.name.trim().ifBlank { "Owned+Social" },
            allowedDomains = allowedDomains,
            channelAccounts = accounts.map { account ->
                if (account.allowedDomains.isEmpty()) {
                    account.copy(allowedDomains = allowedDomains)
                } else {
                    account
                }
            },
            dailyPostLimit = request.dailyPostLimit.coerceAtLeast(0),
            forbiddenTerms = request.forbiddenTerms.map { it.trim() }.filter { it.isNotBlank() }.distinct(),
            brandTone = request.brandTone?.trim()?.takeIf { it.isNotBlank() },
            prohibitedActions = request.prohibitedActions
                .ifEmpty { defaultMarketingProhibitedActions() }
                .map { it.trim() }
                .filter { it.isNotBlank() }
                .distinct(),
            secretRefs = request.secretRefs.map { it.trim() }.filter { it.isNotBlank() }.distinct(),
            browserSessionRef = request.browserSessionRef?.trim()?.takeIf { it.isNotBlank() },
            maxRuntimeSeconds = request.maxRuntimeSeconds.coerceAtLeast(15),
            createdAt = existing?.createdAt ?: now,
            updatedAt = now
        )
    }

    private fun marketingPolicyCapabilitySettings(policy: MarketingDelegationPolicy): Map<CapabilityKey, AgentCapabilitySetting> {
        val domains = (policy.allowedDomains + policy.channelAccounts.flatMap { it.allowedDomains })
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .distinctBy { it.lowercase() }
        val channels = policy.channelAccounts.map { it.channel }.distinctBy { it.lowercase() }
        val refs = (policy.secretRefs + policy.channelAccounts.flatMap { it.secretRefs }).distinct()
        val notes = "Opened by MarketingDelegationPolicy ${policy.name}; out-of-policy marketing/browser actions are DENIED, not routed to approval."
        val autoSetting = AgentCapabilitySetting(
            enabled = true,
            mode = CapabilityMode.AUTO,
            domainAllowlist = domains,
            channelAllowlist = channels,
            secretRefs = refs,
            maxRuntimeSeconds = policy.maxRuntimeSeconds,
            requiresEvidence = true,
            requiresReview = false,
            notes = notes
        )
        return mapOf(
            CapabilityKey.BROWSER_READ to autoSetting,
            CapabilityKey.BROWSER_INTERACT to autoSetting,
            CapabilityKey.BROWSER_EXTERNAL_DOMAIN to autoSetting,
            CapabilityKey.BROWSER_LOGIN_FLOW to autoSetting,
            CapabilityKey.WEB_PUBLISH to autoSetting,
            CapabilityKey.SOCIAL_POST_CREATE to autoSetting,
            CapabilityKey.MARKETING_ANALYTICS_READ to autoSetting
        )
    }

    private fun isMarketingOperatorAgent(state: DesktopAppState, definition: CompanyAgentDefinition): Boolean {
        if (definition.title.equals("Marketing Operator", ignoreCase = true)) {
            return true
        }
        val profile = state.agentCapabilityProfiles.firstOrNull { it.companyId == definition.companyId && it.agentId == definition.id }
        return profile?.settings?.get(CapabilityKey.SKILL_RUN)
            ?.skillAllowlist
            .orEmpty()
            .any { allowedSkill -> marketingSkillNames.any { it.equals(allowedSkill, ignoreCase = true) } }
    }

    private fun marketingTargetUrl(
        policy: MarketingDelegationPolicy,
        account: MarketingChannelAccount
    ): String? {
        val raw = account.allowedDomains.firstOrNull()
            ?: policy.allowedDomains.firstOrNull()
            ?: return null
        return if (raw.contains("://")) raw else "https://$raw"
    }

    private fun marketingInputSummary(objective: String, policy: MarketingDelegationPolicy): String {
        val tone = policy.brandTone?.let { " Tone: $it" }.orEmpty()
        return (objective.trim() + tone).take(1_000)
    }

    private fun marketingScreenshotPath(runId: String, channel: String): Path =
        stateStore.appHome()
            .resolve("runtime")
            .resolve("marketing-browser")
            .resolve("screenshots")
            .resolve("${safeMarketingPathSegment(runId)}-${safeMarketingPathSegment(channel)}.png")

    private fun withMarketingUtm(targetUrl: String, runId: String, channel: String): String {
        val separator = if (targetUrl.contains("?")) "&" else "?"
        return targetUrl + separator +
            "utm_source=cotor&utm_medium=organic&utm_campaign=${safeMarketingPathSegment(runId)}&utm_content=${safeMarketingPathSegment(channel)}"
    }

    private fun marketingIdempotencyKey(
        policy: MarketingDelegationPolicy,
        objective: String,
        channel: String,
        target: String
    ): String {
        val raw = "${policy.id}|${policy.companyId}|${policy.agentId}|${channel.lowercase()}|${target.lowercase()}|${objective.trim().lowercase()}"
        val digest = MessageDigest.getInstance("SHA-256").digest(raw.toByteArray())
        return digest.joinToString("") { "%02x".format(it) }
    }

    private fun safeMarketingPathSegment(raw: String): String =
        raw.trim().replace(Regex("[^A-Za-z0-9._-]"), "_").ifBlank { "marketing" }

