    suspend fun syncGitHubProvider(companyId: String): GitHubSyncResponse {
        val refreshedCount = stateMutex.withLock {
            val state = stateStore.load()
            val company = state.companies.firstOrNull { it.id == companyId }
                ?: throw IllegalArgumentException("Company not found: $companyId")
            val candidates = state.reviewQueue
                .filter { it.companyId == companyId }
                .filter { it.pullRequestNumber != null && !it.worktreePath.isNullOrBlank() }

            if (candidates.isEmpty()) {
                return@withLock 0
            }

            val refreshedMetadata = candidates.mapNotNull { item ->
                val worktreePath = item.worktreePath?.takeIf { it.isNotBlank() } ?: return@mapNotNull null
                val pullRequestNumber = item.pullRequestNumber ?: return@mapNotNull null
                val refreshed = runCatching {
                    gitWorkspaceService.refreshPullRequestMetadata(Path.of(worktreePath), pullRequestNumber)
                }.getOrNull() ?: return@mapNotNull null
                item to refreshed
            }

            val refreshedByIssueId = refreshedMetadata.associateBy { it.first.issueId }
            val mergedIssueIds = mutableSetOf<String>()
            val closedIssueIds = mutableSetOf<String>()
            val recoveredIssueIds = mutableSetOf<String>()
            val failingIssueIds = mutableSetOf<String>()
            val updatedIssues = state.issues.map { issue ->
                val queueItem = refreshedByIssueId[issue.id] ?: return@map issue
                val existingQueueItem = queueItem.first
                val refreshed = queueItem.second
                val pullRequestState = refreshed.pullRequestState?.uppercase()
                val failingChecks = checksFailing(refreshed.checksSummary)
                val passingChecks = checksExplicitlyPassing(refreshed.checksSummary)
                val nextStatus = when {
                    pullRequestState == "MERGED" -> IssueStatus.DONE
                    pullRequestState == "CLOSED" -> IssueStatus.BLOCKED
                    pullRequestState == "OPEN" && failingChecks && issue.status in setOf(IssueStatus.IN_REVIEW, IssueStatus.READY_FOR_CEO) -> IssueStatus.BLOCKED
                    issue.status == IssueStatus.BLOCKED && passingChecks -> recoveredIssueStatus(issue, existingQueueItem)
                    else -> issue.status
                }
                when {
                    pullRequestState == "MERGED" -> mergedIssueIds += issue.id
                    pullRequestState == "CLOSED" -> closedIssueIds += issue.id
                    pullRequestState == "OPEN" && failingChecks -> failingIssueIds += issue.id
                    issue.status == IssueStatus.BLOCKED && passingChecks -> recoveredIssueIds += issue.id
                }
                issue.copy(
                    status = nextStatus,
                    pullRequestNumber = refreshed.pullRequestNumber ?: issue.pullRequestNumber,
                    pullRequestUrl = refreshed.pullRequestUrl ?: issue.pullRequestUrl,
                    pullRequestState = refreshed.pullRequestState ?: issue.pullRequestState,
                    mergeResult = if (pullRequestState == "MERGED") "MERGED" else issue.mergeResult,
                    providerBlockReason = when {
                        pullRequestState == "MERGED" -> null
                        pullRequestState == "CLOSED" -> "GitHub sync found that the linked pull request was closed before merge."
                        failingChecks -> refreshed.checksSummary?.takeIf { it.isNotBlank() } ?: issue.providerBlockReason
                        passingChecks -> null
                        else -> issue.providerBlockReason
                    },
                    transitionReason = when {
                        pullRequestState == "MERGED" -> "GitHub sync confirmed that the linked PR merged."
                        pullRequestState == "CLOSED" -> "GitHub sync found that the linked PR was closed before merge."
                        pullRequestState == "OPEN" && failingChecks -> "GitHub sync found failing required checks on the linked PR."
                        issue.status == IssueStatus.BLOCKED && passingChecks -> "GitHub sync confirmed that required checks recovered."
                        else -> issue.transitionReason
                    },
                    updatedAt = System.currentTimeMillis()
                )
            }
            val updatedReviewQueue = state.reviewQueue.map { item ->
                val refreshed = refreshedMetadata.firstOrNull { it.first.id == item.id }?.second ?: return@map item
                val pullRequestState = refreshed.pullRequestState?.uppercase()
                val failingChecks = checksFailing(refreshed.checksSummary)
                val passingChecks = checksExplicitlyPassing(refreshed.checksSummary)
                val nextStatus = when {
                    pullRequestState == "MERGED" -> ReviewQueueStatus.MERGED
                    pullRequestState == "CLOSED" -> ReviewQueueStatus.CHANGES_REQUESTED
                    pullRequestState == "OPEN" && failingChecks -> ReviewQueueStatus.FAILED_CHECKS
                    item.status == ReviewQueueStatus.FAILED_CHECKS && passingChecks -> recoveredReviewQueueStatus(item)
                    else -> item.status
                }
                item.copy(
                    status = nextStatus,
                    pullRequestState = refreshed.pullRequestState ?: item.pullRequestState,
                    checksSummary = refreshed.checksSummary ?: item.checksSummary,
                    mergeability = refreshed.mergeability ?: item.mergeability,
                    providerBlockReason = when {
                        pullRequestState == "MERGED" -> null
                        pullRequestState == "CLOSED" -> "GitHub sync found that the linked pull request was closed before merge."
                        failingChecks -> refreshed.checksSummary?.takeIf { it.isNotBlank() } ?: item.providerBlockReason
                        passingChecks -> null
                        else -> item.providerBlockReason
                    },
                    updatedAt = System.currentTimeMillis()
                )
            }
            val approvalIssuesToComplete = updatedReviewQueue
                .filter { it.status == ReviewQueueStatus.MERGED && !it.approvalIssueId.isNullOrBlank() }
                .mapNotNull { it.approvalIssueId }
                .toSet()
            val settledReviewQueue = updatedReviewQueue.filterNot { it.status == ReviewQueueStatus.MERGED }
            val issuesWithApprovalSettled = updatedIssues.map { issue ->
                if (issue.id in approvalIssuesToComplete) {
                    issue.copy(
                        status = IssueStatus.DONE,
                        providerBlockReason = null,
                        transitionReason = "GitHub sync confirmed merge completion for the approved pull request.",
                        updatedAt = System.currentTimeMillis()
                    )
                } else {
                    issue
                }
            }

            refreshedMetadata.forEach { (item, metadata) ->
                val checks = parseChecks(metadata.checksSummary)
                gitHubControlPlaneService.recordSnapshot(
                    snapshot = PullRequestSnapshot(
                        number = metadata.pullRequestNumber ?: return@forEach,
                        url = metadata.pullRequestUrl,
                        state = metadata.pullRequestState,
                        mergeability = metadata.mergeability,
                        checksSummary = metadata.checksSummary,
                        checks = checks,
                        mergeRequirement = MergeRequirement(
                            requiredChecks = checks.map { it.name },
                            reviewDecision = metadata.reviewState
                        ),
                        mergeQueueState = MergeQueueState(
                            state = when {
                                metadata.pullRequestState.equals("MERGED", ignoreCase = true) -> "merged"
                                metadata.mergeability.equals("DIRTY", ignoreCase = true) -> "blocked"
                                else -> "ready"
                            }
                        ),
                        companyId = companyId,
                        issueId = item.issueId,
                        runId = item.runId,
                        branchName = item.branchName
                    ),
                    eventType = "sync",
                    detail = "Synced PR #${metadata.pullRequestNumber ?: "unknown"} for company ${company.name}"
                )
                updatedIssues.firstOrNull { it.id == item.issueId }?.let { issue ->
                    provenanceService.recordIssueRunLink(companyId = companyId, goalId = issue.goalId, issueId = issue.id, runId = item.runId)
                }
            }

            var nextState = state.copy(
                issues = issuesWithApprovalSettled,
                reviewQueue = settledReviewQueue
            )
            if (mergedIssueIds.isNotEmpty()) {
                nextState = nextState.recordCompanyActivity(
                    companyId = companyId,
                    source = "github-sync",
                    title = "Merged pull requests",
                    detail = "GitHub sync confirmed merged PRs for ${mergedIssueIds.size} issue(s)."
                )
            }
            if (closedIssueIds.isNotEmpty()) {
                nextState = nextState.recordCompanyActivity(
                    companyId = companyId,
                    source = "github-sync",
                    title = "Closed pull requests",
                    detail = "GitHub sync found closed pull requests for ${closedIssueIds.size} issue(s).",
                    severity = "warning"
                )
            }
            if (failingIssueIds.isNotEmpty()) {
                nextState = nextState.recordSignal(
                    source = "github-sync",
                    message = "GitHub sync found failing checks for ${failingIssueIds.size} issue(s).",
                    severity = "warning",
                    companyId = companyId
                )
            }
            if (recoveredIssueIds.isNotEmpty()) {
                nextState = nextState.recordSignal(
                    source = "github-sync",
                    message = "GitHub sync recovered passing checks for ${recoveredIssueIds.size} blocked issue(s).",
                    severity = "info",
                    companyId = companyId
                )
            }
            nextState = applyVerificationProjection(nextState).withDerivedMetrics()
            stateStore.save(nextState)
            knowledgeService.synchronizeFromState(nextState)
            refreshedMetadata.size
        }
        if (refreshedCount > 0) {
            runCatching { runCompanyRuntimeTick(companyId) }
        }
        return GitHubSyncResponse(
            companyId = companyId,
            syncedPullRequests = refreshedCount,
            resumedRuntimeTick = refreshedCount > 0
        )
    }

    suspend fun getTask(taskId: String): AgentTask? =
        stateStore.load().tasks.firstOrNull { it.id == taskId }

    suspend fun getIssue(issueId: String): CompanyIssue? =
        stateStore.load().issues.firstOrNull { it.id == issueId }

    suspend fun getIssueProjected(issueId: String): CompanyIssue? =
        runCatching { issueRuntimeProjection(issueId).issue }
            .getOrElse { getIssue(issueId) }

    suspend fun companyMemorySnapshot(
        companyId: String,
        issueId: String? = null,
        agentProfileId: String? = null
    ): CompanyMemorySnapshotResponse {
        val state = stateStore.load()
        val company = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val issue = when {
            issueId != null -> state.issues.firstOrNull { it.id == issueId && it.companyId == companyId }
                ?: throw IllegalArgumentException("Issue not found for company: $companyId")
            else -> state.issues.firstOrNull { it.companyId == companyId }
        }
        val goal = issue?.goalId
            ?.let { goalId -> state.goals.firstOrNull { it.id == goalId } }
            ?: state.goals
                .filter { it.companyId == companyId && it.status != GoalStatus.COMPLETED }
                .maxByOrNull { it.updatedAt }
        val projectContext = issue?.projectContextId
            ?.let { projectContextId -> state.projectContexts.firstOrNull { it.id == projectContextId } }
            ?: state.projectContexts.firstOrNull { it.companyId == companyId }
        val profiles = ensureOrgProfiles(state.orgProfiles, state.companyAgentDefinitions, state.companies)
        val profile = when {
            agentProfileId != null -> profiles.firstOrNull { it.id == agentProfileId && it.companyId == companyId }
            else -> profiles.firstOrNull { it.companyId == companyId && it.roleName == "CEO" }
                ?: profiles.firstOrNull { it.companyId == companyId }
        } ?: throw IllegalArgumentException("Agent profile not found for company: $companyId")

        return buildCompanyMemorySnapshot(state, company, projectContext, goal, issue, profile).toResponse()
    }

    suspend fun listProblemSignals(companyId: String): List<CompanyProblemSignal> =
        stateStore.load().problemSignals
            .filter { it.companyId == companyId }
            .sortedWith(
                compareByDescending<CompanyProblemSignal> { problemSignalSeverityRank(it.severity) }
                    .thenByDescending { it.updatedAt }
            )

    suspend fun runAutonomyDiscoveryScan(companyId: String): List<CompanyProblemSignal> {
        var changed = false
        stateMutex.withLock {
            val state = stateStore.load()
            if (state.companies.none { it.id == companyId }) {
                throw IllegalArgumentException("Company not found: $companyId")
            }
            val scan = autonomousDiscoveryService.scan(state, companyId)
            if (scan.signals != state.problemSignals) {
                stateStore.save(
                    state.copy(
                        problemSignals = scan.signals
                    ).recordSignal(
                        source = "autonomous-discovery",
                        message = if (scan.changedCount > 0) {
                            "Autonomous discovery recorded ${scan.changedCount} problem signal(s)."
                        } else {
                            "Autonomous discovery found no new internal quality problems."
                        },
                        severity = if (scan.changedCount > 0) "warning" else "info",
                        companyId = companyId
                    ).withDerivedMetrics()
                )
                changed = scan.changedCount > 0
            }
        }
        if (changed) {
            knowledgeService.synchronizeFromState(stateStore.load())
        }
        return listProblemSignals(companyId)
    }

    private suspend fun bindIssueToDurableRun(
        issueId: String,
        runId: String,
        providerBlockReason: String? = null
    ) {
        val approvalPauseId = durableRuntimeApprovalPauseId(runId)
        stateMutex.withLock {
            val state = stateStore.load()
            val issue = state.issues.firstOrNull { it.id == issueId } ?: return@withLock
            val nextIssue = issue.copy(
                durableRunId = runId,
                approvalPauseId = approvalPauseId ?: issue.approvalPauseId,
                providerBlockReason = providerBlockReason ?: issue.providerBlockReason,
                updatedAt = issue.updatedAt
            )
            val nextQueue = state.reviewQueue.map { item ->
                if (item.issueId == issueId) {
                    item.copy(
                        approvalPauseId = approvalPauseId ?: item.approvalPauseId,
                        providerBlockReason = providerBlockReason ?: item.providerBlockReason
                    )
                } else {
                    item
                }
            }
            stateStore.save(
                state.copy(
                    issues = state.issues.map { existing -> if (existing.id == issueId) nextIssue else existing },
                    reviewQueue = nextQueue
                )
            )
        }
    }

    private fun durableRuntimeApprovalPauseId(runId: String?): String? =
        runId
            ?.let { durableRuntimeService.inspectRun(it) }
            ?.approvalPauses
            ?.firstOrNull { it.status.name == "PENDING" }
            ?.id

    private fun providerBlockReasonForIssue(
        nextStatus: IssueStatus,
        run: AgentRun?
    ): String? {
        if (nextStatus != IssueStatus.BLOCKED && nextStatus != IssueStatus.WAITING_FOR_APPROVAL) {
            return null
        }
        return run?.publish?.checksSummary
            ?.takeIf { it.isNotBlank() }
            ?: run?.publish?.error
                ?.takeIf { it.isNotBlank() }
            ?: run?.error
                ?.takeIf { it.isNotBlank() }
    }

    private fun classifyBlockedReason(
        issue: CompanyIssue,
        latestRun: AgentRun?,
        reviewQueueItem: ReviewQueueItem? = null,
        transitionReasonOverride: String? = null
    ): BlockedReasonSnapshot? {
        if (issue.status != IssueStatus.BLOCKED && issue.status != IssueStatus.WAITING_FOR_APPROVAL) {
            return null
        }
        val publishError = latestRun?.let(::effectiveExecutionLogPublishError)
        val checksSummary = latestRun?.publish?.checksSummary?.takeIf { it.isNotBlank() }
            ?: reviewQueueItem?.checksSummary?.takeIf { it.isNotBlank() }
        val mergeability = latestRun?.publish?.mergeability?.takeIf { it.isNotBlank() }
            ?: reviewQueueItem?.mergeability?.takeIf { it.isNotBlank() }
        val signals = listOfNotNull(
            "providerBlockReason" toNonBlank issue.providerBlockReason,
            "transitionReason" toNonBlank (transitionReasonOverride ?: issue.transitionReason),
            "run.error" toNonBlank latestRun?.error,
            "publish.error" toNonBlank publishError,
            "checksSummary" toNonBlank checksSummary,
            "mergeability" toNonBlank mergeability,
            "review.status" toNonBlank reviewQueueItem?.status?.name,
            "qaVerdict" toNonBlank issue.qaVerdict,
            "ceoVerdict" toNonBlank issue.ceoVerdict,
            "sourceSignal" toNonBlank issue.sourceSignal,
            "approvalPauseId" toNonBlank (issue.approvalPauseId ?: reviewQueueItem?.approvalPauseId),
            "blockedBy" toNonBlank issue.blockedBy.takeIf { it.isNotEmpty() }?.joinToString(",")
        )
        val combined = signals.joinToString("\n") { it.second }.lowercase()
        val detail = blockedReasonDetail(signals)

        fun has(vararg needles: String): Boolean = needles.any { combined.contains(it.lowercase()) }
        fun source(vararg preferred: String): String =
            preferred.firstNotNullOfOrNull { name ->
                signals.firstOrNull { it.first == name }?.first
            } ?: signals.firstOrNull()?.first ?: "classifier"
        fun snapshot(
            code: BlockedReasonCode,
            summary: String,
            source: String,
            retryable: Boolean
        ) = BlockedReasonSnapshot(
            code = code,
            summary = summary,
            detail = detail,
            source = source,
            retryable = retryable
        )

        return when {
            issue.status == IssueStatus.WAITING_FOR_APPROVAL ||
                issue.approvalPauseId != null ||
                reviewQueueItem?.approvalPauseId != null ||
                has("requires approval", "approval required", "waiting for approval", "github_pr_create requires approval") ->
                snapshot(
                    code = BlockedReasonCode.CAPABILITY_APPROVAL_REQUIRED,
                    summary = "Capability approval is required before execution can continue.",
                    source = source("approvalPauseId", "providerBlockReason", "publish.error", "run.error", "transitionReason"),
                    retryable = true
                )
            has(INTERRUPTED_RUN_ERROR, INTERRUPTED_ISSUE_REASON, "app-server stopped", "runtime stopped while execution", "exit=143", "exit 143", "exit code 143", "exited with code 143") ->
                snapshot(
                    code = BlockedReasonCode.RUNTIME_INTERRUPTED,
                    summary = "Execution was interrupted by runtime shutdown.",
                    source = source("run.error", "providerBlockReason", "transitionReason"),
                    retryable = true
                )
            issue.sourceSignal == "github-readiness" ||
                has("github is not connected", "no github remote", "origin remote", "no history in common", "gh auth", "github cli is not authenticated") ||
                (has("github") && has("not authenticated", "not configured", "not ready", "missing remote", "pull request create failed")) ->
                snapshot(
                    code = BlockedReasonCode.GITHUB_NOT_READY,
                    summary = "GitHub publishing is not ready.",
                    source = source("sourceSignal", "transitionReason", "providerBlockReason", "publish.error", "run.error"),
                    retryable = true
                )
            mergeability.equals("DIRTY", ignoreCase = true) ||
                has("merge conflict", "does not merge cleanly", "not mergeable", "cannot be cleanly created") ->
                snapshot(
                    code = BlockedReasonCode.MERGE_CONFLICT,
                    summary = "The branch does not merge cleanly with the base branch.",
                    source = source("mergeability", "transitionReason", "providerBlockReason", "publish.error", "run.error"),
                    retryable = true
                )
            reviewQueueItem?.status == ReviewQueueStatus.FAILED_CHECKS || checksFailing(checksSummary) ->
                snapshot(
                    code = BlockedReasonCode.CI_FAILED,
                    summary = "Pull request checks failed.",
                    source = source("checksSummary", "review.status", "providerBlockReason", "transitionReason"),
                    retryable = true
                )
            has("test failed", "tests failed", "failing test", "gradlew test", "test task failed") ->
                snapshot(
                    code = BlockedReasonCode.TEST_FAILED,
                    summary = "Automated tests failed.",
                    source = source("run.error", "providerBlockReason", "transitionReason"),
                    retryable = true
                )
            signals.any { isNoChangesToPublishError(it.second) } ||
                has("no new diff", "no changes to publish", "produced no new diff") ->
                snapshot(
                    code = BlockedReasonCode.NO_CHANGES,
                    summary = "Execution produced no publishable changes.",
                    source = source("publish.error", "run.error", "transitionReason", "providerBlockReason"),
                    retryable = false
                )
            has("not found on path", "command not found", "executable not found", "no such file or directory", "tool unavailable") ->
                snapshot(
                    code = BlockedReasonCode.TOOL_UNAVAILABLE,
                    summary = "A required local tool is unavailable.",
                    source = source("run.error", "providerBlockReason", "transitionReason"),
                    retryable = true
                )
            has("budget", "daily budget", "monthly budget", "cost limit", "spend limit") ->
                snapshot(
                    code = BlockedReasonCode.BUDGET_LIMIT,
                    summary = "The company budget limit blocked execution.",
                    source = source("providerBlockReason", "transitionReason", "run.error"),
                    retryable = false
                )
            issue.qaVerdict.equals("CHANGES_REQUESTED", ignoreCase = true) ||
                has("qa requested changes", "qa_verdict: changes_requested") ->
                snapshot(
                    code = BlockedReasonCode.QA_CHANGES_REQUESTED,
                    summary = "QA requested changes before this can proceed.",
                    source = source("qaVerdict", "transitionReason", "providerBlockReason", "review.status"),
                    retryable = true
                )
            issue.ceoVerdict.equals("CHANGES_REQUESTED", ignoreCase = true) ||
                has("ceo requested changes", "ceo_verdict: changes_requested") ->
                snapshot(
                    code = BlockedReasonCode.CEO_REJECTED,
                    summary = "CEO review rejected the current work.",
                    source = source("ceoVerdict", "transitionReason", "providerBlockReason", "review.status"),
                    retryable = true
                )
            issue.blockedBy.isNotEmpty() || has("blocked by dependency", "dependency blocked", "waiting on dependency") ->
                snapshot(
                    code = BlockedReasonCode.DEPENDENCY_BLOCKED,
                    summary = "A dependency is blocking this issue.",
                    source = source("blockedBy", "transitionReason", "providerBlockReason"),
                    retryable = true
                )
            has("not authenticated", "unauthorized", "oauth", "login required", "api key", "token missing", "auth missing") ->
                snapshot(
                    code = BlockedReasonCode.AUTH_MISSING,
                    summary = "Authentication is missing for a required provider.",
                    source = source("providerBlockReason", "run.error", "publish.error", "transitionReason"),
                    retryable = true
                )
            has("opencode execution failed", "codex execution failed", "provider error", "model_not_found", "invalid_request_error") ->
                snapshot(
                    code = BlockedReasonCode.PROVIDER_ERROR,
                    summary = "The execution provider failed.",
                    source = source("run.error", "providerBlockReason", "transitionReason"),
                    retryable = true
                )
            has(CEO_PLANNING_INVALID_OUTPUT.lowercase()) ->
                snapshot(
                    code = BlockedReasonCode.CEO_PLANNING_INVALID_OUTPUT,
                    summary = "CEO planning did not produce a valid execution graph.",
                    source = source("transitionReason", "run.error", "providerBlockReason"),
                    retryable = true
                )
            else ->
                snapshot(
                    code = BlockedReasonCode.UNKNOWN,
                    summary = "Blocked reason is unknown.",
                    source = source("providerBlockReason", "transitionReason", "run.error", "publish.error"),
                    retryable = false
                )
        }
    }

    private infix fun String.toNonBlank(value: String?): Pair<String, String>? =
        value?.trim()?.takeIf { it.isNotBlank() }?.let { this to it }

    private fun blockedReasonDetail(signals: List<Pair<String, String>>): String? {
        val detail = signals.joinToString("\n") { (source, value) ->
            "$source: ${value.take(1_000)}"
        }.trim()
        return detail.takeIf { it.isNotBlank() }?.let { text ->
            if (text.length <= 2_000) text else text.take(2_000) + "\n[truncated after 2000 characters]"
        }
    }

    private fun issueAttentionSeverity(status: IssueStatus): String =
        if (status == IssueStatus.BLOCKED || status == IssueStatus.WAITING_FOR_APPROVAL) "warning" else "info"

    private fun syntheticCompanyRunPipeline(issue: CompanyIssue?): Pair<Pipeline, PipelineStage> {
        val stage = PipelineStage(id = "company-agent-execution", type = StageType.EXECUTION)
        val name = issue?.kind?.takeIf { it.isNotBlank() }?.let { "company-$it-run" } ?: "company-execution-run"
        return Pipeline(name = name, stages = listOf(stage)) to stage
    }

    private fun createCompanyRunContext(
        runId: String,
        pipeline: Pipeline,
        issue: CompanyIssue?,
        task: AgentTask,
        repository: ManagedRepository
    ): PipelineContext {
        val context = PipelineContext(
            pipelineId = runId,
            pipelineName = pipeline.name,
            totalStages = pipeline.stages.size
        )
        DurableRuntimeFlags.enable(context)
        context.metadata["durableRunId"] = runId
        context.metadata["companyTaskRun"] = "true"
        context.metadata["repositoryPath"] = repository.localPath
        issue?.companyId?.let { context.metadata["companyId"] = it }
        issue?.goalId?.let { context.metadata["goalId"] = it }
        issue?.id?.let { context.metadata["issueId"] = it }
        context.metadata["taskId"] = task.id
        val configPath = Path.of(repository.localPath).resolve("cotor.yaml")
        if (configPath.exists()) {
            context.metadata["configPath"] = configPath.toString()
        }
        return context
    }

    private fun parseChecks(summary: String?): List<CheckSnapshot> {
        if (summary.isNullOrBlank()) {
            return emptyList()
        }
        return summary.split(';')
            .map { it.trim() }
            .filter { it.isNotBlank() }
            .map { token ->
                val name = token.substringBefore('=').trim()
                val statusPart = token.substringAfter('=', "UNKNOWN").trim()
                val status = statusPart.substringBefore('/').trim()
                val conclusion = statusPart.substringAfter('/', "").trim().ifBlank { null }
                CheckSnapshot(
                    name = name,
                    status = status,
                    conclusion = conclusion
                )
            }
    }

    private fun checksFailing(summary: String?): Boolean {
        if (summary.isNullOrBlank()) return false
        val checks = parseChecks(summary)
        return when {
            checks.isNotEmpty() -> checks.any { check ->
                check.status.equals("COMPLETED", ignoreCase = true) &&
                    !check.conclusion.equals("SUCCESS", ignoreCase = true)
            }
            else -> summary.contains("FAILURE", ignoreCase = true) ||
                summary.contains("ERROR", ignoreCase = true)
        }
    }

    private fun checksExplicitlyPassing(summary: String?): Boolean {
        if (summary.isNullOrBlank()) return false
        val checks = parseChecks(summary)
        return when {
            checks.isNotEmpty() -> checks.all { check ->
                !check.status.equals("COMPLETED", ignoreCase = true) ||
                    check.conclusion.equals("SUCCESS", ignoreCase = true)
            }
            else -> !checksFailing(summary)
        }
    }

    private fun recoveredReviewQueueStatus(item: ReviewQueueItem): ReviewQueueStatus =
        when {
            item.ceoVerdict.equals("APPROVE", ignoreCase = true) -> ReviewQueueStatus.READY_FOR_CEO
            item.qaVerdict.equals("PASS", ignoreCase = true) -> ReviewQueueStatus.READY_FOR_CEO
            else -> ReviewQueueStatus.AWAITING_QA
        }

    private fun recoveredIssueStatus(issue: CompanyIssue, queueItem: ReviewQueueItem? = null): IssueStatus =
        when {
            issue.ceoVerdict.equals("APPROVE", ignoreCase = true) -> IssueStatus.READY_FOR_CEO
            issue.qaVerdict.equals("PASS", ignoreCase = true) -> IssueStatus.READY_FOR_CEO
            queueItem?.ceoVerdict.equals("APPROVE", ignoreCase = true) -> IssueStatus.READY_FOR_CEO
            queueItem?.qaVerdict.equals("PASS", ignoreCase = true) -> IssueStatus.READY_FOR_CEO
            issue.pullRequestUrl != null || issue.pullRequestNumber != null -> IssueStatus.IN_REVIEW
            else -> issue.status
        }

    private fun applyVerificationProjection(state: DesktopAppState): DesktopAppState {
        val issuesById = state.issues.associateBy { it.id }
        val bundlesByIssueId = state.issues.associate { issue ->
            issue.id to verificationBundleService.buildForIssue(
                state = state,
                issue = issue,
                queueItem = state.reviewQueue.filter { it.issueId == issue.id }.maxByOrNull { it.updatedAt }
            )
        }
        val updatedIssues = state.issues.map { issue ->
            val bundle = bundlesByIssueId.getValue(issue.id)
            issue.copy(
                verificationStatus = bundle.outcome.status.name,
                verificationSummary = bundle.outcome.summary,
                lastVerifiedAt = bundle.outcome.verifiedAt
            )
        }
        val updatedReviewQueue = state.reviewQueue.map { item ->
            val bundle = bundlesByIssueId[item.issueId] ?: return@map item
            item.copy(
                verificationStatus = bundle.outcome.status.name,
                verificationSummary = bundle.outcome.summary,
                lastVerifiedAt = bundle.outcome.verifiedAt
            )
        }
        return state.copy(
            issues = updatedIssues,
            reviewQueue = updatedReviewQueue
        )
    }

    suspend fun updateGoalAutonomy(goalId: String, enabled: Boolean): CompanyGoal = stateMutex.withLock {
        val state = stateStore.load()
        val goal = state.goals.firstOrNull { it.id == goalId }
            ?: throw IllegalArgumentException("Goal not found: $goalId")
        val updated = goal.copy(
            autonomyEnabled = enabled,
            status = when {
                enabled && goal.status == GoalStatus.PAUSED -> GoalStatus.ACTIVE
                !enabled && goal.status == GoalStatus.ACTIVE -> GoalStatus.PAUSED
                else -> goal.status
            },
            updatedAt = System.currentTimeMillis()
        )
        val nextState = state.copy(
            goals = state.goals.map { if (it.id == goalId) updated else it }
        ).recordSignal(
            companyId = updated.companyId,
            projectContextId = updated.projectContextId,
            source = "goal-policy",
            message = if (enabled) "Enabled autonomy for ${updated.title}" else "Paused autonomy for ${updated.title}",
            goalId = goalId
        ).withDerivedMetrics()
        stateStore.save(nextState)
        updated
    }

    suspend fun createCompany(
        name: String,
        rootPath: String,
        defaultBaseBranch: String? = null,
        autonomyEnabled: Boolean = true,
        operatorAutomationMode: OperatorAutomationMode? = null,
        dailyBudgetCents: Int? = null,
        monthlyBudgetCents: Int? = null
    ): Company = stateMutex.withLock {
        // Company creation is the bridge from an arbitrary checkout on disk to the product's
        // higher-level operating model. The method normalizes the repo root, ensures a managed
        // repository/workspace exists, seeds default org roles, and records the first persisted
        // company snapshot in one serialized transaction.
        val now = System.currentTimeMillis()
        val loadedState = stateStore.load()
        val initialBackendKind = initialCompanyBackendKind(loadedState)
        val requestedRoot = Path.of(rootPath).toAbsolutePath().normalize()
        val repositoryRoot = runCatching {
            gitWorkspaceService.ensureInitializedRepositoryRoot(
                requestedRoot,
                defaultBaseBranch
            )
        }.getOrElse { error ->
            if (loadedState.repositories.any { sameRepositoryRoot(it.localPath, requestedRoot) }) {
                requestedRoot
            } else {
                throw error
            }
        }
        val repository = upsertRepositoryForPath(loadedState.repositories, repositoryRoot, now)
        val requestedBranch = defaultBaseBranch?.trim()?.takeIf { it.isNotBlank() }
        val resolvedBranch = if (requestedBranch == null) {
            repository.defaultBranch
        } else {
            val requestedBranchExists = runCatching {
                gitWorkspaceService.hasLocalBranch(repositoryRoot, requestedBranch)
            }.getOrDefault(true)
            if (requestedBranchExists || repository.defaultBranch.isBlank()) {
                requestedBranch
            } else {
                repository.defaultBranch
            }
        }
        val existing = loadedState.companies.firstOrNull {
            Path.of(it.rootPath).toAbsolutePath().normalize() == repositoryRoot.toAbsolutePath().normalize()
        }
        if (existing != null) {
            val refreshed = existing.copy(
                name = name.trim().ifEmpty { existing.name },
                repositoryId = repository.id,
                defaultBaseBranch = resolvedBranch,
                autonomyEnabled = autonomyEnabled,
                operatorAutomationMode = operatorAutomationMode ?: existing.operatorAutomationMode,
                dailyBudgetCents = normalizeBudgetOverride(dailyBudgetCents, existing.dailyBudgetCents),
                monthlyBudgetCents = normalizeBudgetOverride(monthlyBudgetCents, existing.monthlyBudgetCents),
                updatedAt = now
            )
            val refreshedState = loadedState.copy(
                repositories = mergeRepository(loadedState.repositories, repository),
                companies = loadedState.companies.map { if (it.id == existing.id) refreshed else it }
            )
            val workspaceState = ensureCompanyWorkspace(refreshedState, refreshed, now).first
            val nextState = workspaceState.recordCompanyActivity(
                companyId = refreshed.id,
                source = "company",
                title = "Updated company",
                detail = refreshed.name
            ).withDerivedMetrics()
            stateStore.save(nextState)
            publishCompanyEvent(
                companyId = refreshed.id,
                type = "company.updated",
                title = "Updated company",
                detail = refreshed.name
            )
            return@withLock refreshed
        }

        val companyId = UUID.randomUUID().toString()
        val company = Company(
            id = companyId,
            name = name.trim().ifEmpty { repositoryRoot.fileName.toString() },
            rootPath = repositoryRoot.toString(),
            repositoryId = repository.id,
            defaultBaseBranch = resolvedBranch,
            backendKind = initialBackendKind,
            autonomyEnabled = autonomyEnabled,
            operatorAutomationMode = operatorAutomationMode ?: OperatorAutomationMode.AGENT_APPROVED,
            dailyBudgetCents = dailyBudgetCents?.takeIf { it > 0 },
            monthlyBudgetCents = monthlyBudgetCents?.takeIf { it > 0 },
            createdAt = now,
            updatedAt = now
        )
        val context = CompanyProjectContext(
            id = UUID.randomUUID().toString(),
            companyId = companyId,
            name = company.name,
            slug = slugify(company.name),
            contextDocPath = companyContextRoot(company).resolve("projects/default.md").toString(),
            lastUpdatedAt = now
        )
        val seededDefinitions = seedCompanyAgentDefinitions(companyId, now)
        val seededCapabilityProfiles = seedCompanyAgentCapabilityProfiles(company, seededDefinitions, now)
        val baseState = loadedState.copy(
            repositories = mergeRepository(loadedState.repositories, repository),
            companies = loadedState.companies + company,
            projectContexts = loadedState.projectContexts + context,
            companyAgentDefinitions = loadedState.companyAgentDefinitions + seededDefinitions,
            agentCapabilityProfiles = loadedState.agentCapabilityProfiles + seededCapabilityProfiles,
            companyRuntimes = loadedState.companyRuntimes + CompanyRuntimeSnapshot(companyId = companyId, backendKind = company.backendKind)
        )
        val workspaceState = ensureCompanyWorkspace(baseState, company, now).first
        val nextState = workspaceState.recordCompanyActivity(
            companyId = companyId,
            projectContextId = context.id,
            source = "company",
            title = "Created company",
            detail = company.name
        ).withDerivedMetrics()
        stateStore.save(nextState)
        writeCompanyContextSnapshot(nextState, company, context)
        publishCompanyEvent(
            companyId = company.id,
            type = "company.created",
            title = "Created company",
            detail = company.name
        )
        company
    }

    private fun initialCompanyBackendKind(state: DesktopAppState): ExecutionBackendKind {
        val preferred = state.backendSettings.defaultBackendKind
        if (preferred != ExecutionBackendKind.CODEX_APP_SERVER) {
            return preferred
        }
        val codexConfig = state.backendSettings.backends.firstOrNull { it.kind == ExecutionBackendKind.CODEX_APP_SERVER }
        return if (codexConfig == null || !codexConfig.enabled || !codexAppServerManager.executableAvailable(codexConfig)) {
            ExecutionBackendKind.LOCAL_COTOR
        } else {
            preferred
        }
    }

    suspend fun updateCompany(
        companyId: String,
        name: String? = null,
        defaultBaseBranch: String? = null,
        autonomyEnabled: Boolean? = null,
        backendKind: ExecutionBackendKind? = null,
        dailyBudgetCents: Int? = null,
        monthlyBudgetCents: Int? = null
    ): Company = stateMutex.withLock {
        val state = stateStore.load()
        val company = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val updated = company.copy(
            name = name?.trim()?.takeIf { it.isNotBlank() } ?: company.name,
            defaultBaseBranch = defaultBaseBranch?.trim()?.takeIf { it.isNotBlank() } ?: company.defaultBaseBranch,
            backendKind = backendKind ?: company.backendKind,
            autonomyEnabled = autonomyEnabled ?: company.autonomyEnabled,
            dailyBudgetCents = normalizeBudgetOverride(dailyBudgetCents, company.dailyBudgetCents),
            monthlyBudgetCents = normalizeBudgetOverride(monthlyBudgetCents, company.monthlyBudgetCents),
            updatedAt = System.currentTimeMillis()
        )
        val nextState = state.copy(
            companies = state.companies.map { if (it.id == companyId) updated else it }
        ).recordCompanyActivity(
            companyId = updated.id,
            source = "company",
            title = "Updated company",
            detail = updated.name
        ).withDerivedMetrics()
        stateStore.save(nextState)
        nextState.projectContexts.firstOrNull { it.companyId == companyId }?.let { context ->
            writeCompanyContextSnapshot(nextState, updated, context)
        }
        publishCompanyEvent(
            companyId = updated.id,
            type = "company.updated",
            title = "Updated company",
            detail = updated.name
        )
        updated
    }

    suspend fun updateBackendSettings(
        defaultBackendKind: ExecutionBackendKind,
        codePublishMode: CodePublishMode? = null,
        codexLaunchMode: BackendLaunchMode? = null,
        codexCommand: String? = null,
        codexArgs: List<String>? = null,
        codexWorkingDirectory: String? = null,
        codexPort: Int? = null,
        codexStartupTimeoutSeconds: Int? = null,
        codexAppServerBaseUrl: String? = null,
        codexAuthMode: String? = null,
        codexToken: String? = null,
        codexTimeoutSeconds: Int? = null
    ): DesktopSettings = stateMutex.withLock {
        val state = stateStore.load()
        val updatedConfigs = state.backendSettings.backends.map { config ->
            if (config.kind == ExecutionBackendKind.CODEX_APP_SERVER) {
                config.copy(
                    launchMode = codexLaunchMode ?: config.launchMode,
                    command = codexCommand?.trim()?.takeIf { it.isNotBlank() } ?: config.command,
                    args = codexArgs ?: config.args,
                    workingDirectory = codexWorkingDirectory?.trim()?.takeIf { it.isNotBlank() } ?: config.workingDirectory,
                    port = codexPort ?: config.port,
                    startupTimeoutSeconds = codexStartupTimeoutSeconds ?: config.startupTimeoutSeconds,
                    baseUrl = codexAppServerBaseUrl?.trim()?.takeIf { it.isNotBlank() } ?: config.baseUrl,
                    authMode = codexAuthMode?.trim()?.takeIf { it.isNotBlank() } ?: config.authMode,
                    token = codexToken ?: config.token,
                    timeoutSeconds = codexTimeoutSeconds ?: config.timeoutSeconds
                )
            } else {
                config
            }
        }
        stateStore.save(
            state.copy(
                backendSettings = state.backendSettings.copy(
                    defaultBackendKind = defaultBackendKind,
                    codePublishMode = codePublishMode ?: state.backendSettings.codePublishMode,
                    backends = updatedConfigs
                )
            )
        )
        settings()
    }

