    private fun operatorGoalTitleFromMessage(message: String): String =
        message.lineSequence()
            .firstOrNull { it.isNotBlank() }
            ?.trim()
            ?.removePrefix("Create ")
            ?.removePrefix("만들어")
            ?.take(90)
            ?.ifBlank { null }
            ?: "Operator chat goal"

    private fun extractOperatorRemoteUrl(message: String): String? =
        Regex("""https://github\.com/[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+(?:\.git)?""")
            .find(message)
            ?.value

    private data class GroundedOperatorAnswer(
        val message: String,
        val sources: List<OperatorAnswerSource> = emptyList()
    )

    private fun OperatorCommandResponse.toOperatorChatResponse(
        answerSources: List<OperatorAnswerSource> = emptyList()
    ): OperatorChatResponse = OperatorChatResponse(
        message = message,
        automationMode = automationMode,
        actions = actions,
        pendingApprovals = pendingApprovals,
        blockedActions = blockedActions,
        summary = summary,
        answerSources = answerSources
    )

    private suspend fun buildGroundedOperatorChatAnswer(
        companyId: String,
        message: String,
        normalized: String
    ): GroundedOperatorAnswer {
        val state = stateStore.load().withDerivedMetrics()
        val company = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val orgProfiles = ensureOrgProfiles(state.orgProfiles, state.companyAgentDefinitions, state.companies)
        val performance = computeAgentPerformance(state, companyId, orgProfiles)
        val companyIssues = state.issues.filter { it.companyId == companyId }
        val companyIssueIds = companyIssues.mapTo(linkedSetOf()) { it.id }
        val companyTasks = state.tasks.filter { task -> task.issueId == null || task.issueId in companyIssueIds }
        val companyTaskIds = companyTasks.mapTo(linkedSetOf()) { it.id }
        val companyRuns = state.runs.filter { it.taskId in companyTaskIds }
        val companyReviews = state.reviewQueue.filter { it.companyId == companyId || it.issueId in companyIssueIds }
        val companyActivity = state.companyActivity.filter { it.companyId == companyId }
        val summary = buildOperatorCompanySummary(companyId)
        val korean = prefersKoreanOperatorAnswer(message)

        return when {
            looksLikePerformanceQuestion(normalized) ->
                buildOperatorPerformanceAnswer(performance, companyIssues, companyRuns, companyReviews, korean)
            looksLikeBlockedQuestion(normalized) ->
                buildOperatorBlockedAnswer(companyIssues, companyActivity, korean)
            looksLikeApprovalOrReviewQuestion(normalized) ->
                buildOperatorReviewAnswer(companyReviews, companyIssues, korean)
            looksLikeRuntimeQuestion(normalized) ->
                buildOperatorRuntimeAnswer(summary, companyRuns, korean)
            else ->
                buildOperatorGeneralAnswer(company, summary, performance, companyIssues, companyActivity, korean)
        }
    }

    private fun buildOperatorPerformanceAnswer(
        performance: List<AgentPerformanceSnapshot>,
        issues: List<CompanyIssue>,
        runs: List<AgentRun>,
        reviews: List<ReviewQueueItem>,
        korean: Boolean
    ): GroundedOperatorAnswer {
        val ranked = performance.sortedWith(
            compareByDescending<AgentPerformanceSnapshot> { it.score ?: -1 }
                .thenByDescending { it.completedIssues }
                .thenBy { it.blockedIssues }
                .thenBy { it.retryCount }
        )
        val best = ranked.firstOrNull()
            ?: return GroundedOperatorAnswer(
                message = if (korean) {
                    "아직 인사평가에 쓸 에이전트 실행 데이터가 없습니다. 이슈 실행, 리뷰, QA 결과가 쌓이면 성과 순위를 답할 수 있습니다."
                } else {
                    "There is not enough agent performance data yet. Once issues, runs, and review outcomes exist, I can rank the team."
                },
                sources = listOf(
                    OperatorAnswerSource(
                        type = "agent-performance",
                        title = "No scoreable agent performance",
                        detail = "issues=${issues.size}, runs=${runs.size}, reviews=${reviews.size}"
                    )
                )
            )

        val scoreText = best.score?.let { "${it}점" } ?: if (korean) "점수 산정 전" else "not scored yet"
        val successText = best.runSuccessRate?.let { "${(it * 100).toInt()}%" } ?: if (korean) "데이터 부족" else "insufficient data"
        val qaText = best.qaPassRate?.let { "${(it * 100).toInt()}%" } ?: if (korean) "데이터 부족" else "insufficient data"
        val message = if (korean) {
            buildString {
                append("${best.agentName}(${best.roleName})가 현재 가장 좋은 에이전트입니다. ")
                append("성과 점수는 $scoreText, 완료 이슈 ${best.completedIssues}개, 실행 성공률 $successText, QA 통과율 ${qaText}입니다.")
                if (best.blockedIssues > 0) append(" 다만 막힌 이슈 ${best.blockedIssues}개가 있어 다음 평가에서 감점 요인이 됩니다.")
                if (best.retryCount > 0) append(" 재시도는 ${best.retryCount}회 기록됐습니다.")
            }
        } else {
            buildString {
                append("${best.agentName} (${best.roleName}) is currently the strongest agent. ")
                append("Score: ${best.score ?: "not scored"}, completed issues: ${best.completedIssues}, run success: $successText, QA pass: $qaText.")
                if (best.blockedIssues > 0) append(" ${best.blockedIssues} blocked issue(s) still weigh against that score.")
                if (best.retryCount > 0) append(" Retry count: ${best.retryCount}.")
            }
        }
        val sources = ranked.take(3).map { snapshot ->
            OperatorAnswerSource(
                type = "agent-performance",
                title = "${snapshot.agentName} · ${snapshot.roleName}",
                detail = "score=${snapshot.score ?: "n/a"}, completed=${snapshot.completedIssues}, active=${snapshot.activeIssues}, blocked=${snapshot.blockedIssues}, runSuccess=${snapshot.runSuccessRate ?: "n/a"}, qaPass=${snapshot.qaPassRate ?: "n/a"}",
                refId = snapshot.agentId
            )
        } + OperatorAnswerSource(
            type = "runtime-scope",
            title = "Performance evidence scope",
            detail = "issues=${issues.size}, runs=${runs.size}, reviews=${reviews.size}"
        )
        return GroundedOperatorAnswer(message = message, sources = sources)
    }

    private fun buildOperatorBlockedAnswer(
        issues: List<CompanyIssue>,
        activity: List<CompanyActivityItem>,
        korean: Boolean
    ): GroundedOperatorAnswer {
        val blocked = issues.filter { it.status == IssueStatus.BLOCKED }.sortedByDescending { it.updatedAt }
        if (blocked.isEmpty()) {
            return GroundedOperatorAnswer(
                message = if (korean) {
                    "현재 막힌 이슈는 없습니다. 최근 활동 기준으로 차단 상태가 새로 쌓이지 않았습니다."
                } else {
                    "There are no blocked issues right now."
                },
                sources = activity.take(3).map {
                    OperatorAnswerSource("activity", it.title, it.detail, it.id)
                }
            )
        }
        val lead = blocked.first()
        val reason = humanizeOperatorBlockReason(lead.transitionReason ?: lead.providerBlockReason)
        val message = if (korean) {
            "현재 ${blocked.size}개 이슈가 막혀 있습니다. 가장 최근 항목은 \"${lead.title}\"이고, 원인은 $reason 입니다."
        } else {
            "${blocked.size} issue(s) are blocked. The most recent is \"${lead.title}\"; reason: $reason."
        }
        val sources = blocked.take(5).map { issue ->
            OperatorAnswerSource(
                type = "issue",
                title = issue.title,
                detail = humanizeOperatorBlockReason(issue.transitionReason ?: issue.providerBlockReason),
                refId = issue.id
            )
        } + activity.filter { it.title.contains("blocked", ignoreCase = true) || it.severity == "error" }
            .take(3)
            .map { OperatorAnswerSource("activity", it.title, humanizeOperatorBlockReason(it.detail), it.id) }
        return GroundedOperatorAnswer(message = message, sources = sources)
    }

    private fun buildOperatorReviewAnswer(
        reviews: List<ReviewQueueItem>,
        issues: List<CompanyIssue>,
        korean: Boolean
    ): GroundedOperatorAnswer {
        val attention = reviews.filter { it.status != ReviewQueueStatus.MERGED }.sortedByDescending { it.updatedAt }
        val ceoReady = attention.count { it.status == ReviewQueueStatus.READY_FOR_CEO || it.status == ReviewQueueStatus.READY_TO_MERGE }
        val qaReady = attention.count { it.status == ReviewQueueStatus.AWAITING_QA || it.status == ReviewQueueStatus.CHANGES_REQUESTED }
        val message = if (korean) {
            "리뷰 큐에는 처리할 항목 ${attention.size}개가 있습니다. CEO 승인 대기 ${ceoReady}개, QA/수정 확인 ${qaReady}개입니다."
        } else {
            "The review queue has ${attention.size} active item(s): $ceoReady waiting on CEO/merge approval and $qaReady in QA or changes-requested review."
        }
        val issueById = issues.associateBy { it.id }
        val sources = attention.take(5).map { item ->
            OperatorAnswerSource(
                type = "review",
                title = issueById[item.issueId]?.title ?: "Review ${item.id}",
                detail = item.status.name,
                refId = item.id
            )
        }
        return GroundedOperatorAnswer(message = message, sources = sources)
    }

    private fun buildOperatorRuntimeAnswer(
        summary: OperatorCompanySummary,
        runs: List<AgentRun>,
        korean: Boolean
    ): GroundedOperatorAnswer {
        val activeRuns = runs.filter { it.status == AgentRunStatus.RUNNING || it.status == AgentRunStatus.QUEUED }
        val message = if (korean) {
            "런타임은 ${summary.runtimeStatus} 상태입니다. 활성 에이전트 ${summary.activeAgentCount}개, 막힌 이슈 ${summary.blockedIssueCount}개, 승인 대기 ${summary.pendingApprovalCount}개입니다."
        } else {
            "Runtime status is ${summary.runtimeStatus}. Active agents: ${summary.activeAgentCount}, blocked issues: ${summary.blockedIssueCount}, pending approvals: ${summary.pendingApprovalCount}."
        }
        val sources = activeRuns.take(5).map { run ->
            OperatorAnswerSource(
                type = "run",
                title = "${run.agentName} · ${run.status.name}",
                detail = run.output?.take(180) ?: run.error?.take(180),
                refId = run.id
            )
        }
        return GroundedOperatorAnswer(message = message, sources = sources)
    }

    private fun buildOperatorGeneralAnswer(
        company: Company,
        summary: OperatorCompanySummary,
        performance: List<AgentPerformanceSnapshot>,
        issues: List<CompanyIssue>,
        activity: List<CompanyActivityItem>,
        korean: Boolean
    ): GroundedOperatorAnswer {
        val best = performance.firstOrNull { it.score != null }
        val activeIssues = issues.count { it.status in setOf(IssueStatus.PLANNED, IssueStatus.DELEGATED, IssueStatus.IN_PROGRESS, IssueStatus.IN_REVIEW) }
        val message = if (korean) {
            buildString {
                append("${company.name} 상태를 기준으로 답하면, 런타임은 ${summary.runtimeStatus}이고 활성 이슈는 ${activeIssues}개입니다. ")
                append("막힌 이슈 ${summary.blockedIssueCount}개, 리뷰 ${summary.reviewQueueCount}개, 승인 대기 ${summary.pendingApprovalCount}개가 보입니다.")
                best?.let { append(" 현재 성과 상위 에이전트는 ${it.agentName}(${it.roleName})입니다.") }
            }
        } else {
            buildString {
                append("${company.name} is ${summary.runtimeStatus}; active issues: $activeIssues. ")
                append("Blocked issues: ${summary.blockedIssueCount}, review items: ${summary.reviewQueueCount}, pending approvals: ${summary.pendingApprovalCount}.")
                best?.let { append(" Current top performer: ${it.agentName} (${it.roleName}).") }
            }
        }
        val sources = buildList {
            add(OperatorAnswerSource("company-summary", company.name, "runtime=${summary.runtimeStatus}, activeIssues=$activeIssues", company.id))
            best?.let {
                add(OperatorAnswerSource("agent-performance", "${it.agentName} · ${it.roleName}", "score=${it.score}", it.agentId))
            }
            activity.take(3).forEach { add(OperatorAnswerSource("activity", it.title, it.detail, it.id)) }
        }
        return GroundedOperatorAnswer(message = message, sources = sources)
    }

    private data class OperatorModeUpdate(
        val mode: OperatorAutomationMode,
        val actions: List<OperatorCommandAction> = emptyList(),
        val blockedActions: List<OperatorCommandAction> = emptyList()
    )

    private suspend fun applyOperatorAutomationMode(
        companyId: String,
        requestedMode: OperatorAutomationMode?,
        confirmFullAuto: Boolean
    ): OperatorModeUpdate = stateMutex.withLock {
        val state = stateStore.load()
        val company = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        if (requestedMode == null || requestedMode == company.operatorAutomationMode) {
            return@withLock OperatorModeUpdate(company.operatorAutomationMode)
        }
        if (requestedMode == OperatorAutomationMode.FULL_AUTO && !confirmFullAuto) {
            return@withLock OperatorModeUpdate(
                mode = company.operatorAutomationMode,
                blockedActions = listOf(
                    OperatorCommandAction(
                        type = "automation-mode",
                        title = "Full auto requires confirmation",
                        detail = "Full auto needs one explicit user confirmation before routine prompts are removed.",
                        status = "USER_CONFIRMATION_REQUIRED"
                    )
                )
            )
        }

        val now = System.currentTimeMillis()
        val updatedCompany = company.copy(operatorAutomationMode = requestedMode, updatedAt = now)
        val nextState = state.copy(
            companies = state.companies.map { if (it.id == companyId) updatedCompany else it }
        ).recordCompanyActivity(
            companyId = companyId,
            source = "operator",
            title = "Automation mode changed",
            detail = formatOperatorAutomationMode(requestedMode)
        ).withDerivedMetrics()
        stateStore.save(nextState)
        OperatorModeUpdate(
            mode = requestedMode,
            actions = listOf(
                OperatorCommandAction(
                    type = "automation-mode",
                    title = "Automation mode changed",
                    detail = "Company Operator now uses ${formatOperatorAutomationMode(requestedMode)}.",
                    status = "DONE"
                )
            )
        )
    }

    private suspend fun currentOperatorAutomationMode(companyId: String): OperatorAutomationMode =
        stateStore.load().companies.firstOrNull { it.id == companyId }?.operatorAutomationMode
            ?: throw IllegalArgumentException("Company not found: $companyId")

    private suspend fun createOperatorWorkIntakeGoal(companyId: String, message: String): CompanyGoal {
        val company = stateStore.load().companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val draft = buildCeoChatIntakeDraft(company, message)
        return createGoal(
            companyId = companyId,
            title = draft.title,
            description = draft.description,
            successMetrics = draft.successMetrics,
            autonomyEnabled = true,
            operatingPolicy = "Company Operator work intake: CEO planning must produce the execution graph before downstream work starts.",
            startRuntimeIfNeeded = false
        )
    }

    private suspend fun buildOperatorCompanySummary(companyId: String): OperatorCompanySummary {
        val state = stateStore.load().withDerivedMetrics()
        val company = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val runtime = runtimeStatus(companyId)
        val companyWorkspaceIds = state.workspaces
            .filter { it.repositoryId == company.repositoryId }
            .mapTo(linkedSetOf()) { it.id }
        val companyIssueIds = state.issues
            .filter { it.companyId == companyId }
            .mapTo(linkedSetOf()) { it.id }
        val companyTaskIds = state.tasks
            .filter { it.issueId in companyIssueIds || it.workspaceId in companyWorkspaceIds }
            .mapTo(linkedSetOf()) { it.id }
        val activeAgentCount = state.runs.count {
            it.taskId in companyTaskIds && (it.status == AgentRunStatus.RUNNING || it.status == AgentRunStatus.QUEUED)
        }
        val blockedIssueCount = state.issues.count { it.companyId == companyId && it.status == IssueStatus.BLOCKED }
        val attentionReviewCount = state.reviewQueue.count {
            it.companyId == companyId && it.status !in setOf(ReviewQueueStatus.MERGED)
        }
        val pendingApprovalCount = runtime.waitingApprovalCount +
            state.issues.count { it.companyId == companyId && it.status == IssueStatus.WAITING_FOR_APPROVAL } +
            state.reviewQueue.count {
                it.companyId == companyId &&
                    it.status in setOf(ReviewQueueStatus.READY_FOR_CEO, ReviewQueueStatus.READY_TO_MERGE)
            }
        return OperatorCompanySummary(
            runtimeStatus = runtime.status.name,
            backendHealth = runtime.backendHealth,
            activeAgentCount = activeAgentCount,
            blockedIssueCount = blockedIssueCount,
            reviewQueueCount = attentionReviewCount,
            pendingApprovalCount = pendingApprovalCount,
            budgetPaused = runtime.budgetPausedAt != null
        )
    }

    private fun formatOperatorAutomationMode(mode: OperatorAutomationMode): String = when (mode) {
        OperatorAutomationMode.ASK_ME -> "confirmation before execution"
        OperatorAutomationMode.AGENT_APPROVED -> "internal approval"
        OperatorAutomationMode.FULL_AUTO -> "full auto"
    }

    private fun formatOperatorStatusBrief(summary: OperatorCompanySummary): String {
        val parts = buildList {
            if (summary.activeAgentCount > 0) add("${summary.activeAgentCount} active agent run(s)")
            if (summary.blockedIssueCount > 0) add("${summary.blockedIssueCount} blocked issue(s)")
            if (summary.pendingApprovalCount > 0) add("${summary.pendingApprovalCount} item(s) waiting for approval")
            if (summary.reviewQueueCount > 0) add("${summary.reviewQueueCount} review item(s)")
            if (summary.budgetPaused) add("budget paused")
        }
        return if (parts.isEmpty()) {
            "No active runs, blocked issues, or waiting approvals need attention."
        } else {
            parts.joinToString(separator = ", ").replaceFirstChar { it.uppercase() } + "."
        }
    }

    private fun formatOperatorActionOutcome(action: OperatorCommandAction): String {
        val outcome = when (action.status) {
            "DONE" -> "done"
            "NOOP" -> "nothing to change"
            "READY" -> "ready"
            "ATTENTION" -> "needs attention"
            "BLOCKED" -> "blocked"
            "USER_CONFIRMATION_REQUIRED" -> "needs your confirmation"
            "AGENT_APPROVAL_REQUESTED" -> "sent for internal approval"
            else -> action.status.lowercase().replace('_', ' ')
        }
        return "${action.title} $outcome"
    }

    private fun formatOperatorResponseMessage(
        actions: List<OperatorCommandAction>,
        pendingApprovals: List<OperatorCommandAction>,
        blockedActions: List<OperatorCommandAction>,
        summary: OperatorCompanySummary
    ): String {
        val main = when {
            blockedActions.isNotEmpty() && actions.isEmpty() && pendingApprovals.isEmpty() -> blockedActions.first().detail
            pendingApprovals.isNotEmpty() -> "${pendingApprovals.size} action(s) were sent for internal approval."
            actions.isNotEmpty() -> actions.joinToString("; ") { formatOperatorActionOutcome(it) } + "."
            else -> "Company status checked."
        }
        return "$main ${formatOperatorStatusBrief(summary)}"
    }

    private data class OperatorModelUpdate(
        val requestedModel: String,
        val appliedModel: String
    )

    private suspend fun updateOperatorAgentModels(
        companyId: String,
        includeAllCompanies: Boolean,
        requestedModel: String,
        appliedModel: String
    ): OperatorCommandAction = stateMutex.withLock {
        val state = stateStore.load()
        val selectedCompany = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val targetCompanies = if (includeAllCompanies) state.companies else listOf(selectedCompany)
        val targetCompanyIds = targetCompanies.mapTo(linkedSetOf()) { it.id }
        val targetDefinitions = state.companyAgentDefinitions.filter { it.companyId in targetCompanyIds }
        if (targetDefinitions.isEmpty()) {
            return@withLock OperatorCommandAction(
                type = "agent-model-update",
                title = "No agents to update",
                detail = "No company agents are registered for the selected scope.",
                status = "NOOP"
            )
        }

        val now = System.currentTimeMillis()
        val updatedDefinitionIds = targetDefinitions.mapTo(linkedSetOf()) { it.id }
        val nextDefinitions = state.companyAgentDefinitions.map { definition ->
            if (definition.id in updatedDefinitionIds && definition.companyId in targetCompanyIds) {
                definition.copy(
                    agentCli = "opencode",
                    model = appliedModel,
                    updatedAt = now
                )
            } else {
                definition
            }
        }
        val nextState = targetCompanies.fold(
            state.copy(
                companyAgentDefinitions = nextDefinitions,
                orgProfiles = deriveProfiles(nextDefinitions, state.companies)
            )
        ) { current, company ->
            current.recordCompanyActivity(
                companyId = company.id,
                source = "operator",
                title = "Updated agent models",
                detail = "requested=$requestedModel, applied=opencode · $appliedModel"
            )
        }.withDerivedMetrics()
        stateStore.save(nextState)
        targetCompanies.forEach { company ->
            nextState.projectContexts.firstOrNull { it.companyId == company.id }?.let { context ->
                writeCompanyContextSnapshot(nextState, company, context)
            }
        }

        OperatorCommandAction(
            type = "agent-model-update",
            title = "Agent models updated",
            detail = "${targetDefinitions.size} agent(s) were moved to opencode with $appliedModel across ${targetCompanies.size} company scope(s). Requested model: $requestedModel. Applied model: $appliedModel.",
            status = "DONE"
        )
    }

    private data class HrStaffingNeed(
        val title: String,
        val roleSummary: String,
        val specialties: List<String>,
        val reason: String,
        val mentorTitleHints: List<String>,
        val collaboratorTitleHints: List<String> = emptyList()
    )

    private data class HrMentorAssignment(
        val agentTitle: String,
        val mentorTitle: String
    )

    private data class HrStaffingOutcome(
        val hiredAgents: List<CompanyAgentDefinition>,
        val mentorAssignments: List<HrMentorAssignment>,
        val capped: Boolean,
        val noOpReason: String?
    )

    private data class CompanyAgentExecutionModel(
        val agentCli: String,
        val model: String?
    )

    private suspend fun runHrStaffingReviewAsOperator(
        companyId: String,
        requestText: String?,
        maxHires: Int
    ): OperatorCommandAction {
        val outcome = runHrStaffingReview(companyId, requestText, maxHires)
        val detail = formatHrStaffingOutcome(outcome)
        return OperatorCommandAction(
            type = "hr-staffing",
            title = when {
                outcome.hiredAgents.isNotEmpty() -> "HR Manager staffed the team"
                outcome.mentorAssignments.isNotEmpty() -> "HR Manager assigned mentors"
                else -> "HR Manager checked the team"
            },
            detail = detail,
            status = if (outcome.hiredAgents.isEmpty() && outcome.mentorAssignments.isEmpty()) "NOOP" else "DONE"
        )
    }

    private suspend fun runHrStaffingReview(
        companyId: String,
        requestText: String?,
        maxHires: Int
    ): HrStaffingOutcome = stateMutex.withLock {
        val state = stateStore.load()
        val company = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val now = System.currentTimeMillis()
        val companyDefinitions = state.companyAgentDefinitions
            .filter { it.companyId == companyId }
            .sortedWith(compareBy<CompanyAgentDefinition> { it.displayOrder }.thenBy { it.title.lowercase() })
        val activeDefinitions = companyDefinitions.filter { it.enabled }
        val activeDefinitionCount = activeDefinitions.size
        val inheritedExecutionModel = dominantCompanyExecutionModel(activeDefinitions)
        val profiles = ensureOrgProfiles(state.orgProfiles, state.companyAgentDefinitions, state.companies)
            .filter { it.companyId == companyId && it.enabled }
        val occupiedProfileIds = occupiedCompanyProfileIds(state, companyId)

        val mentorAssignments = mutableListOf<Pair<String, String>>()
        var nextCompanyDefinitions = companyDefinitions.map { definition ->
            if (!definition.enabled || definition.mentorAgentId != null || definition.title.equals("CEO", ignoreCase = true)) {
                definition
            } else {
                val mentor = chooseMentorForAgent(definition, companyDefinitions)
                if (mentor == null) {
                    definition
                } else {
                    mentorAssignments += definition.id to mentor.id
                    definition.copy(mentorAgentId = mentor.id, updatedAt = now)
                }
            }
        }

        val requestMentorOnly = requestText
            ?.lowercase()
            ?.let { text ->
                containsAny(text, "mentor", "사수") &&
                    !containsAny(text, "hire", "hiring", "staff", "팀 보강", "고용", "채용", "필요한 사람", "사람 붙")
            }
            ?: false
        val staffingNeeds = if (requestMentorOnly) {
            emptyList()
        } else {
            inferHrStaffingNeeds(state, companyId, requestText)
        }
        val hiredDefinitions = mutableListOf<CompanyAgentDefinition>()
        var capped = false

        staffingNeeds.forEach { need ->
            if (hiredDefinitions.size >= maxHires) {
                capped = true
                return@forEach
            }
            if (activeDefinitionCount + hiredDefinitions.size >= HR_MAX_ACTIVE_AGENTS_PER_COMPANY) {
                capped = true
                return@forEach
            }
            if (companyHasCoverageForNeed(need, nextCompanyDefinitions + hiredDefinitions, profiles, occupiedProfileIds)) {
                return@forEach
            }
            val mentor = chooseMentorForNeed(need, nextCompanyDefinitions + hiredDefinitions)
            val preferredCollaboratorIds = (
                listOfNotNull(mentor?.id) +
                    need.collaboratorTitleHints.mapNotNull { titleHint ->
                        (nextCompanyDefinitions + hiredDefinitions).firstOrNull {
                            it.enabled && it.title.equals(titleHint, ignoreCase = true)
                        }?.id
                    }
                ).distinct()
            val definition = CompanyAgentDefinition(
                id = UUID.randomUUID().toString(),
                companyId = companyId,
                title = uniqueHrHireTitle(need.title, nextCompanyDefinitions + hiredDefinitions),
                agentCli = inheritedExecutionModel.agentCli,
                model = inheritedExecutionModel.model,
                roleSummary = need.roleSummary,
                specialties = need.specialties,
                collaborationInstructions = "Work with ${mentor?.title ?: "the company lead"} as mentor and keep HR Manager informed about onboarding blockers.",
                preferredCollaboratorIds = preferredCollaboratorIds,
                mentorAgentId = mentor?.id,
                memoryNotes = "Hired by HR Manager. Reason: ${need.reason}",
                enabled = true,
                displayOrder = companyDefinitions.size + hiredDefinitions.size,
                createdAt = now,
                updatedAt = now
            )
            hiredDefinitions += definition
        }

        if (hiredDefinitions.isEmpty() && mentorAssignments.isEmpty()) {
            return@withLock HrStaffingOutcome(
                hiredAgents = emptyList(),
                mentorAssignments = emptyList(),
                capped = capped,
                noOpReason = if (capped) {
                    "The team is at its staffing limit."
                } else {
                    "The current team already covers this request."
                }
            )
        }

        nextCompanyDefinitions = nextCompanyDefinitions + hiredDefinitions
        val nextDefinitions = state.companyAgentDefinitions
            .filterNot { it.companyId == companyId }
            .plus(nextCompanyDefinitions)
        val mentorAssignmentsById = mentorAssignments.toMap()
        val assignmentSummaries = mentorAssignments.mapNotNull { (agentId, mentorId) ->
            val agent = nextCompanyDefinitions.firstOrNull { it.id == agentId } ?: return@mapNotNull null
            val mentor = nextCompanyDefinitions.firstOrNull { it.id == mentorId } ?: return@mapNotNull null
            HrMentorAssignment(agent.title, mentor.title)
        } + hiredDefinitions.mapNotNull { hired ->
            val mentorId = hired.mentorAgentId ?: return@mapNotNull null
            val mentor = nextCompanyDefinitions.firstOrNull { it.id == mentorId } ?: return@mapNotNull null
            HrMentorAssignment(hired.title, mentor.title)
        }.filterNot { hiredAssignment ->
            mentorAssignmentsById.any { (agentId, mentorId) ->
                val agent = nextCompanyDefinitions.firstOrNull { it.id == agentId }
                val mentor = nextCompanyDefinitions.firstOrNull { it.id == mentorId }
                agent?.title == hiredAssignment.agentTitle && mentor?.title == hiredAssignment.mentorTitle
            }
        }
        val messages = buildList {
            hiredDefinitions.forEach { hired ->
                val mentorTitle = hired.mentorAgentId
                    ?.let { mentorId -> nextCompanyDefinitions.firstOrNull { it.id == mentorId }?.title }
                    ?: "company lead"
                add(
                    AgentMessage(
                        id = UUID.randomUUID().toString(),
                        companyId = companyId,
                        fromAgentName = "HR Manager",
                        toAgentName = hired.title,
                        kind = "hr-onboarding",
                        subject = "New agent onboarded",
                        body = "You were hired for ${hired.roleSummary}. Your mentor is $mentorTitle.",
                        createdAt = now
                    )
                )
            }
            assignmentSummaries.filter { assignment ->
                hiredDefinitions.none { it.title == assignment.agentTitle }
            }.forEach { assignment ->
                add(
                    AgentMessage(
                        id = UUID.randomUUID().toString(),
                        companyId = companyId,
                        fromAgentName = "HR Manager",
                        toAgentName = assignment.agentTitle,
                        kind = "hr-mentor-assignment",
                        subject = "Mentor assigned",
                        body = "${assignment.mentorTitle} is your mentor for onboarding and escalation.",
                        createdAt = now
                    )
                )
            }
        }

        val nextState = state.copy(
            companyAgentDefinitions = nextDefinitions,
            agentCapabilityProfiles = state.agentCapabilityProfiles + hiredDefinitions.map {
                seedCompanyAgentCapabilityProfile(company, it, now)
            },
            orgProfiles = deriveProfiles(nextDefinitions, state.companies),
            agentMessages = state.agentMessages + messages
        ).recordCompanyActivity(
            companyId = companyId,
            source = "hr-manager",
            title = "HR Manager reviewed staffing",
            detail = formatHrStaffingActivityDetail(hiredDefinitions, assignmentSummaries),
            severity = if (capped) "warning" else "info"
        ).withDerivedMetrics()
        stateStore.save(nextState)
        nextState.projectContexts.firstOrNull { it.companyId == companyId }?.let { context ->
            writeCompanyContextSnapshot(nextState, company, context)
        }
        HrStaffingOutcome(
            hiredAgents = hiredDefinitions,
            mentorAssignments = assignmentSummaries,
            capped = capped,
            noOpReason = null
        )
    }

    private fun formatHrStaffingOutcome(outcome: HrStaffingOutcome): String {
        val parts = buildList {
            if (outcome.hiredAgents.isNotEmpty()) {
                add(
                    outcome.hiredAgents.joinToString { hired ->
                        val mentorText = outcome.mentorAssignments.firstOrNull { it.agentTitle == hired.title }
                            ?.mentorTitle
                            ?.let { " with $it as mentor" }
                            .orEmpty()
                        "${hired.title}$mentorText"
                    } + " added."
                )
            }
            val existingMentors = outcome.mentorAssignments.filterNot { assignment ->
                outcome.hiredAgents.any { it.title == assignment.agentTitle }
            }
            if (existingMentors.isNotEmpty()) {
                add(
                    existingMentors.joinToString { "${it.agentTitle} -> ${it.mentorTitle}" } +
                        " mentor assignment(s) updated."
                )
            }
            if (outcome.capped) {
                add("Additional hiring was held at the company staffing limit.")
            }
            outcome.noOpReason?.let { add(it) }
        }
        return parts.joinToString(" ")
    }

    private fun formatHrStaffingActivityDetail(
        hiredDefinitions: List<CompanyAgentDefinition>,
        mentorAssignments: List<HrMentorAssignment>
    ): String =
        when {
            hiredDefinitions.isNotEmpty() -> "Hired ${hiredDefinitions.joinToString { it.title }}."
            mentorAssignments.isNotEmpty() -> "Assigned mentors for ${mentorAssignments.joinToString { it.agentTitle }}."
            else -> "No staffing change needed."
        }

    private fun dominantCompanyExecutionModel(definitions: List<CompanyAgentDefinition>): CompanyAgentExecutionModel {
        val activeModels = definitions
            .filter { it.enabled }
            .map { definition ->
                CompanyAgentExecutionModel(
                    agentCli = definition.agentCli.trim().ifBlank { "opencode" },
                    model = OpenCodeDefaults.normalizeModel(definition.model)
                )
            }
        if (activeModels.isEmpty()) {
            return CompanyAgentExecutionModel("opencode", OpenCodeDefaults.DEFAULT_MODEL)
        }
        return activeModels
            .groupingBy { it }
            .eachCount()
            .maxWithOrNull(
                compareBy<Map.Entry<CompanyAgentExecutionModel, Int>> { it.value }
                    .thenBy { if (it.key.agentCli.equals("opencode", ignoreCase = true)) 1 else 0 }
                    .thenBy { if (it.key.model == OpenCodeDefaults.DEFAULT_MODEL) 1 else 0 }
            )
            ?.key
            ?: CompanyAgentExecutionModel("opencode", OpenCodeDefaults.DEFAULT_MODEL)
    }

    private fun occupiedCompanyProfileIds(state: DesktopAppState, companyId: String): Set<String> {
        val issueCompanyById = state.issues.associate { it.id to it.companyId }
        return state.tasks
            .filter { it.status == DesktopTaskStatus.RUNNING || it.status == DesktopTaskStatus.QUEUED }
            .mapNotNull { task ->
                val issueCompanyId = task.issueId?.let(issueCompanyById::get) ?: return@mapNotNull null
                if (issueCompanyId == companyId) {
                    state.issues.firstOrNull { it.id == task.issueId }?.assigneeProfileId
                } else {
                    null
                }
            }
            .toSet()
    }

    private fun inferHrStaffingNeeds(
        state: DesktopAppState,
        companyId: String,
        requestText: String?
    ): List<HrStaffingNeed> {
        val request = requestText.orEmpty()
        val issueTexts = state.issues
            .filter {
                it.companyId == companyId &&
                    it.status in setOf(IssueStatus.PLANNED, IssueStatus.BACKLOG, IssueStatus.DELEGATED, IssueStatus.BLOCKED)
            }
            .sortedWith(compareBy<CompanyIssue> { it.priority }.thenByDescending { it.updatedAt })
            .take(6)
            .joinToString("\n") { "${it.kind} ${it.title} ${it.description} ${it.acceptanceCriteria.joinToString(" ")}" }
        val text = "$request\n$issueTexts".lowercase()
        val explicitStaffing = containsAny(text, "hire", "hiring", "staff", "팀 보강", "고용", "채용", "필요한 사람", "사람 붙")
        val needs = mutableListOf<HrStaffingNeed>()
        fun addNeed(need: HrStaffingNeed) {
            if (needs.none { it.title.equals(need.title, ignoreCase = true) }) {
                needs += need
            }
        }
        if (containsAny(text, "frontend", "front-end", "ui", "swift", "macos", "desktop", "화면", "프론트", "사용자 경험")) {
            addNeed(
                HrStaffingNeed(
                    title = "Frontend Specialist",
                    roleSummary = "own frontend, SwiftUI, desktop UI, and interaction polish work",
                    specialties = listOf("frontend", "swiftui", "macos", "ui"),
                    reason = "Frontend or desktop UI work needs dedicated capacity.",
                    mentorTitleHints = listOf("Engineering Lead", "UI Builder", "UX Builder"),
                    collaboratorTitleHints = listOf("UI Builder", "UX Builder", "QA")
                )
            )
        }
        if (containsAny(text, "backend", "api", "kotlin", "server", "orchestration", "백엔드")) {
            addNeed(
                HrStaffingNeed(
                    title = "Backend Specialist",
                    roleSummary = "own backend APIs, Kotlin orchestration, and runtime integration",
                    specialties = listOf("backend", "api", "kotlin", "orchestration"),
                    reason = "Backend or orchestration work needs dedicated capacity.",
                    mentorTitleHints = listOf("Engineering Lead", "Backend Builder", "CEO"),
                    collaboratorTitleHints = listOf("Backend Builder", "QA", "Release Manager")
                )
            )
        }
        if (containsAny(text, "qa", "test", "testing", "검증", "테스트", "리뷰")) {
            addNeed(
                HrStaffingNeed(
                    title = "QA Specialist",
                    roleSummary = "own regression testing, verification evidence, and review feedback",
                    specialties = listOf("qa", "testing", "verification", "review"),
                    reason = "Verification workload needs dedicated capacity.",
                    mentorTitleHints = listOf("QA", "Engineering Lead", "Release Manager"),
                    collaboratorTitleHints = listOf("QA", "Release Manager")
                )
            )
        }
        if (containsAny(text, "marketing", "content", "social", "마케팅", "콘텐츠")) {
            addNeed(
                HrStaffingNeed(
                    title = "Marketing Specialist",
                    roleSummary = "support delegated content, owned-channel, and social workflow execution",
                    specialties = listOf("marketing", "content", "social"),
                    reason = "Marketing work needs dedicated capacity.",
                    mentorTitleHints = listOf("Marketing Operator", "Product Strategist", "CEO"),
                    collaboratorTitleHints = listOf("Marketing Operator", "Product Strategist")
                )
            )
        }
        if (explicitStaffing && needs.isEmpty()) {
            addNeed(
                HrStaffingNeed(
                    title = "Generalist Builder",
                    roleSummary = "take implementation overflow and unblock broad product work",
                    specialties = listOf("implementation", "delivery", "integration"),
                    reason = "The team asked HR Manager to add general execution capacity.",
                    mentorTitleHints = listOf("Engineering Lead", "Builder", "CEO"),
                    collaboratorTitleHints = listOf("Builder", "QA")
                )
            )
        }
        return needs
    }

    private fun companyHasCoverageForNeed(
        need: HrStaffingNeed,
        definitions: List<CompanyAgentDefinition>,
        profiles: List<OrgAgentProfile>,
        occupiedProfileIds: Set<String>
    ): Boolean {
        val activeDefinitions = definitions.filter { it.enabled }
        if (activeDefinitions.any { it.title.equals(need.title, ignoreCase = true) }) {
            return true
        }
        val matchingDefinitionIds = activeDefinitions
            .filter { definition -> definitionMatchesNeed(definition, need) }
            .mapTo(linkedSetOf()) { it.id }
        if (matchingDefinitionIds.isEmpty()) {
            return false
        }
        val matchingProfiles = profiles.filter { it.id in matchingDefinitionIds }
        return matchingProfiles.any { it.id !in occupiedProfileIds }
    }

    private fun definitionMatchesNeed(definition: CompanyAgentDefinition, need: HrStaffingNeed): Boolean {
        val descriptor = listOf(
            definition.title,
            definition.roleSummary,
            definition.specialties.joinToString(" ")
        ).joinToString(" ").lowercase()
        return need.specialties.any { specialty -> descriptor.contains(specialty.lowercase()) }
    }

    private fun chooseMentorForNeed(
        need: HrStaffingNeed,
        definitions: List<CompanyAgentDefinition>
    ): CompanyAgentDefinition? =
        need.mentorTitleHints.firstNotNullOfOrNull { hint ->
            definitions.firstOrNull { it.enabled && it.title.equals(hint, ignoreCase = true) }
        } ?: definitions.firstOrNull { it.enabled && it.title.equals("CEO", ignoreCase = true) }
            ?: definitions.firstOrNull { it.enabled }

    private fun chooseMentorForAgent(
        definition: CompanyAgentDefinition,
        definitions: List<CompanyAgentDefinition>
    ): CompanyAgentDefinition? {
        val title = definition.title.lowercase()
        val hints = when {
            title == "ceo" -> emptyList()
            "hr" in title || "engineering lead" in title || "product" in title || "marketing" in title ->
                listOf("CEO")
            "release" in title -> listOf("QA", "Engineering Lead", "CEO")
            "ui" in title -> listOf("UX Builder", "Engineering Lead", "CEO")
            "ux" in title -> listOf("Product Strategist", "CEO")
            "qa" in title || "backend" in title || "builder" in title || "frontend" in title ->
                listOf("Engineering Lead", "Builder", "CEO")
            else -> listOf("Engineering Lead", "CEO", "HR Manager")
        }
        return hints.firstNotNullOfOrNull { hint ->
            definitions.firstOrNull {
                it.enabled &&
                    it.id != definition.id &&
                    it.title.equals(hint, ignoreCase = true)
            }
        } ?: definitions.firstOrNull {
            it.enabled &&
                it.id != definition.id &&
                it.title.equals("CEO", ignoreCase = true)
        } ?: definitions.firstOrNull { it.enabled && it.id != definition.id }
    }

    private fun uniqueHrHireTitle(
        requestedTitle: String,
        definitions: List<CompanyAgentDefinition>
    ): String {
        val existing = definitions.mapTo(mutableSetOf()) { it.title.lowercase() }
        if (requestedTitle.lowercase() !in existing) return requestedTitle
        var suffix = 2
        while ("$requestedTitle $suffix".lowercase() in existing) {
            suffix += 1
        }
        return "$requestedTitle $suffix"
    }

    private suspend fun reopenBlockedIssuesFromOperator(companyId: String): OperatorCommandAction = stateMutex.withLock {
        val state = stateStore.load()
        val company = state.companies.firstOrNull { it.id == companyId }
            ?: throw IllegalArgumentException("Company not found: $companyId")
        val blockedIssues = state.issues.filter { it.companyId == companyId && it.status == IssueStatus.BLOCKED }
        if (blockedIssues.isEmpty()) {
            return@withLock OperatorCommandAction(
                type = "blocked-issue-retry",
                title = "No blocked issues",
                detail = "There are no blocked issues to retry for ${company.name}.",
                status = "NOOP"
            )
        }

        val now = System.currentTimeMillis()
        val blockedIds = blockedIssues.mapTo(linkedSetOf()) { it.id }
        val nextIssues = state.issues.map { issue ->
            if (issue.id in blockedIds) {
                issue.copy(
                    status = IssueStatus.PLANNED,
                    transitionReason = "Company Operator reopened this blocked issue for autonomous retry.",
                    blockedBy = emptyList(),
                    runtimeDisposition = null,
                    updatedAt = now
                )
            } else {
                issue
            }
        }
        val nextState = state.copy(issues = nextIssues).recordCompanyActivity(
            companyId = companyId,
            source = "operator",
            title = "Reopened blocked issues",
            detail = "${blockedIssues.size} issue(s) moved back to planned."
        ).withDerivedMetrics()
        stateStore.save(nextState)
        OperatorCommandAction(
            type = "blocked-issue-retry",
            title = "Blocked issues reopened",
            detail = "${blockedIssues.size} blocked issue(s) were moved back to planned for retry.",
            status = "DONE"
        )
    }

    private suspend fun routeOperatorApprovalToAgent(
        companyId: String,
