        appendLine("Responsibilities:")
        appendLine("- Review the current PR and the latest QA verdict.")
        appendLine("- Emit CEO_VERDICT: APPROVE or CEO_VERDICT: CHANGES_REQUESTED with concise feedback.")
        appendLine("- Only approve if the PR is ready to merge into the base branch.")
    }.trim()

    private suspend fun synthesizeAutonomousFollowUpGoal(companyId: String): CompanyGoal? {
        val state = stateStore.load()
        val company = state.companies.firstOrNull { it.id == companyId } ?: return null
        val openGoals = state.goals.filter {
            it.companyId == companyId && it.status != GoalStatus.COMPLETED
        }
        val activeTaskIssueIds = state.tasks
            .filter { it.status == DesktopTaskStatus.RUNNING || it.status == DesktopTaskStatus.QUEUED }
            .mapNotNull { it.issueId }
            .toSet()
        val latestRunsByTaskId = state.runs
            .groupBy { it.taskId }
            .mapValues { (_, runs) -> runs.maxByOrNull { it.updatedAt }!! }
        val issuesById = state.issues
            .filter { it.companyId == companyId }
            .associateBy { it.id }
        val goalsById = state.goals.associateBy { it.id }
        val reviewQueueById = state.reviewQueue.associateBy { it.id }

        data class FollowUpCandidate(
            val issue: CompanyIssue,
            val reviewQueueItem: ReviewQueueItem? = null,
            val failureClass: FollowUpFailureClass,
            val rootGoalId: String,
            val followUpContext: FollowUpContextSnapshot,
            val reason: String,
            val marker: String,
            val subject: String
        )

        fun hasOpenFollowUp(marker: String): Boolean =
            openGoals.any { it.operatingPolicy == marker }

        fun hasOpenFollowUpForContext(context: FollowUpContextSnapshot): Boolean =
            openGoals.any { openGoal ->
                val existing = openGoal.followUpContext ?: return@any false
                existing.rootGoalId == context.rootGoalId &&
                    existing.failureClass == context.failureClass &&
                    (
                        existing.reviewQueueItemId != null && existing.reviewQueueItemId == context.reviewQueueItemId ||
                            (
                                existing.reviewQueueItemId == null &&
                                    context.reviewQueueItemId == null &&
                                    existing.triggerIssueId == context.triggerIssueId
                                )
                        )
            }

        val openFollowUpSubjects = openGoals
            .filter { it.operatingPolicy.orEmpty().startsWith("auto-follow-up:") }
            .map { canonicalFollowUpSubject(it.title) }
            .toSet()

        val failedReviewCandidate = state.reviewQueue
            .filter { it.companyId == companyId }
            .sortedByDescending { it.updatedAt }
            .mapNotNull { item ->
                if (item.status != ReviewQueueStatus.FAILED_CHECKS && item.status != ReviewQueueStatus.CHANGES_REQUESTED) {
                    return@mapNotNull null
                }
                val issue = issuesById[item.issueId] ?: return@mapNotNull null
                val parentGoal = state.goals.firstOrNull { it.id == issue.goalId }
                if (parentGoal?.operatingPolicy?.startsWith("auto-follow-up:") == true) {
                    return@mapNotNull null
                }
                val rootGoalId = resolveFollowUpRootGoalId(issue.goalId, issuesById, goalsById, reviewQueueById)
                    ?: issue.goalId
                val marker = "auto-follow-up:goal:$rootGoalId"
                val failureClass = when {
                    item.status == ReviewQueueStatus.CHANGES_REQUESTED && item.mergeability.equals("DIRTY", ignoreCase = true) ->
                        FollowUpFailureClass.MERGE_CONFLICT
                    item.status == ReviewQueueStatus.FAILED_CHECKS -> FollowUpFailureClass.REVIEW_FAILED_CHECKS
                    else -> FollowUpFailureClass.REVIEW_CHANGES_REQUESTED
                }
                val followUpContext = FollowUpContextSnapshot(
                    rootGoalId = rootGoalId,
                    triggerIssueId = issue.id,
                    reviewQueueItemId = item.id,
                    pullRequestNumber = item.pullRequestNumber ?: issue.pullRequestNumber,
                    failureClass = failureClass
                )
                if (hasOpenFollowUpForContext(followUpContext)) return@mapNotNull null
                if (hasOpenFollowUp(marker)) return@mapNotNull null
                val subject = canonicalFollowUpSubject(issue.title)
                if (subject in openFollowUpSubjects) return@mapNotNull null
                val reason = when (item.status) {
                    ReviewQueueStatus.FAILED_CHECKS -> "Review queue checks failed and require a remediation loop."
                    ReviewQueueStatus.CHANGES_REQUESTED -> when (failureClass) {
                        FollowUpFailureClass.MERGE_CONFLICT ->
                            "The current PR no longer merges cleanly with the latest base branch and needs deterministic remediation on the existing PR lineage."
                        else -> "Review requested changes and requires a remediation loop."
                    }
                    else -> return@mapNotNull null
                }
                FollowUpCandidate(
                    issue = issue,
                    reviewQueueItem = item,
                    failureClass = failureClass,
                    rootGoalId = rootGoalId,
                    followUpContext = followUpContext,
                    reason = reason,
                    marker = marker,
                    subject = subject
                )
            }
            .firstOrNull()

        val blockedIssueCandidate = state.issues
            .filter {
                it.companyId == companyId &&
                    it.status == IssueStatus.BLOCKED &&
                    !it.kind.equals("planning", ignoreCase = true)
            }
            .sortedByDescending { it.updatedAt }
            .mapNotNull { issue ->
                if (issue.id in activeTaskIssueIds) return@mapNotNull null
                val retryDecision = resolveRecoverableRetryDecision(
                    issueTasks = state.tasks.filter { it.issueId == issue.id },
                    latestRunsByTaskId = latestRunsByTaskId,
                    now = System.currentTimeMillis()
                )
                if (retryDecision.mode == RecoverableRetryMode.READY || retryDecision.mode == RecoverableRetryMode.WAITING) {
                    return@mapNotNull null
                }
                val parentGoal = state.goals.firstOrNull { it.id == issue.goalId }
                if (parentGoal?.operatingPolicy?.startsWith("auto-follow-up:") == true) {
                    return@mapNotNull null
                }
                val rootGoalId = resolveFollowUpRootGoalId(issue.goalId, issuesById, goalsById, reviewQueueById)
                    ?: issue.goalId
                val marker = "auto-follow-up:goal:$rootGoalId"
                val followUpContext = FollowUpContextSnapshot(
                    rootGoalId = rootGoalId,
                    triggerIssueId = issue.id,
                    failureClass = FollowUpFailureClass.BLOCKED_EXECUTION
                )
                if (hasOpenFollowUpForContext(followUpContext)) return@mapNotNull null
                if (hasOpenFollowUp(marker)) return@mapNotNull null
                val subject = canonicalFollowUpSubject(issue.title)
                if (subject in openFollowUpSubjects) return@mapNotNull null
                FollowUpCandidate(
                    issue = issue,
                    failureClass = FollowUpFailureClass.BLOCKED_EXECUTION,
                    rootGoalId = rootGoalId,
                    followUpContext = followUpContext,
                    reason = "Execution is blocked and needs a new CEO-managed remediation goal.",
                    marker = marker,
                    subject = subject
                )
            }
            .firstOrNull()

        val candidate = failedReviewCandidate ?: blockedIssueCandidate
        if (candidate != null) {
            val parentGoal = state.goals.firstOrNull { it.id == candidate.issue.goalId }
            val title = "Resolve follow-up for \"${candidate.subject}\""
            val description = buildString {
                appendLine("CEO generated this goal automatically because follow-up work is required.")
                appendLine()
                appendLine("Company: ${company.name}")
                parentGoal?.let {
                    appendLine("Parent goal: ${it.title}")
                }
                appendLine("Trigger issue: ${candidate.issue.title}")
                candidate.reviewQueueItem?.pullRequestUrl?.let { appendLine("Pull request: $it") }
                appendLine("Reason: ${candidate.reason}")
                appendLine()
                appendLine("Required outcome:")
                when (candidate.failureClass) {
                    FollowUpFailureClass.MERGE_CONFLICT -> {
                        appendLine("- Reuse the current PR branch and worktree to resolve the merge conflict.")
                        appendLine("- Re-run validation and capture residual risk on the existing PR lineage.")
                        appendLine("- Reopen the existing CEO approval lane instead of creating a handoff PR.")
                    }
                    else -> {
                        appendLine("- Unblock the affected work or satisfy the failed review signal.")
                        appendLine("- Re-run validation and capture any residual risk.")
                        appendLine("- Summarize what the CEO should decide next once the remediation is complete.")
                        appendLine("- Create the next wave so the company can keep moving with multiple branchable issues when more work remains.")
                    }
                }
            }
            return createGoal(
                companyId = companyId,
                title = title,
                description = description,
                successMetrics = listOf(
                    "The triggering issue is no longer blocked or failed in review.",
                    "Validation is re-run and residual risks are documented.",
                    "The CEO receives a concrete next-wave recommendation instead of a dead-end remediation note."
                ),
                autonomyEnabled = false,
                priority = 1,
                operatingPolicy = candidate.marker,
                followUpContext = candidate.followUpContext,
                startRuntimeIfNeeded = false
            )
        }

        val hasActiveTasks = state.tasks.any { task ->
            (task.status == DesktopTaskStatus.RUNNING || task.status == DesktopTaskStatus.QUEUED) &&
                task.issueId?.let(issuesById::containsKey) == true
        }
        val unresolvedIssues = state.issues.filter {
            it.companyId == companyId && it.status != IssueStatus.DONE && it.status != IssueStatus.CANCELED
        }
        val hasActiveAutonomousGoals = openGoals.any { it.autonomyEnabled && it.status == GoalStatus.ACTIVE }
        if (hasActiveTasks || unresolvedIssues.isNotEmpty() || hasActiveAutonomousGoals) {
            return null
        }
        if (company.operatorAutomationMode != OperatorAutomationMode.FULL_AUTO) {
            return null
        }

        val lastContinuousCycle = state.goals
            .filter { it.companyId == companyId }
            .mapNotNull { goal ->
                goal.operatingPolicy
                    ?.takeIf { it.startsWith("auto-loop:continuous:") }
                    ?.removePrefix("auto-loop:continuous:")
                    ?.toIntOrNull()
            }
            .maxOrNull() ?: 0
        val nextCycle = lastContinuousCycle + 1
        val recentCompletedGoals = state.goals
            .filter {
                it.companyId == companyId &&
                    it.status == GoalStatus.COMPLETED &&
                    !it.operatingPolicy.orEmpty().startsWith("auto-follow-up:") &&
                    !isGeneratedFollowUpTitle(it.title)
            }
            .sortedByDescending { it.updatedAt }
            .take(3)
        val recentCompletedIssues = state.issues
            .filter {
                it.companyId == companyId &&
                    it.status == IssueStatus.DONE &&
                    !isGeneratedFollowUpTitle(it.title)
            }
            .sortedByDescending { it.updatedAt }
            .take(5)
        val title = "CEO continuous improvement cycle #$nextCycle for ${company.name}"
        val description = buildString {
            appendLine("CEO generated this goal automatically to keep the company operating without a manual pause.")
            appendLine()
            appendLine("Company: ${company.name}")
            appendLine("Cycle: #$nextCycle")
            if (recentCompletedGoals.isNotEmpty()) {
                appendLine()
                appendLine("Recently completed goals:")
                recentCompletedGoals.forEach { goal ->
                    appendLine("- ${goal.title}")
                }
            }
            if (recentCompletedIssues.isNotEmpty()) {
                appendLine()
                appendLine("Recently completed issues:")
                recentCompletedIssues.forEach { issue ->
                    appendLine("- ${issue.title}")
                }
            }
            appendLine()
            appendLine("CEO directive:")
            appendLine("- Review the current company state, recent wins, and unresolved product gaps.")
            appendLine("- Create a portfolio of 3 to 5 branchable issues for the next cycle instead of one narrow slice.")
            appendLine("- Use the current roster to run multiple compatible implementation and validation tracks in parallel when possible.")
            appendLine("- End this cycle with reviewed work and an explicit CEO decision about the next wave.")
        }
        return createGoal(
            companyId = companyId,
            title = title,
            description = description,
            successMetrics = listOf(
                "The CEO identifies the next improvement cycle and delegates it across the current roster.",
                "At least two branchable issues are opened when the roster can support concurrent work.",
                "Reviewed execution slices complete and residual risk is recorded before the next CEO decision."
            ),
            autonomyEnabled = true,
            priority = 2,
            operatingPolicy = "auto-loop:continuous:$nextCycle",
            startRuntimeIfNeeded = false
        )
    }

    private suspend fun synthesizeDiscoveryTriageGoal(
        companyId: String,
        state: DesktopAppState,
        company: Company
    ): CompanyGoal? {
        val scan = autonomousDiscoveryService.scan(state, companyId)
        if (scan.signals != state.problemSignals) {
            stateMutex.withLock {
                val latest = stateStore.load()
                val latestScan = autonomousDiscoveryService.scan(latest, companyId)
                stateStore.save(
                    latest.copy(problemSignals = latestScan.signals)
                        .recordSignal(
                            source = "autonomous-discovery",
                            message = if (latestScan.changedCount > 0) {
                                "Autonomous discovery recorded ${latestScan.changedCount} problem signal(s)."
                            } else {
                                "Autonomous discovery found no new internal quality problems."
                            },
                            severity = if (latestScan.changedCount > 0) "warning" else "info",
                            companyId = companyId
                        )
                        .withDerivedMetrics()
                )
            }
        }
        val latestState = stateStore.load()
        val latestScan = autonomousDiscoveryService.scan(latestState, companyId)
        val signal = latestScan.actionableSignal ?: return null
        val title = "CEO triage for ${signal.title}"
        val description = buildString {
            appendLine("CEO generated this goal from an internal quality discovery signal.")
            appendLine()
            appendLine("Company: ${company.name}")
            appendLine("Signal: ${signal.title}")
            appendLine("Kind: ${signal.kind}")
            appendLine("Severity: ${signal.severity}")
            appendLine("Confidence: ${"%.2f".format(signal.confidence)}")
            signal.issueId?.let { appendLine("Issue: $it") }
            signal.reviewQueueItemId?.let { appendLine("Review queue item: $it") }
            signal.runId?.let { appendLine("Run: $it") }
            appendLine()
            appendLine("Problem detail:")
            appendLine(signal.detail)
            appendLine()
            appendLine("CEO directive:")
            appendLine("- Decide whether this signal represents real work or should be dismissed.")
            appendLine("- If real, create branchable remediation/validation issues with explicit acceptance criteria.")
            appendLine("- Require evidence before marking the remediation complete.")
            appendLine("- Update project/team/agent memory with the decision and residual risk.")
        }
        val goal = createGoal(
            companyId = companyId,
            title = title,
            description = description,
            successMetrics = listOf(
                "The discovery signal is triaged into a concrete decision.",
                "Real problems become scoped remediation or validation issues.",
                "The outcome is recorded in company memory with evidence and residual risk."
            ),
            autonomyEnabled = true,
            priority = when (signal.severity.lowercase()) {
                "critical", "high" -> 1
                "medium" -> 2
                else -> 3
            },
            operatingPolicy = "auto-discovery:${signal.id}",
            startRuntimeIfNeeded = false
        )
        stateMutex.withLock {
            val latest = stateStore.load()
            stateStore.save(
                latest.copy(
                    problemSignals = autonomousDiscoveryService.markTriaged(
                        latest.problemSignals,
                        signal.id,
                        goal.id
                    )
                ).recordSignal(
                    source = "autonomous-discovery",
                    message = "Created CEO triage goal for discovery signal: ${signal.title}",
                    severity = "warning",
                    companyId = companyId,
                    goalId = goal.id,
                    issueId = signal.issueId
                ).withDerivedMetrics()
            )
        }
        return goal
    }

    internal suspend fun synthesizeAutonomousFollowUpGoalForTesting(companyId: String): CompanyGoal? =
        synthesizeAutonomousFollowUpGoal(companyId)

    private fun buildIssueDescription(
        goal: CompanyGoal,
        assignment: AgentAssignmentPlan,
        sharedChecklist: List<String>
    ): String = buildString {
        appendLine("Goal: ${goal.title}")
        appendLine()
        appendLine("Role: ${assignment.role}")
        appendLine("Phase: ${assignment.phase}")
        appendLine("Focus: ${assignment.focus}")
        if (assignment.subtasks.isNotEmpty()) {
            appendLine()
            appendLine("Owned subtasks:")
            assignment.subtasks.forEach { subtask ->
                appendLine("- ${subtask.title}: ${subtask.details}")
            }
        }
        if (sharedChecklist.isNotEmpty()) {
            appendLine()
            appendLine("Shared checklist:")
            sharedChecklist.forEach { item ->
                appendLine("- $item")
            }
        }
        appendLine()
        appendLine("Quality bar:")
        appendLine("- Treat the result as something an end user could actually open and judge, not as a placeholder diff.")
        appendLine("- Do not satisfy the issue with marker comments, README-only edits, or validation-only artifacts unless the issue explicitly asks for that.")
        appendLine("- If this is user-facing UI/web work, deliver a visually coherent result with strong hierarchy, spacing, interaction clarity, and polished states.")
    }.trim()

    private fun buildIssueExecutionPrompt(
        state: DesktopAppState,
        issue: CompanyIssue,
        profile: OrgAgentProfile
    ): String {
        val company = state.companies.firstOrNull { it.id == issue.companyId }
        val goal = state.goals.firstOrNull { it.id == issue.goalId }
        val projectContext = state.projectContexts.firstOrNull { it.id == issue.projectContextId }
        val siblingIssues = state.issues
            .filter { it.goalId == issue.goalId }
            .filterNot { it.id == issue.id }
            .sortedBy { it.createdAt }
            .take(4)
        val memoryBundle = company?.let {
            buildExecutionMemoryBundle(
                state = state,
                company = it,
                projectContext = projectContext,
                goal = goal,
                issue = issue,
                profile = profile
            )
        }
        val relatedExecutionIssue = relatedExecutionIssueId(issue)?.let { executionIssueId ->
            state.issues.firstOrNull { it.id == executionIssueId }
        }
        val goalReviewQueueItems = state.reviewQueue
            .filter { reviewItem ->
                state.issues.firstOrNull { it.id == reviewItem.issueId }?.goalId == issue.goalId
            }
            .sortedByDescending { it.updatedAt }
        val scopedQueueItems = relatedExecutionIssue?.let { executionIssue ->
            goalReviewQueueItems.filter { it.issueId == executionIssue.id }
        } ?: goalReviewQueueItems
        val qaPendingQueueItems = scopedQueueItems
            .filter { it.status == ReviewQueueStatus.AWAITING_QA || it.status == ReviewQueueStatus.FAILED_CHECKS }
        val ceoReadyQueueItems = scopedQueueItems
            .filter { it.status == ReviewQueueStatus.READY_FOR_CEO }
        val scopedExecutionIssueIds = when (issue.kind.lowercase()) {
            "review", "approval" -> relatedExecutionIssue?.id?.let(::setOf) ?: emptySet()
            else -> emptySet()
        }
        val scopedExecutionIssues = state.issues
            .filter {
                it.goalId == issue.goalId &&
                    it.kind.equals("execution", ignoreCase = true) &&
                    (it.status == IssueStatus.IN_REVIEW || it.status == IssueStatus.READY_FOR_CEO || it.status == IssueStatus.DONE) &&
                    (scopedExecutionIssueIds.isEmpty() || it.id in scopedExecutionIssueIds)
            }
            .sortedByDescending { it.updatedAt }
        val queueScopedExecutionEvidence = if (issue.kind.equals("review", ignoreCase = true) || issue.kind.equals("approval", ignoreCase = true)) {
            scopedQueueItems.mapNotNull { reviewItem ->
                val run = state.runs.firstOrNull { it.id == reviewItem.runId && it.status == AgentRunStatus.COMPLETED }
                    ?: return@mapNotNull null
                val executionIssue = state.issues.firstOrNull { it.id == reviewItem.issueId } ?: return@mapNotNull null
                Triple(reviewItem, executionIssue, run)
            }
                .distinctBy { (_, _, run) -> run.id }
                .take(3)
        } else {
            emptyList()
        }
        val completedExecutionRuns = if (queueScopedExecutionEvidence.isNotEmpty()) {
            queueScopedExecutionEvidence.map { (_, executionIssue, completedRun) ->
                buildString {
                    append("- ${executionIssue.title}")
                    append(" [branch: ${completedRun.branchName}]")
                    completedRun.publish?.commitSha?.let { append(" [commit: ${it.take(7)}]") }
                }
            }
        } else {
            scopedExecutionIssues
                .mapNotNull { completedIssue ->
                    val completedTask = state.tasks
                        .filter { it.issueId == completedIssue.id }
                        .maxByOrNull { it.updatedAt }
                        ?: return@mapNotNull null
                    val completedRun = state.runs
                        .filter { it.taskId == completedTask.id && it.status == AgentRunStatus.COMPLETED }
                        .maxByOrNull { it.updatedAt }
                        ?: return@mapNotNull null
                    buildString {
                        append("- ${completedIssue.title}")
                        append(" [branch: ${completedRun.branchName}]")
                        completedRun.publish?.commitSha?.let { append(" [commit: ${it.take(7)}]") }
                    }
                }
                .take(3)
        }
        val completedExecutionEvidence = if (queueScopedExecutionEvidence.isNotEmpty()) {
            queueScopedExecutionEvidence.map { (_, executionIssue, completedRun) ->
                buildString {
                    appendLine("- ${executionIssue.title}")
                    appendLine("  branch: ${completedRun.branchName}")
                    completedRun.publish?.commitSha?.let { appendLine("  commit: ${it.take(7)}") }
                    completedRun.output?.takeIf { it.isNotBlank() }?.let { output ->
                        appendLine("  execution summary: ${summarizeForPrompt(output, 280)}")
                    }
                }.trimEnd()
            }
        } else {
            scopedExecutionIssues
                .mapNotNull { completedIssue ->
                    val completedTask = state.tasks
                        .filter { it.issueId == completedIssue.id }
                        .maxByOrNull { it.updatedAt }
                        ?: return@mapNotNull null
                    val completedRun = state.runs
                        .filter { it.taskId == completedTask.id && it.status == AgentRunStatus.COMPLETED }
                        .maxByOrNull { it.updatedAt }
                        ?: return@mapNotNull null
                    buildString {
                        appendLine("- ${completedIssue.title}")
                        appendLine("  branch: ${completedRun.branchName}")
                        completedRun.publish?.commitSha?.let { appendLine("  commit: ${it.take(7)}") }
                        completedRun.output?.takeIf { it.isNotBlank() }?.let { output ->
                            appendLine("  execution summary: ${summarizeForPrompt(output, 280)}")
                        }
                    }.trimEnd()
                }
                .take(3)
        }
        val completedReviewEvidence = when (issue.kind.lowercase()) {
            "approval" -> ceoReadyQueueItems.map { reviewItem ->
                buildString {
                    appendLine("- issueId: ${reviewItem.issueId}")
                    reviewItem.pullRequestUrl?.let { appendLine("  pr: $it") }
                    reviewItem.qaVerdict?.let { appendLine("  qaVerdict: $it") }
                    reviewItem.qaFeedback?.takeIf { it.isNotBlank() }?.let { feedback ->
                        appendLine("  qaFeedback: ${summarizeForPrompt(feedback, 280)}")
                    }
                }.trimEnd()
            }
                .take(3)
            else ->
                state.issues
                    .filter { it.goalId == issue.goalId && it.kind.equals("review", ignoreCase = true) && it.status == IssueStatus.DONE }
                    .sortedByDescending { it.updatedAt }
                    .mapNotNull { reviewIssue ->
                        val reviewTask = state.tasks
                            .filter { it.issueId == reviewIssue.id }
                            .maxByOrNull { it.updatedAt }
                            ?: return@mapNotNull null
                        val reviewRun = state.runs
                            .filter { it.taskId == reviewTask.id && it.status == AgentRunStatus.COMPLETED }
                            .maxByOrNull { it.updatedAt }
                            ?: return@mapNotNull null
                        buildString {
                            appendLine("- ${reviewIssue.title}")
                            reviewRun.output?.takeIf { it.isNotBlank() }?.let { output ->
                                appendLine("  review summary: ${summarizeForPrompt(output, 280)}")
                            }
                        }.trimEnd()
                    }
                    .take(3)
        }
        val verificationBundle = verificationBundleService.buildForIssue(
            state = state,
            issue = issue,
            queueItem = scopedQueueItems.maxByOrNull { it.updatedAt }
        )
        val userFacingDesignWork = issueNeedsStrongDesignGuidance(issue, profile)
        val ownedMarketingWork = issueNeedsOwnedMarketingGuardrails(issue, profile)
        val promptBody = when (issue.kind.lowercase()) {
            "planning" -> buildCeoPlanningPrompt(state, issue, profile)
            "review" -> buildString {
                appendLine("Company review context")
                company?.let {
                    appendLine("- company: ${it.name}")
                    appendLine("- rootPath: ${it.rootPath}")
                    appendLine("- baseBranch: ${it.defaultBaseBranch}")
                }
                goal?.let { appendLine("- goal: ${it.title}") }
                appendLine("- assignedRole: ${profile.roleName}")
                appendLine()
                appendLine("Review task: ${issue.title}")
                if (completedExecutionRuns.isNotEmpty()) {
                    appendLine()
                    appendLine("Completed execution work to review:")
                    completedExecutionRuns.forEach(::appendLine)
                }
                if (completedExecutionEvidence.isNotEmpty()) {
                    appendLine()
                    appendLine("Execution evidence:")
                    completedExecutionEvidence.forEach(::appendLine)
                }
                val qaPromptQueueItems = qaPendingQueueItems.ifEmpty { goalReviewQueueItems.filter { it.status != ReviewQueueStatus.MERGED } }
                if (qaPromptQueueItems.isNotEmpty()) {
                    appendLine()
                    appendLine("Open pull request handoffs:")
                    qaPromptQueueItems.forEach { reviewItem ->
                        appendLine("- issueId: ${reviewItem.issueId}")
                        reviewItem.branchName?.let { appendLine("  branch: $it") }
                        reviewItem.pullRequestUrl?.let { appendLine("  pr: $it") }
                        reviewItem.checksSummary?.let { appendLine("  checks: ${summarizeForPrompt(it, 220)}") }
                    }
                }
                if (issue.acceptanceCriteria.isNotEmpty()) {
                    appendLine()
                    appendLine("Acceptance criteria:")
                    issue.acceptanceCriteria.forEach { appendLine("- $it") }
                }
                appendLine()
                appendVerificationBundle(verificationBundle)
                appendLine()
                appendLine("Review instructions:")
                appendLine("- Review only the completed execution work listed above.")
                appendLine("- Use the execution summaries above as primary evidence. Only inspect the branch or commit directly if something is unclear.")
                appendLine("- Act as a direct reviewer, not as an orchestrator.")
                appendLine("- Do not create plans, spawn sub-agents, or perform broad repo exploration.")
                appendLine("- Keep the review tight: inspect only the listed execution result and produce one concise verdict.")
                appendLine("- Do not create commits, branches, pushes, or pull requests. Cotor will handle workflow publishing.")
                appendLine("- Do not modify repository files unless a tiny fix is absolutely required to unblock the flow.")
                appendLine("- No publish is required for a pure review step.")
                appendLine("- If the provided execution evidence is sufficient and you do not find a concrete defect, mark the work ready instead of asking for speculative follow-up.")
                appendLine("- If the work is marketing-related, reject generic templates and any out-of-scope paid ads, mass email, DMs, third-party groups, or non-owned-channel posting.")
                appendLine("- The first line of your response must be exactly `QA_VERDICT: PASS` or `QA_VERDICT: CHANGES_REQUESTED`.")
                appendLine("- After the verdict line, return concise feedback, residual risks, and whether the work is ready for CEO approval.")
                memoryBundle?.let { memory ->
                    appendLine()
                    appendLine(renderMemorySections(memory))
                }
            }
            "approval" -> buildString {
                appendLine("Company approval context")
                company?.let {
                    appendLine("- company: ${it.name}")
                    appendLine("- rootPath: ${it.rootPath}")
                    appendLine("- baseBranch: ${it.defaultBaseBranch}")
                }
                goal?.let { appendLine("- goal: ${it.title}") }
                appendLine("- assignedRole: ${profile.roleName}")
                appendLine()
                appendLine("Approval task: ${issue.title}")
                if (completedExecutionEvidence.isNotEmpty()) {
                    appendLine()
                    appendLine("Completed execution evidence:")
                    completedExecutionEvidence.forEach(::appendLine)
                }
                if (completedReviewEvidence.isNotEmpty()) {
                    appendLine()
                    appendLine("Completed review evidence:")
                    completedReviewEvidence.forEach(::appendLine)
                }
                if (ceoReadyQueueItems.isNotEmpty()) {
                    appendLine()
                    appendLine("Pull requests awaiting CEO approval:")
                    ceoReadyQueueItems.forEach { reviewItem ->
                        appendLine("- issueId: ${reviewItem.issueId}")
                        reviewItem.branchName?.let { appendLine("  branch: $it") }
                        reviewItem.pullRequestUrl?.let { appendLine("  pr: $it") }
                        reviewItem.qaVerdict?.let { appendLine("  qaVerdict: $it") }
                        reviewItem.qaFeedback?.let { appendLine("  qaFeedback: ${summarizeForPrompt(it, 220)}") }
                    }
                }
                if (issue.acceptanceCriteria.isNotEmpty()) {
                    appendLine()
                    appendLine("Acceptance criteria:")
                    issue.acceptanceCriteria.forEach { appendLine("- $it") }
                }
                appendLine()
                appendVerificationBundle(verificationBundle)
                appendLine()
                appendLine("Approval instructions:")
                appendLine("- Review the completed execution and review outcomes listed above.")
                appendLine("- Prefer the summaries above over broad repository exploration.")
                appendLine("- Act as a direct approver, not as an orchestrator.")
                appendLine("- Do not create plans, spawn sub-agents, or perform broad repo exploration.")
                appendLine("- Keep the approval tight and decide from the provided evidence unless a concrete inconsistency forces a deeper check.")
                appendLine("- Do not create commits, branches, pushes, or pull requests. Cotor will handle workflow publishing.")
                appendLine("- Do not modify repository files unless a tiny unblocker is required.")
                appendLine("- No publish is required for a pure approval step.")
                appendLine("- The first line of your response must be exactly `CEO_VERDICT: APPROVE` or `CEO_VERDICT: CHANGES_REQUESTED`.")
                appendLine("- After the verdict line, return one concise rationale for merge or rework.")
                memoryBundle?.let { memory ->
                    appendLine()
                    appendLine(renderMemorySections(memory))
                }
            }
            else -> buildString {
                val validationOnlyFollowUp = !requiresCodePublish(issue)
                val conciseCodeExecution = !validationOnlyFollowUp
                if (conciseCodeExecution) {
                    appendLine("Task")
                    appendLine("- Deliver this issue with a real repository change: ${issue.title}")
                    appendLine("- Scope: ${summarizeForPrompt(issue.description, 160)}")
                    appendLine("- Work as a direct implementer. Start editing immediately and do not plan, delegate, or do broad repo exploration.")
                    appendLine("- Only read or write files reachable from the current working directory. Never write to absolute paths, parent directories, or unrelated repository checkouts.")
                    appendLine("- Do not create placeholder diffs, marker comments, README-only edits, or validation-only artifacts.")
                    appendLine("- Keep the result coherent and shippable when opened directly by a user.")
                    appendLine("- ${graphifyKnowledgeGuidance()}")
                    if (userFacingDesignWork) {
                        appendLine("- Design: Berkeley Mono, warm dark surfaces, crisp borders, restrained accents, flat hierarchy, strong spacing rhythm.")
                    }
                    if (ownedMarketingWork) {
                        appendLine("- Marketing guardrails: make the output Cotor-specific, tied to this repository/product evidence, and limited to owned website/CMS plus owned organic social. Do not propose paid ads, mass email, DMs, third-party community/group posting, or generic hashtag/tagging filler.")
                    }
                    appendLine("- Run one targeted validation command after the change, report the result, and stop.")
                    return@buildString
                }
                appendLine("Company execution context")
                company?.let {
                    appendLine("- company: ${it.name}")
                    if (validationOnlyFollowUp) {
                        appendLine("- rootPath: ${it.rootPath}")
                        appendLine("- baseBranch: ${it.defaultBaseBranch}")
                    }
                }
                projectContext?.takeIf { validationOnlyFollowUp }?.let {
                    appendLine("- projectContext: ${it.name}")
                }
                goal?.let {
                    appendLine("- goal: ${it.title}")
                    appendLine("- goalDescription: ${summarizeForPrompt(it.description, if (conciseCodeExecution) 120 else 240)}")
                }
                appendLine("- assignedRole: ${profile.roleName}")
                appendLine()
                appendLine("Task")
                if (validationOnlyFollowUp) {
                    appendLine("- Prefer structured A2A communication whenever the runtime bridge is available: use note/warning/feedback/handoff/escalation/accept message types instead of stdout conventions.")
                    appendLine("- Treat legacy output markers like CONTEXT_NOTE:, CONTEXT_HANDOFF:, MESSAGE_TO, and ESCALATION as compatibility fallback only when the runtime bridge is unavailable.")
                } else {
                    appendLine("- Use normal repository edits only. Do not add marker comments, placeholder text, or README-only artifacts.")
                    appendLine("- Keep the result shippable and coherent when a user opens it directly.")
                }
                if (validationOnlyFollowUp) {
                    appendLine("- Re-run the smallest validation needed for this issue and capture exact evidence: ${issue.title}")
                    appendLine("- Stay inside the current worktree only. Do not inspect parent directories or unrelated repositories.")
                    appendLine("- Read only the smallest file set needed for evidence. Prefer README.md, VALIDATION.md, NEXT_ISSUES.md, and the main product entry file if they exist.")
                    appendLine("- Do not run broad discovery commands like find, rg across the repo, or git history scans unless the needed file is truly missing.")
                    appendLine("- Do not edit files unless the issue explicitly requires correcting a proven mismatch in the current worktree.")
                } else {
                    appendLine("- Deliver this issue: ${issue.title}")
                    appendLine("- Scope: ${summarizeForPrompt(issue.description, 220)}")
                }
                appendLine("- Act as a direct worker. Do not act like a planner or orchestrator.")
                appendLine(if (validationOnlyFollowUp) "- Start validating immediately. Do not spend time on broad repo exploration." else "- Start editing immediately. Do not spend time on broad repo exploration.")
                appendLine("- Do not create plans, spawn sub-agents, or do broad multi-step analysis.")
                if (validationOnlyFollowUp) {
                    appendLine("- If you need to tell another agent something important, send a concise structured A2A note/warning/feedback/handoff/escalation/accept signal instead of burying it in long free-form output.")
                }
                if (validationOnlyFollowUp) {
                    appendLine("- Do not create README-only, VALIDATION.md-only, or other placeholder repository changes just to produce a diff.")
                    appendLine("- If the branch already contains the right evidence, leave files untouched and report the findings precisely.")
                    appendLine("- No publish is required for a pure validation or residual-risk follow-up.")
                    appendLine("- Run exactly one targeted validation command, summarize the result, and stop.")
                    appendLine("- If you can already verify the issue from the visible files in the current worktree, stop immediately after that validation instead of continuing to explore.")
                } else {
                    appendLine("- If there is no legitimate product change to make, do not manufacture README-only or placeholder artifacts just to force a diff; report the blocker instead.")
                }
                if (!validationOnlyFollowUp) {
                    appendLine("- Run one targeted validation command that proves the change works, then stop.")
                }
                if (!validationOnlyFollowUp) {
                    appendLine()
                    appendLine("Output quality requirements:")
                    appendLine("- Produce a real user-facing result, not a placeholder or proof marker.")
                    appendLine("- Do not use validation comments, fake TODO markers, README-only edits, or cosmetic no-op diffs as the deliverable.")
                    appendLine("- Prefer one cohesive, usable slice over many partial or decorative changes.")
                }
                if (!validationOnlyFollowUp && userFacingDesignWork) {
                    appendLine()
                    appendLine("Design direction for this user-facing result:")
                    appendLine("- Use an OpenCode-style visual system: Berkeley Mono, warm dark surfaces, crisp borders, restrained accent colors, flat hierarchy, and strong spacing rhythm.")
                    appendLine("- Avoid generic gradients, glassmorphism, oversized radii, random ornaments, and placeholder demo copy.")
                }
                if (!validationOnlyFollowUp && ownedMarketingWork) {
                    appendLine()
                    appendLine("Marketing quality requirements:")
                    appendLine("- Make the deliverable specific to Cotor, the selected company, and the repository evidence visible in this worktree.")
                    appendLine("- Stay inside owned website/CMS and owned organic social channels only.")
                    appendLine("- Do not propose or perform paid ads, budget changes, mass email, DMs, third-party group/community posting, scraping, or account changes.")
                    appendLine("- Avoid generic launch-plan filler, vague relevant groups, and empty hashtag/tagging lists unless the owned channel policy explicitly names them.")
                }
                issue.qaFeedback?.takeIf { it.isNotBlank() }?.let { feedback ->
                    appendLine()
                    appendLine("Latest QA feedback:")
                    appendLine(summarizeForPrompt(feedback, 240))
                }
                issue.ceoFeedback?.takeIf { it.isNotBlank() }?.let { feedback ->
                    appendLine()
                    appendLine("Latest CEO feedback:")
                    appendLine(summarizeForPrompt(feedback, 240))
                }
                if (validationOnlyFollowUp && siblingIssues.isNotEmpty()) {
                    appendLine()
                    appendLine("Parallel issues in the same goal:")
                    siblingIssues.forEach { sibling ->
                        appendLine("- ${sibling.title} [${sibling.status}]")
                    }
                }
                appendLine()
                appendLine("Rules")
                appendLine("- Work in the assigned isolated branch and worktree.")
                appendLine("- Do not create commits, branches, pushes, or pull requests. Cotor will publish after you finish.")
                appendLine("- Keep the change minimal and focused on this issue.")
                if (issue.acceptanceCriteria.isNotEmpty()) {
                    appendLine()
                    appendLine("Done when:")
                    issue.acceptanceCriteria.forEach { appendLine("- $it") }
                }
                if (validationOnlyFollowUp) {
                    appendLine()
                    appendVerificationBundle(verificationBundle)
                    memoryBundle?.let { memory ->
                        appendLine()
                        appendLine(renderMemorySections(memory))
                    }
                }
            }
        }
        return promptBody.trim()
    }

    private fun issueNeedsStrongDesignGuidance(issue: CompanyIssue, profile: OrgAgentProfile): Boolean {
        val issueText = buildString {
            append(issue.title)
            append(' ')
            append(issue.description)
            append(' ')
            append(profile.roleName)
            append(' ')
            append(profile.capabilities.joinToString(" "))
        }.lowercase()

        val designKeywords = listOf(
            "ui", "ux", "design", "visual", "frontend", "front-end", "landing",
            "page", "web", "website", "html", "hero", "layout", "interaction"
        )
        return designKeywords.any { it in issueText }
    }

    private fun issueNeedsOwnedMarketingGuardrails(issue: CompanyIssue, profile: OrgAgentProfile): Boolean {
        val issueText = buildString {
            append(issue.title)
            append(' ')
            append(issue.description)
            append(' ')
            append(profile.roleName)
            append(' ')
            append(profile.capabilities.joinToString(" "))
            append(' ')
            append(issue.acceptanceCriteria.joinToString(" "))
        }.lowercase()
        return listOf("marketing", "content", "social", "owned", "launch", "마케팅", "콘텐츠", "소셜").any { it in issueText }
    }

    private data class CompanyMemorySnapshot(
        val companyMemory: String,
        val projectMemory: String,
        val teamMemory: String,
        val workflowMemory: String,
        val agentMemory: String
    )

    private fun CompanyMemorySnapshot.toResponse(): CompanyMemorySnapshotResponse = CompanyMemorySnapshotResponse(
        companyMemory = sanitizeUserFacingMemoryText(companyMemory),
        workflowMemory = sanitizeUserFacingMemoryText(workflowMemory),
        agentMemory = sanitizeUserFacingMemoryText(agentMemory),
        projectMemory = sanitizeUserFacingMemoryText(projectMemory),
        teamMemory = sanitizeUserFacingMemoryText(teamMemory)
    )

    private fun CompanyMemorySnapshot.toInternalResponse(): CompanyMemorySnapshotResponse = CompanyMemorySnapshotResponse(
        companyMemory = companyMemory,
        workflowMemory = workflowMemory,
        agentMemory = agentMemory,
        projectMemory = projectMemory,
        teamMemory = teamMemory
    )

    private data class CompanyMemoryFact(
        val layer: CompanyMemoryLayer,
        val key: String,
        val value: String,
        val source: String,
        val confidence: Double,
        val freshness: Long,
        val conflictStatus: String = "CLEAR"
    ) {
        fun render(): String =
            "$key=$value | source=$source | confidence=${"%.2f".format(confidence)} | freshness=$freshness | conflict=$conflictStatus"
    }

    private fun sanitizeUserFacingMemoryText(text: String): String =
        text.lineSequence()
            .mapNotNull { line ->
                val trimmed = line.trim()
                when {
                    trimmed.startsWith("graphify=") -> null
                    trimmed.startsWith("rootPath=") -> "workspace=${trimmed.substringAfterLast('/').ifBlank { trimmed.removePrefix("rootPath=") }}"
                    else -> sanitizeUserFacingMemoryLine(line)
                }
            }
            .joinToString("\n")

    private fun sanitizeUserFacingMemoryLine(line: String): String {
        var sanitized = line.replace(Regex(" \\| source=.*$"), "")
            .replace("Created infra issue:", "Created connection issue:")
            .replace("Blocked code issue:", "Code work is waiting:")
            .replace("Created CEO planning issue:", "Prepared CEO work plan:")
            .replace("Reopened CEO planning issue:", "Reopened CEO work plan:")
            .replace("Started CEO planning:", "CEO started planning:")
            .replace(
                "GitHub is not connected. Configure an existing origin remote before starting GitHub PR work.",
                "Connect an existing GitHub repository before starting PR-based code work. Cotor will not create one automatically."
            )
            .replace(
                "GitHub PR mode requires an existing origin remote. Cotor will not create a GitHub repository automatically.",
                "Connect an existing GitHub repository before starting PR-based code work. Cotor will not create one automatically."
            )
        val restorePattern = Regex("Restore GitHub publishing for ([^|\\n]+)")
        while (restorePattern.containsMatchIn(sanitized)) {
            sanitized = restorePattern.replace(sanitized) { match ->
                "Connect GitHub for ${match.groupValues[1].trim()}"
            }
        }
        return sanitized
    }

    private fun renderMemorySections(memory: CompanyMemorySnapshot): String = buildString {
        appendLine("Company memory:")
        appendLine(summarizeForPrompt(memory.companyMemory, 180))
        appendLine()
        appendLine("Workflow memory:")
        appendLine(summarizeForPrompt(memory.workflowMemory, 320))
        appendLine()
        appendLine("Project memory:")
        appendLine(summarizeForPrompt(memory.projectMemory, 260))
        appendLine()
        appendLine("Team memory:")
        appendLine(summarizeForPrompt(memory.teamMemory, 260))
        appendLine()
        appendLine("Agent memory:")
        appendLine(summarizeForPrompt(memory.agentMemory, 220))
    }.trimEnd()

    private fun renderPlanningMemorySections(memory: CompanyMemorySnapshot): String =
        renderMemorySections(
            memory.copy(
                companyMemory = redactPlanningMemoryForProvider(memory.companyMemory),
                workflowMemory = redactPlanningMemoryForProvider(memory.workflowMemory),
                projectMemory = redactPlanningMemoryForProvider(memory.projectMemory),
                teamMemory = redactPlanningMemoryForProvider(memory.teamMemory),
                agentMemory = redactPlanningMemoryForProvider(memory.agentMemory)
            )
        )

    private fun redactPlanningMemoryForProvider(text: String): String =
        text.lineSequence()
            .mapNotNull { line ->
                val trimmed = line.trim()
                when {
                    trimmed.startsWith("rootPath=") -> null
                    else -> line
                }
            }
            .joinToString("\n")

    private fun buildCompanyMemorySnapshot(
        state: DesktopAppState,
        company: Company,
        projectContext: CompanyProjectContext?,
        goal: CompanyGoal?,
        issue: CompanyIssue?,
        profile: OrgAgentProfile
    ): CompanyMemorySnapshot {
        val companyGoals = state.goals
            .filter { it.companyId == company.id && it.status != GoalStatus.COMPLETED }
            .sortedByDescending { it.updatedAt }
            .take(3)
        val goalIssues = goal
            ?.let { activeGoal ->
                state.issues
                    .filter { it.goalId == activeGoal.id }
                    .sortedByDescending { it.updatedAt }
                    .take(5)
            }
            .orEmpty()
        val recentActivity = state.companyActivity
            .filter { it.companyId == company.id }
            .sortedByDescending { it.createdAt }
            .take(5)
        val recentDecisions = state.goalDecisions
            .filter { it.companyId == company.id }
            .sortedByDescending { it.createdAt }
            .take(3)
        val recentContextEntries = state.agentContextEntries
            .filter {
                it.companyId == company.id &&
                    (
                        issue?.id?.let { issueId -> it.issueId == issueId } == true ||
                            goal?.id?.let { goalId -> it.goalId == goalId } == true ||
                            it.visibility == "company"
                        )
            }
            .sortedByDescending { it.createdAt }
            .take(5)
        val recentMessages = state.agentMessages
            .filter {
                it.companyId == company.id &&
                    (
                        issue?.id?.let { issueId -> it.issueId == issueId } == true ||
                            goal?.id?.let { goalId -> it.goalId == goalId } == true
                        )
            }
            .sortedByDescending { it.createdAt }
            .take(5)
        val retrievedKnowledge = issue
            ?.let { knowledgeService.retrieveForExecution(it.id, company.id).take(3) }
            .orEmpty()
        val assignedIssues = state.issues
            .filter { it.companyId == company.id && it.assigneeProfileId == profile.id }
            .sortedByDescending { it.updatedAt }
            .take(3)
        val collaboratorIds = state.companyAgentDefinitions
            .firstOrNull { it.companyId == company.id && it.id == profile.id }
            ?.preferredCollaboratorIds
            .orEmpty()
        val collaboratorNames = state.companyAgentDefinitions
            .filter { it.companyId == company.id && it.id in collaboratorIds }
            .map { it.title }
        val agentDefinition = issue
            ?.let { resolveCompanyAgentDefinition(state, it, profile, profile.executionAgentName) }
            ?: state.companyAgentDefinitions.firstOrNull { definition ->
                definition.companyId == company.id &&
                    (
                        definition.id == profile.id ||
                            definition.title.equals(profile.roleName, ignoreCase = true) ||
                            definition.agentCli.equals(profile.executionAgentName, ignoreCase = true)
                        )
            }
        val mentorName = state.companyAgentDefinitions
            .firstOrNull { it.companyId == company.id && it.id == agentDefinition?.mentorAgentId }
            ?.title
        val now = System.currentTimeMillis()
        fun fact(
            layer: CompanyMemoryLayer,
            key: String,
            value: String,
            source: String,
            confidence: Double,
            freshness: Long = now,
            conflictStatus: String = "CLEAR"
        ): CompanyMemoryFact =
            CompanyMemoryFact(layer, key, value, source, confidence, freshness, conflictStatus)
        fun renderFacts(layer: CompanyMemoryLayer, facts: List<CompanyMemoryFact>): String =
            facts.filter { it.layer == layer && it.value.isNotBlank() }
                .joinToString("\n") { it.render() }
                .ifBlank { "No ${layer.name.lowercase()} memory recorded yet." }

        val memoryFacts = buildList {
            add(fact(CompanyMemoryLayer.COMPANY, "company", company.name, "company-state", 1.0, company.updatedAt))
            add(fact(CompanyMemoryLayer.COMPANY, "rootPath", company.rootPath, "company-state", 1.0, company.updatedAt))
            add(fact(CompanyMemoryLayer.COMPANY, "defaultBaseBranch", company.defaultBaseBranch, "company-state", 0.95, company.updatedAt))
            add(fact(CompanyMemoryLayer.COMPANY, "activeGoals", companyGoals.joinToString { it.title }, "goal-state", 0.85))
            add(
                fact(
                    CompanyMemoryLayer.COMPANY,
                    "recentActivity",
                    recentActivity.joinToString(" | ") { "${it.title}${it.detail?.let { detail -> ": $detail" } ?: ""}" },
                    "activity-feed",
                    0.8
                )
            )
            add(fact(CompanyMemoryLayer.PROJECT, "projectContext", projectContext?.name.orEmpty(), "project-context", 0.85, projectContext?.lastUpdatedAt ?: now))
            goal?.let {
                add(fact(CompanyMemoryLayer.PROJECT, "goal", it.title, "goal-state", 0.9, it.updatedAt))
                add(fact(CompanyMemoryLayer.PROJECT, "goalDescription", it.description.lineSequence().firstOrNull().orEmpty(), "goal-state", 0.75, it.updatedAt))
            }
            if (issue != null) {
                add(fact(CompanyMemoryLayer.PROJECT, "issue", issue.title, "issue-state", 0.9, issue.updatedAt))
                add(fact(CompanyMemoryLayer.PROJECT, "issueStatus", issue.status.name, "issue-state", 0.95, issue.updatedAt))
            } else {
                add(fact(CompanyMemoryLayer.PROJECT, "issueContext", "No active issue selected.", "issue-state", 0.75))
            }
            add(
                fact(
                    CompanyMemoryLayer.PROJECT,
                    "goalIssues",
                    goalIssues.joinToString(" | ") { "${it.title} [${it.status}]" },
                    "issue-graph",
                    0.8
                )
            )
            add(fact(CompanyMemoryLayer.PROJECT, "graphify", graphifyKnowledgeGuidance(), "graphify", 0.7))
            if (retrievedKnowledge.isNotEmpty()) {
                add(
                    fact(
                        CompanyMemoryLayer.PROJECT,
                        "knowledge",
                        retrievedKnowledge.joinToString(" | ") {
                            "${it.kind}:${summarizeForPrompt(it.content, 120)}"
                        },
                        "knowledge-store",
                        retrievedKnowledge.maxOfOrNull { it.confidence } ?: 0.6,
                        retrievedKnowledge.maxOfOrNull { it.freshness } ?: now,
                        retrievedKnowledge.map { it.conflictStatus.name }.distinct().joinToString("+")
                    )
                )
            }
            add(
                fact(
                    CompanyMemoryLayer.TEAM,
                    "recentDecisions",
                    recentDecisions.joinToString(" | ") { it.summary },
                    "ceo-decisions",
                    0.8
                )
            )
            if (recentContextEntries.isNotEmpty()) {
                add(
                    fact(
                        CompanyMemoryLayer.TEAM,
                        "handoffs",
                        recentContextEntries.joinToString(" | ") { "${it.agentName}:${it.kind}:${summarizeForPrompt(it.content, 120)}" },
                        "agent-context",
                        0.85,
                        recentContextEntries.maxOf { it.createdAt }
                    )
                )
            }
            if (recentMessages.isNotEmpty()) {
                add(
                    fact(
                        CompanyMemoryLayer.TEAM,
                        "recentMessages",
                        recentMessages.joinToString(" | ") { "${it.fromAgentName}->${it.toAgentName ?: "all"}:${summarizeForPrompt(it.body, 120)}" },
                        "agent-message",
                        0.8,
                        recentMessages.maxOf { it.createdAt }
                    )
                )
            }
            add(fact(CompanyMemoryLayer.AGENT, "role", profile.roleName, "agent-profile", 0.95))
            add(fact(CompanyMemoryLayer.AGENT, "agentCli", profile.executionAgentName, "agent-profile", 0.95))
            add(fact(CompanyMemoryLayer.AGENT, "capabilities", profile.capabilities.joinToString(), "agent-profile", 0.85))
            agentDefinition?.roleSummary?.takeIf { it.isNotBlank() }?.let {
                add(fact(CompanyMemoryLayer.AGENT, "roleSummary", it, "agent-definition", 0.85, agentDefinition.updatedAt))
            }
            agentDefinition?.memoryNotes?.takeIf { it.isNotBlank() }?.let {
                add(fact(CompanyMemoryLayer.AGENT, "memoryNotes", summarizeForPrompt(it, 160), "agent-definition", 0.75, agentDefinition.updatedAt))
            }
            mentorName?.takeIf { it.isNotBlank() }?.let {
                add(fact(CompanyMemoryLayer.AGENT, "mentor", it, "agent-definition", 0.82, agentDefinition?.updatedAt ?: now))
            }
            add(
                fact(
                    CompanyMemoryLayer.AGENT,
                    "assignedIssues",
                    assignedIssues.joinToString(" | ") { "${it.title} [${it.status}]" },
                    "issue-assignment",
                    0.8
                )
            )
            if (collaboratorNames.isNotEmpty()) {
                add(fact(CompanyMemoryLayer.AGENT, "preferredCollaborators", collaboratorNames.joinToString(), "agent-definition", 0.8))
            }
        }
        val companyMemory = renderFacts(CompanyMemoryLayer.COMPANY, memoryFacts)
        val projectMemory = renderFacts(CompanyMemoryLayer.PROJECT, memoryFacts)
        val teamMemory = renderFacts(CompanyMemoryLayer.TEAM, memoryFacts)
        val agentMemory = renderFacts(CompanyMemoryLayer.AGENT, memoryFacts)
        val workflowMemory = buildString {
            appendLine(projectMemory)
            appendLine(teamMemory)
        }.trim()

        return CompanyMemorySnapshot(
            companyMemory = companyMemory,
            projectMemory = projectMemory,
            teamMemory = teamMemory,
            workflowMemory = workflowMemory,
            agentMemory = agentMemory
        )
    }

